	MOVL  $8, DX
	SUBQ  CX, AX
	ADDL  $1, AX
	CMPL  AX, DX
	CMOVLHI DX, AX
	LEAL  (AX)(R10*1), DX
	CMPL  R10, DX
	JCC   upd
	MOVQ  R13, 0x58(SP)
	MOVL  R10, R12
	MOVQ  0x20(SP), R15
	MOVL  DX, 0x40(SP)
	MOVQ  R8, 0x50(SP)
	MOVQ  CX, R8
	MOVL  0x2c(SP), CX
	PCALIGN $16

fill:
	MOVQ  $0x9e3779b100000000, DX
	IMULQ (R8), DX
	ADDQ  $1, R8
	XORQ  R15, DX
	SHRQ  CX, DX
	MOVL  DX, AX
	SHRL  $8, AX
	SHLL  $4, AX
	LEAQ  (AX*4), R13
	PREFETCHT0 (BP)(AX*1)
	MOVL  R12, AX
	ANDL  $7, AX
	ADDL  $1, R12
	PREFETCHT0 (BX)(R13*1)
	MOVL  DX, (R14)(AX*4)
	CMPL  R12, 0x40(SP)
	JCS   fill
	MOVQ  0x50(SP), R8
	MOVQ  0x58(SP), R13
	JMP   upd

cmpdict:
	// C: match = dictBase + matchIndex; read32(match) == read32(ip), then
	// ZSTD_count_2segments(ip+4, match+4, iLimit, dictEnd, prefixStart) + 4.
	// The candidate is at most dictLimit - 4 (C: by table construction;
	// else bad, where the Go code reads past d's slice); lowLimit <= it
	// and lowLimit >= dictBaseIdx (lazyRowExtRun), so it lies in
	// d[lowLimit-dictBaseIdx:dictEnd-4], and the count reads d only up to
	// dictEnd, then b from prefixStart, no further than iLimit from ip.
	MOVL  AX, DI
	MOVL  AX, R11
	SUBL  400(SP), R11
	CMPL  R11, $-3
	JCC   bad
	ADDQ  376(SP), AX       // match
	MOVL  (AX), R11
	CMPL  R11, (SI)
	JNE   next
	MOVQ  BX, 408(SP)
	MOVQ  CX, 416(SP)
	MOVQ  R10, 424(SP)
	MOVQ  DX, 432(SP)
	MOVQ  DI, 440(SP)
	LEAQ  4(SI), R9
	LEAQ  4(AX), R10
	MOVQ  384(SP), R13
	SUBQ  R10, R13
	MOVQ  0(SP), CX
	SUBQ  R9, CX
	CMPQ  CX, R13
	CMOVQLT CX, R13         // min(dictEnd - match, iLimit - ip) bytes
	MOVQ  R10, 448(SP)
	CALL  ·fastCount(SB)
	MOVQ  448(SP), R10
	ADDQ  R11, R10
	CMPQ  R10, 384(SP)
	JNE   dictcnt           // the match ends before dictEnd
	MOVQ  R11, 448(SP)
	LEAQ  4(SI)(R11*1), R9
	MOVQ  392(SP), R10      // it goes on at prefixStart
	MOVQ  0(SP), R13
	SUBQ  R9, R13
	CALL  ·fastCount(SB)
	ADDQ  448(SP), R11

dictcnt:
	LEAQ  4(R11), AX        // currentMl
	MOVQ  408(SP), BX
	MOVQ  416(SP), CX
	MOVQ  424(SP), R10
	MOVQ  432(SP), DX
	MOVQ  440(SP), DI
	JMP   counted

none:
	MOVL  $3, CX
	JMP   done

bad:
	MOVQ  368(SP), R15
	MOVQ  P_B, SI
	MOVQ  $-1, AX
	RET

// func lazyRowExt44(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_extDict_generic (row) for mls 4, rowLog 4:
// compressBlockLazyExtDictGeneric's match loop, with the repcode checks
// (REPLEN), the catch up and the lazy skipping step of the extDict parser.
// R15 = p, SI = b; prefixLowest is unused (the frame holds the segments).
// The repcodes live in the rep1/rep2 argument slots, the anchor and counts in
// their result slots. nSeq = -1 reports a table entry at or after the
// position searched (impossible).
TEXT ·lazyRowExt44(SB), NOSPLIT, $128-128
	MOVQ p+0(FP), R15
	MOVQ P_B, SI
	MOVQ P_DICTBASE, AX
	MOVL P_DICTBASEIDX, CX
	SUBQ CX, AX
	MOVQ AX, L_DBIAS
	MOVL P_LOWEST, CX
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_DSTARTP
	MOVL P_DICTLIMIT, CX
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_DENDP
	MOVQ SI, AX
	MOVL P_BASEIDX, DX
	SUBQ DX, AX
	MOVQ AX, L_BBIAS
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_PSTARTP
	MOVQ iend+40(FP), AX
	ADDQ SI, AX
	MOVQ AX, L_IENDP
	MOVQ ip+24(FP), AX
	MOVQ AX, L_IP
	MOVQ anchor+32(FP), AX
	MOVQ AX, anchorOut+88(FP)
	MOVQ $0, nSeq+96(FP)
	MOVQ $0, nLits+104(FP)
	MOVL $0, llType+120(FP)
	MOVL $0, llPos+124(FP)

main:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  finish
	MOVQ $0, L_MLEN
	MOVQ $1, L_OFFBASE      // repcode1ToOffBase
	LEAQ 1(R8), AX
	MOVQ AX, L_START

	// repcode at ip+1
	INCQ  R8
	MOVL  rep1+64(FP), DX
	REPLEN(r0none, r0c1, r0d1, r0c2, r0d2, r0cd, r0done)
	TESTQ R11, R11
	JEQ   search0
	MOVQ  R11, L_MLEN
	CMPQ  depth+72(FP), $0
	JEQ   store

search0:
	MOVQ L_IP, DI
	CALL ·rowSearchExt44(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, L_MLEN
	JLE  nobetter0
	MOVQ AX, L_MLEN
	MOVQ L_IP, CX
	MOVQ CX, L_START
	MOVQ BX, L_OFFBASE

nobetter0:
	CMPQ L_MLEN, $4
	JGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	MOVQ L_IP, AX
	MOVQ AX, CX
	SUBQ anchorOut+88(FP), CX
	SARQ $8, CX              // kSearchStrength
	LEAQ 1(AX)(CX*1), AX     // ip += step + 1; lazySkipping = step > kLazySkippingStep
	MOVQ AX, L_IP
	XORL DX, DX
	CMPQ CX, $8              // kLazySkippingStep
	SETHI DX
	MOVL DX, P_SKIP
	JMP  main

found:
	CMPQ depth+72(FP), $0
	JEQ  catchup

lazy:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch1
	MOVL  rep1+64(FP), DX
	REPLEN(r1none, r1c1, r1d1, r1c2, r1d2, r1cd, r1done)
	TESTQ R11, R11           // mlRep
	JEQ   lsearch1
	LEAQ  (R11)(R11*2), AX   // gain2
	MOVQ  L_MLEN, CX
	LEAQ  (CX)(CX*2), CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX                 // gain1
	CMPQ  AX, CX
	JLE   lsearch1
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch1:
	MOVQ L_IP, DI
	CALL ·rowSearchExt44(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $4, CX
	CMPQ DX, CX
	JLE  ldepth2
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

ldepth2:
	CMPQ depth+72(FP), $2
	JNE  catchup
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch2
	MOVL  rep1+64(FP), DX
	REPLEN(r2none, r2c1, r2d1, r2c2, r2d2, r2cd, r2done)
	TESTQ R11, R11
	JEQ   lsearch2
	MOVQ  R11, AX
	SHLQ  $2, AX
	MOVQ  L_MLEN, CX
	SHLQ  $2, CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX
	CMPQ  AX, CX
	JLE   lsearch2
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch2:
	MOVQ L_IP, DI
	CALL ·rowSearchExt44(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $7, CX
	CMPQ DX, CX
	JLE  catchup
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

catchup:
	MOVQ L_OFFBASE, DX
	CMPQ DX, $3
	JLS  store              // a repcode: no catch up
	SUBQ $3, DX             // offset
	MOVQ L_START, R8
	MOVQ L_MLEN, AX
	// matchIndex = idx(start) - offset, in the extDict (from dictStart) or
	// the prefix (from prefixStart)
	MOVL    P_BASEIDX, CX
	ADDL    R8, CX
	SUBL    DX, CX
	MOVQ    L_BBIAS, R10
	MOVQ    L_PSTARTP, R9
	CMPL    CX, P_DICTLIMIT
	CMOVQCS L_DBIAS, R10
	CMOVQCS L_DSTARTP, R9
	ADDQ    CX, R10         // match

back:
	CMPQ    R8, anchorOut+88(FP)
	JLE     backdone
	CMPQ    R10, R9
	JLS     backdone
	MOVBLZX -1(SI)(R8*1), BX
	MOVBLZX -1(R10), CX
	CMPL    BX, CX
	JNE     backdone
	DECQ    R8
	DECQ    R10
	INCQ    AX
	JMP     back

backdone:
	MOVQ R8, L_START
	MOVQ AX, L_MLEN
	MOVL rep1+64(FP), CX
	MOVL CX, rep2+68(FP)    // offset2 = offset1
	MOVL DX, rep1+64(FP)    // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVQ L_START, R9
	SUBQ anchorOut+88(FP), R9
	MOVQ L_OFFBASE, R12
	MOVQ L_MLEN, AX
	MOVQ $0, L_RET
	JMP  storeseq

afterstore:
	MOVQ L_START, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	CMPL P_SKIP, $0
	JEQ  reploop
	// leave lazy skipping: ZSTD_row_fillHashCache(ms, base, rowLog, mls, nextToUpdate, ilimit)
	MOVL $0, P_SKIP
	MOVQ P_NEXT, AX
	MOVL (AX), R8            // idx
	MOVL R8, AX
	SUBL P_BASEIDX, AX       // its position
	MOVQ ilimit+48(FP), BX
	SUBQ AX, BX
	JLT  reploop             // idx beyond ilimit: nothing to fill
	INCQ BX
	CMPQ BX, $8
	JLE  fillcnt
	MOVQ $8, BX

fillcnt:
	MOVQ P_CACHE, DX

fillloop:
	MOVL R8, AX
	SUBL P_BASEIDX, AX
	MOVQ (SI)(AX*1), R10
	MOVQ $0x9e3779b100000000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $4, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	MOVL R8, AX
	ANDL $7, AX
	MOVL R10, (DX)(AX*4)
	INCL R8
	DECQ BX
	JNE  fillloop

reploop:
	// while ip <= ilimit: ml = repMatchLength(ip, idx(ip), offset2), until 0
	MOVQ  L_IP, R8
	CMPQ  R8, ilimit+48(FP)
	JGT   main
	MOVL  rep2+68(FP), DX
	REPLEN(r3none, r3c1, r3d1, r3c2, r3d2, r3cd, r3done)
	TESTQ R11, R11
	JEQ   main
	MOVQ  R11, AX            // matchLength
	MOVL  rep2+68(FP), CX    // swap repcodes
	MOVL  rep1+64(FP), DX
	MOVL  DX, rep2+68(FP)
	MOVL  CX, rep1+64(FP)
	MOVQ  AX, L_MLEN
	XORL  R9, R9             // no literals
	MOVL  $1, R12            // repcode1ToOffBase
	MOVQ  $1, L_RET
	JMP   storeseq

afterrep:
	MOVQ L_IP, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	JMP  reploop

	// storeseq: R9 litLen (from anchor), R12 offBase, AX matchLength;
	// returns to afterstore (L_RET = 0) or afterrep (L_RET = 1).
storeseq:
	TESTQ R9, R9
	JEQ   seq
	MOVQ  lits+16(FP), R10
	ADDQ  nLits+104(FP), R10
	MOVQ  anchorOut+88(FP), R11
	ADDQ  R9, nLits+104(FP)
	// up to 16 literals: one 16-byte copy (C: ZSTD_storeSeq's ZSTD_copy16).
	// The literal buffer has 16 bytes of slack (the Run functions check),
	// and the source must hold the 16 bytes (else fastCopyLits).
	CMPQ  R9, $16
	JA    litcall
	LEAQ  16(R11), CX
	CMPQ  CX, iend+40(FP)
	JA    litcall
	MOVOU (SI)(R11*1), X0
	MOVOU X0, (R10)
	JMP   seq

litcall:
	ADDQ  SI, R11
	CALL  ·fastCopyLits(SB)

seq:
	MOVQ seqs+8(FP), R10
	MOVQ nSeq+96(FP), R11
	MOVL R12, (R10)(R11*8)
	MOVW R9, 4(R10)(R11*8)
	LEAQ -3(AX), CX
	MOVW CX, 6(R10)(R11*8)
	CMPQ R9, $0xFFFF
	JLS  nolongll
	MOVL $1, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongll:
	CMPQ CX, $0xFFFF
	JLS  nolongml
	MOVL $2, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongml:
	INCQ R11
	MOVQ R11, nSeq+96(FP)
	CMPQ L_RET, $0
	JEQ  afterstore
	JMP  afterrep

finish:
	MOVQ L_IP, AX
	MOVQ AX, ipOut+80(FP)
	MOVL rep1+64(FP), AX
	MOVL AX, rep1Out+112(FP)
	MOVL rep2+68(FP), AX
	MOVL AX, rep2Out+116(FP)
	RET

bad:
	MOVQ $-1, nSeq+96(FP)
	RET

// rowSearchExt45: rowFindBestMatchExtDict (mls 4, rowLog 5) at DI = ip,
// R15 = p: rowSearch45 with the candidates below p.dictLimit read in
// the extDict (see EXTDICT in the header).
// Returns AX = ml (below 4: none; -1: a table entry at or after ip, or in
// the extDict's last 3 bytes, impossible), BX = offBase, SI = b. Clobbers
// everything but R15.
// Frame: as rowSearch45, then 376 d - dictBaseIdx, 384 the address of
// dictEnd, 392 of prefixStart, 400 dictLimit, 408-447 spills, 448 a count.
TEXT ·rowSearchExt45(SB), NOSPLIT, $456-0
	MOVQ R15, 368(SP)
	MOVQ R15, R9
	MOVQ Q_B, SI
	MOVQ SI, DX
	ADDQ DI, SI             // ip
	ADDQ Q_ILIMIT, DX       // iLimit
	MOVL $999999999, 8(SP)  // offBaseNotFound
	MOVQ Q_B, R8
	MOVL Q_BASEIDX, AX
	SUBQ AX, R8             // base: an index addresses it directly
	MOVQ Q_DICTBASE, AX
	MOVL Q_DICTBASEIDX, CX
	SUBQ CX, AX
	MOVQ AX, 376(SP)        // d - dictBaseIdx: an extDict index addresses it
	MOVL Q_DICTLIMIT, CX
	MOVL CX, 400(SP)
	ADDQ CX, AX
	MOVQ AX, 384(SP)        // the address of dictEnd
	LEAQ (R8)(CX*1), AX
	MOVQ AX, 392(SP)        // the address of prefixStart
	MOVQ SI, R13
	MOVQ Q_HASHTABLE, BX
	MOVQ Q_TAGTABLE, BP
	MOVQ DX, 0(SP)
	SUBQ R8, R13            // curr
	MOVL Q_MAXDIST, DX
	MOVL R13, R10
	MOVL R13, CX
	MOVL Q_LOWEST, AX
	SUBL DX, CX
	MOVQ BX, 0x10(SP)
	MOVQ BP, 0x18(SP)
	SUBL AX, R10
	MOVQ R8, 0x30(SP)
	CMPL DX, R10
	MOVL Q_ISDICT, DX
	MOVL R13, 0x28(SP)
	CMOVLCC AX, CX          // withinMaxDistance
	TESTL DX, DX
	MOVL CX, R11
	CMOVLNE AX, R11         // lowLimit = isDictionary ? lowestValid : withinMaxDistance
	MOVQ Q_SALT, AX
	MOVQ AX, 0x20(SP)
	MOVL Q_ATTEMPTS, DI
	MOVQ Q_HSHIFT, AX
	MOVL AX, 0x2c(SP)
	MOVL Q_SKIP, CX
	TESTL CX, CX
	JNE  skipping
	MOVQ Q_NEXT, AX
	MOVL (AX), R10          // idx = nextToUpdate
	MOVL R13, AX
	MOVQ Q_CACHE, R14
	SUBL R10, AX
	CMPL AX, $0x180         // kSkipThreshold
	JHI  far

upd:
	// ZSTD_row_update_internalImpl for [R10, R13)
	CMPL R10, R13
	JCC  hash
	MOVQ 0x30(SP), DX
	MOVQ R13, 0x38(SP)
	MOVL 0x2c(SP), CX
	MOVL R10, AX
	MOVQ R8, 0x30(SP)
	MOVQ $0x9e3779b100000000, R15
	MOVL DI, 0x40(SP)
	LEAQ 8(DX)(AX*1), R12
	MOVQ SI, 0x48(SP)
	MOVL 0x28(SP), SI
	MOVQ 0x20(SP), R9       // salt (p is reloaded after the loop)
	MOVL $31, DI
	PCALIGN $16

updloop:
	MOVQ  (R12), DX
	IMULQ R15, DX
	XORQ  R9, DX
	SHRQ  CX, DX            // newHash
	MOVL  DX, AX
	SHRL  $8, AX
	SHLL  $5, AX
	PREFETCHT0 (BP)(AX*1)
	PREFETCHT0 (BX)(AX*4)
	PREFETCHT0 0x40(BX)(AX*4)
	MOVL  R10, R8
	ANDL  $7, R8
	MOVL  (R14)(R8*4), R13  // hash
	MOVL  DX, (R14)(R8*4)
	MOVL  R13, DX
	SHRL  $8, DX
	SHLL  $5, DX       // relRow
	MOVBLZX (BP)(DX*1), AX
	SUBL  $1, AX
	ANDL  $31, AX
	CMOVLEQ DI, AX          // head 0 wraps to rowMask
	MOVB  AX, (BP)(DX*1)
	ADDQ  AX, DX
	MOVB  R13, (BP)(DX*1)
	MOVL  R10, (BX)(DX*4)
	ADDQ  $1, R12
	ADDL  $1, R10
	CMPL  SI, R10
	JNE   updloop
	MOVQ  368(SP), R9
	MOVQ  0x30(SP), R8
	MOVQ  0x38(SP), R13
	MOVL  0x40(SP), DI
	MOVQ  0x48(SP), SI

hash:
	// hash = ZSTD_row_nextCachedHash(curr); nextToUpdate = curr
	MOVL  R13, DX
	MOVQ  0x20(SP), BX
	MOVBLZX 0x2c(SP), CX
	MOVQ  $0x9e3779b100000000, AX
	IMULQ 8(R8)(DX*1), AX
	MOVQ  Q_NEXT, R12
	MOVL  R13, (R12)
	XORQ  BX, AX
	MOVQ  0x10(SP), BX
	SHRQ  CX, AX
	MOVL  AX, DX
	SHRL  $8, DX
	SHLL  $5, DX
	LEAQ  (DX*4), CX
	PREFETCHT0 (BX)(CX*1)
	PREFETCHT0 0x40(BX)(CX*1)
	MOVQ  0x18(SP), BX
	PREFETCHT0 (BX)(DX*1)
	MOVQ  R13, DX
	ANDL  $7, DX
	LEAQ  (R14)(DX*4), DX
	MOVL  (DX), R12
	MOVL  AX, (DX)

havehash:
	MOVL  R12, BX
	MOVQ  0x10(SP), AX
	MOVQ  R12, X0
	MOVQ  Q_ENTROPY, CX
	ADDL  R12, (CX)         // collect salt entropy
	SHRL  $8, BX
	PUNPCKLBW X0, X0
	SHLL  $5, BX       // relRow
	PUNPCKLWL X0, X0
	LEAQ  (AX)(BX*4), BP    // row
	MOVQ  0x18(SP), AX
	PSHUFL $0, X0, X0
	ADDQ  BX, AX            // tagRow

	// matches: tags equal to tag, rotated right by headGrouped (C: ZSTD_row_getSSEMask)
	MOVQ  AX, BX
	MOVOU (AX), X1
	MOVBLZX (AX), CX
	MOVOU 0x10(BX), X2
	PCMPEQB X0, X1
	MOVL  CX, R13
	PCMPEQB X2, X0
	ANDL  $0x1f, R13        // headGrouped
	PMOVMSKB X1, AX
	PMOVMSKB X0, R10
	SHLL  $0x10, R10
	ORL   AX, R10
	CMPB  ·useRowBMI(SB), $0
	JEQ   slow
	CMPL  DI, $31
	JCS   slow              // nbAttempts < rowEntries - 1: C's loop
	ANDQ  $-2, R10          // the head entry is never a candidate
	MOVQ  R10, DX
	RORL  CX, DX
	TESTQ R10, R10
	JEQ   insert
	MOVL  0x28(SP), R15     // curr
	XORL  R10, R10
	PCALIGN $16

gfast:
	XORL  AX, AX
	TZCNTQ DX, AX  // DX != 0 here and below: TZCNT runs as BSF without BMI1, same result
	ADDL  R13, AX
	ANDL  $31, AX    // matchPos
	MOVL  (BP)(AX*4), R14   // matchIndex
	CMPL  R14, R11
	JCS   insert            // below lowLimit: stop
	// Bounds: lowLimit <= R14 < curr, and lowLimit >= baseIdx (rowAsmSetup
	// checks lowestValid >= baseIdx, and lazyRowRun lowestValid <= curr, so
	// curr - lowestValid does not wrap and curr - maxDistance is used only
	// when it is above lowestValid). So R8 + R14 lies in b[0:ip], and the
	// compare and count below read only b[R14-baseIdx:] up to the
	// iLimit - ip bytes that b[ip:] holds. Only buffered candidates are
	// read, and every one passed this check, so the compare loop needs none.
	CMPL  R14, R15
	JCC   bad
	MOVQ  R8, AX
	CMPL  R14, 400(SP)
	CMOVQCS 376(SP), AX     // the candidate's segment
	PREFETCHT0 (AX)(R14*1)
	MOVL  R14, 0x60(SP)(R10*4)
	ADDQ  $1, R10
	BLSRQ DX, DX
	JNE   gfast
	JMP   insert

slow:
	MOVQ  R10, DX
	RORL  CX, DX
	TESTQ R10, R10
	JEQ   insert

gslow:
	XORL  R10, R10
	JMP   gnext
	PCALIGN $16

gtake:
	CMPL  R14, 0x28(SP)     // idx < curr (see gfast)
	JCC   bad
	SUBL  $1, DI
	MOVQ  R8, AX
	CMPL  R14, 400(SP)
	CMOVQCS 376(SP), AX     // the candidate's segment
	PREFETCHT0 (AX)(R14*1)
	MOVL  R14, 0x60(SP)(R10*4)
	ADDQ  $1, R10

gskip:
	LEAQ  -1(DX), AX
	ANDQ  AX, DX
	JEQ   insert
	TESTL DI, DI
	JEQ   insert

gnext:
	XORL  AX, AX
	TZCNTQ DX, AX  // DX != 0 (TZCNT = BSF without BMI1)
	ADDL  R13, AX
	ANDL  $31, AX
	MOVL  AX, R14
	MOVL  (BP)(R14*4), R14
	JEQ   gskip             // matchPos 0 is the head entry
	CMPL  R14, R11
	JCC   gtake

insert:
	// insert curr (nextToUpdate) into the row; nextToUpdate++
	LEAL  31(CX), AX  // (head - 1) & rowMask, CX the raw head byte
	MOVL  $31, DX
	ANDL  $31, AX
	CMOVLEQ DX, AX
	MOVB  AX, (BX)
	MOVL  AX, AX
	MOVB  R12, (BX)(AX*1)
	MOVQ  Q_NEXT, DI
	MOVL  (DI), DX
	LEAL  1(DX), CX
	MOVL  CX, (DI)
	MOVL  DX, (BP)(AX*4)
	TESTQ R10, R10
	JEQ   none
	MOVQ  0(SP), AX
	MOVL  0x28(SP), BP
	MOVL  $3, CX            // ml
	XORL  DX, DX
	LEAQ  0x60(SP), BX
	LEAQ  -7(AX), R12  // iLimit - 7, -3, -1: ZSTD_count's 8, 4, 2-byte step limits
	ADDL  $3, BP
	LEAQ  -3(AX), R15
	LEAQ  -1(AX), R14
	JMP   cmp
	PCALIGN $16

next:
	ADDQ  $1, DX
	CMPQ  DX, R10
	JEQ   done

cmp:
	MOVL  (BX)(DX*4), AX
	CMPL  AX, 400(SP)
	JCS   cmpdict           // an extDict candidate
	MOVL  -3(SI)(CX*1), R11
	MOVQ  AX, DI
	ADDQ  R8, AX            // match
	CMPL  -3(AX)(CX*1), R11
	JNE   next
	// ZSTD_count(ip, match, iLimit)
	CMPQ  SI, R12
	JCC   cnt4ip
	MOVQ  (AX), R9
	MOVQ  (SI), R11
	CMPQ  R9, R11
	JEQ   cnt8
	XORQ  R11, R9
	XORL  AX, AX
	TZCNTQ R9, AX  // R9 != 0 (TZCNT = BSF without BMI1)
	SHRL  $3, AX

counted:
	CMPQ  CX, AX
	JCC   next
	MOVL  BP, CX
	SUBL  DI, CX
	MOVL  CX, 8(SP)         // offBase = curr - matchIndex + REP_NUM
	LEAQ  (SI)(AX*1), CX
	CMPQ  0(SP), CX
	MOVQ  AX, CX
	JNE   next              // ip + ml == iLimit: the best possible

done:
	MOVQ  CX, AX
	MOVL  8(SP), BX
	MOVQ  368(SP), R15
	MOVQ  P_B, SI
	RET
	PCALIGN $16

cnt4ip:
	MOVQ  SI, R11

cnt4:
	CMPQ  R11, R15
	JCC   cnt2
	MOVL  (R11), R9
	CMPL  (AX), R9
	JNE   cnt2
	ADDQ  $4, R11
	ADDQ  $4, AX
	PCALIGN $16

cnt2:
	CMPQ  R11, R14
	JCC   cnt1
	MOVWLZX (R11), R9
	CMPW  (AX), R9
	JNE   cnt1
	ADDQ  $2, R11
	ADDQ  $2, AX
	PCALIGN $16

cnt1:
	MOVQ  0(SP), R9
	CMPQ  R11, R9
	JCC   cntend
	MOVBLZX (R11), R9
	CMPB  (AX), R9
	SETEQ AL
	MOVBLZX AL, AX
	ADDQ  AX, R11

cntend:
	MOVQ  R11, AX
	SUBQ  SI, AX
	JMP   counted
	PCALIGN $8

cnt8:
	LEAQ  8(SI), R11
	ADDQ  $8, AX
	CMPB  ·useAVX2(SB), $0
	JEQ   cnt8chk

cnt32:
	// 32 bytes per step with AVX2 (as fastCount), while R11 + 32 <= iLimit
	LEAQ  32(R11), R9
	CMPQ  R9, 0(SP)
	JHI   cnt32end
	VMOVDQU   (R11), Y0
	VPCMPEQB  (AX), Y0, Y0
	VPMOVMSKB Y0, R9
	INCL  R9
	JNE   cnt32diff
	ADDQ  $32, R11
	ADDQ  $32, AX
	JMP   cnt32

cnt32diff:
	VZEROUPPER
	BSFL  R9, R9
	LEAQ  (R11)(R9*1), AX
	SUBQ  SI, AX
	JMP   counted

cnt32end:
	VZEROUPPER

cnt8chk:
	CMPQ  R11, R12
	JCC   cnt4

cnt8loop:
	MOVQ  (AX), R9
	MOVQ  (R11), R13
	CMPQ  R9, R13
	JEQ   cnt8next
	XORQ  R13, R9
	XORL  AX, AX
	TZCNTQ R9, AX  // R9 != 0 (TZCNT = BSF without BMI1)
	SHRL  $3, AX
	ADDQ  R11, AX
	SUBQ  SI, AX
	JMP   counted
	PCALIGN $16

skipping:
	// lazy skipping: hash ip directly, without the cache or the row update
	MOVQ  $0x9e3779b100000000, R12
	IMULQ (SI), R12
	MOVQ  0x20(SP), AX
	MOVQ  Q_NEXT, CX
	MOVL  R13, (CX)         // nextToUpdate = curr
	MOVBLZX 0x2c(SP), CX
	XORQ  AX, R12
	SHRQ  CX, R12
	JMP   havehash
	PCALIGN $16

cnt8next:
	ADDQ  $8, R11
	ADDQ  $8, AX
	CMPQ  R11, R12
	JCS   cnt8loop
	JMP   cnt4

far:
	// target - idx > kSkipThreshold: update [idx, idx + 96), then refill the
	// cache from target - 32 (C: ZSTD_row_fillHashCache, up to ip + 1)
	CMPL  R10, $0xffffff9f  // idx + kMaxMatchStartPositionsToUpdate (96) would wrap: skip
	JHI   farfill
	MOVL  R10, AX
	MOVQ  R13, 0x38(SP)
	MOVL  0x2c(SP), CX
	MOVQ  $0x9e3779b100000000, R12
	LEAQ  8(R8)(AX*1), BX
	LEAQ  0x68(R8)(AX*1), R15
	MOVQ  0x20(SP), AX
	MOVL  R11, 0x40(SP)
	SUBL  BX, R10  // idx - pointer (mod 2^32), kept in R13: idx = R13 + pointer
	MOVL  DI, 0x48(SP)
	MOVQ  0x10(SP), R8
	MOVL  R10, BP
	MOVQ  SI, 0x50(SP)
	MOVQ  0x18(SP), R10
	MOVQ  AX, DX
	MOVL  BP, R13
	JMP   farin
	PCALIGN $16

farloop:
	MOVQ  Q_SALT, DX

farin:
	MOVQ  (BX), AX
	LEAL  (R13)(BX*1), R11  // idx, rebuilt from the moving pointer
	MOVL  $31, SI
	IMULQ R12, AX
	XORQ  AX, DX
	SHRQ  CX, DX
	MOVL  DX, AX
	SHRL  $8, AX
	SHLL  $5, AX
	PREFETCHT0 (R10)(AX*1)
	LEAQ  (AX*4), DI
	MOVL  R11, AX
	ANDL  $7, AX
	PREFETCHT0 (R8)(DI*1)
	PREFETCHT0 0x40(R8)(DI*1)
	LEAQ  (R14)(AX*4), AX
	MOVL  (AX), BP
	MOVL  DX, (AX)
	MOVL  BP, DX
	SHRL  $8, DX
	SHLL  $5, DX
	LEAQ  (R10)(DX*1), DI
	MOVBLZX (DI), AX
	SUBL  $1, AX
	ANDL  $31, AX
	CMOVLEQ SI, AX
	ADDQ  $1, BX
	MOVB  AX, (DI)
	MOVL  AX, AX
	ADDQ  AX, DX
	MOVB  BP, (DI)(AX*1)
	MOVL  R11, (R8)(DX*4)
	CMPQ  BX, R15
	JNE   farloop
	MOVQ  0x30(SP), R8
	MOVQ  0x38(SP), R13
	MOVL  0x40(SP), R11
	MOVL  0x48(SP), DI
	MOVQ  0x50(SP), SI
	MOVQ  0x10(SP), BX
	MOVQ  0x18(SP), BP

farfill:
	LEAL  -0x20(R13), AX
	LEAQ  1(SI), DX
	LEAQ  (R8)(AX*1), CX
	MOVQ  AX, R10           // idx = target - 32
	CMPQ  DX, CX
	JCS   upd
	MOVQ  DX, AX
	MOVL  $8, DX
	SUBQ  CX, AX
	ADDL  $1, AX
	CMPL  AX, DX
	CMOVLHI DX, AX
	LEAL  (AX)(R10*1), DX
	CMPL  R10, DX
	JCC   upd
	MOVQ  R13, 0x58(SP)
	MOVL  R10, R12
	MOVQ  0x20(SP), R15
	MOVL  DX, 0x40(SP)
	MOVQ  R8, 0x50(SP)
	MOVQ  CX, R8
	MOVL  0x2c(SP), CX
	PCALIGN $16

fill:
	MOVQ  $0x9e3779b100000000, DX
	IMULQ (R8), DX
	ADDQ  $1, R8
	XORQ  R15, DX
	SHRQ  CX, DX
	MOVL  DX, AX
	SHRL  $8, AX
	SHLL  $5, AX
	LEAQ  (AX*4), R13
	PREFETCHT0 (BP)(AX*1)
	MOVL  R12, AX
	ANDL  $7, AX
	ADDL  $1, R12
	PREFETCHT0 (BX)(R13*1)
	PREFETCHT0 0x40(BX)(R13*1)
	MOVL  DX, (R14)(AX*4)
	CMPL  R12, 0x40(SP)
	JCS   fill
	MOVQ  0x50(SP), R8
	MOVQ  0x58(SP), R13
	JMP   upd

cmpdict:
	// C: match = dictBase + matchIndex; read32(match) == read32(ip), then
	// ZSTD_count_2segments(ip+4, match+4, iLimit, dictEnd, prefixStart) + 4.
	// The candidate is at most dictLimit - 4 (C: by table construction;
	// else bad, where the Go code reads past d's slice); lowLimit <= it
	// and lowLimit >= dictBaseIdx (lazyRowExtRun), so it lies in
	// d[lowLimit-dictBaseIdx:dictEnd-4], and the count reads d only up to
	// dictEnd, then b from prefixStart, no further than iLimit from ip.
	MOVL  AX, DI
	MOVL  AX, R11
	SUBL  400(SP), R11
	CMPL  R11, $-3
	JCC   bad
	ADDQ  376(SP), AX       // match
	MOVL  (AX), R11
	CMPL  R11, (SI)
	JNE   next
	MOVQ  BX, 408(SP)
	MOVQ  CX, 416(SP)
	MOVQ  R10, 424(SP)
	MOVQ  DX, 432(SP)
	MOVQ  DI, 440(SP)
	LEAQ  4(SI), R9
	LEAQ  4(AX), R10
	MOVQ  384(SP), R13
	SUBQ  R10, R13
	MOVQ  0(SP), CX
	SUBQ  R9, CX
	CMPQ  CX, R13
	CMOVQLT CX, R13         // min(dictEnd - match, iLimit - ip) bytes
	MOVQ  R10, 448(SP)
	CALL  ·fastCount(SB)
	MOVQ  448(SP), R10
	ADDQ  R11, R10
	CMPQ  R10, 384(SP)
	JNE   dictcnt           // the match ends before dictEnd
	MOVQ  R11, 448(SP)
	LEAQ  4(SI)(R11*1), R9
	MOVQ  392(SP), R10      // it goes on at prefixStart
	MOVQ  0(SP), R13
	SUBQ  R9, R13
	CALL  ·fastCount(SB)
	ADDQ  448(SP), R11

dictcnt:
	LEAQ  4(R11), AX        // currentMl
	MOVQ  408(SP), BX
	MOVQ  416(SP), CX
	MOVQ  424(SP), R10
	MOVQ  432(SP), DX
	MOVQ  440(SP), DI
	JMP   counted

none:
	MOVL  $3, CX
	JMP   done

bad:
	MOVQ  368(SP), R15
	MOVQ  P_B, SI
	MOVQ  $-1, AX
	RET

// func lazyRowExt45(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_extDict_generic (row) for mls 4, rowLog 5:
// compressBlockLazyExtDictGeneric's match loop, with the repcode checks
// (REPLEN), the catch up and the lazy skipping step of the extDict parser.
// R15 = p, SI = b; prefixLowest is unused (the frame holds the segments).
// The repcodes live in the rep1/rep2 argument slots, the anchor and counts in
// their result slots. nSeq = -1 reports a table entry at or after the
// position searched (impossible).
TEXT ·lazyRowExt45(SB), NOSPLIT, $128-128
	MOVQ p+0(FP), R15
	MOVQ P_B, SI
	MOVQ P_DICTBASE, AX
	MOVL P_DICTBASEIDX, CX
	SUBQ CX, AX
	MOVQ AX, L_DBIAS
	MOVL P_LOWEST, CX
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_DSTARTP
	MOVL P_DICTLIMIT, CX
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_DENDP
	MOVQ SI, AX
	MOVL P_BASEIDX, DX
	SUBQ DX, AX
	MOVQ AX, L_BBIAS
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_PSTARTP
	MOVQ iend+40(FP), AX
	ADDQ SI, AX
	MOVQ AX, L_IENDP
	MOVQ ip+24(FP), AX
	MOVQ AX, L_IP
	MOVQ anchor+32(FP), AX
	MOVQ AX, anchorOut+88(FP)
	MOVQ $0, nSeq+96(FP)
	MOVQ $0, nLits+104(FP)
	MOVL $0, llType+120(FP)
	MOVL $0, llPos+124(FP)

main:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  finish
	MOVQ $0, L_MLEN
	MOVQ $1, L_OFFBASE      // repcode1ToOffBase
	LEAQ 1(R8), AX
	MOVQ AX, L_START

	// repcode at ip+1
	INCQ  R8
	MOVL  rep1+64(FP), DX
	REPLEN(r0none, r0c1, r0d1, r0c2, r0d2, r0cd, r0done)
	TESTQ R11, R11
	JEQ   search0
	MOVQ  R11, L_MLEN
	CMPQ  depth+72(FP), $0
	JEQ   store

search0:
	MOVQ L_IP, DI
	CALL ·rowSearchExt45(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, L_MLEN
	JLE  nobetter0
	MOVQ AX, L_MLEN
	MOVQ L_IP, CX
	MOVQ CX, L_START
	MOVQ BX, L_OFFBASE

nobetter0:
	CMPQ L_MLEN, $4
	JGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	MOVQ L_IP, AX
	MOVQ AX, CX
	SUBQ anchorOut+88(FP), CX
	SARQ $8, CX              // kSearchStrength
	LEAQ 1(AX)(CX*1), AX     // ip += step + 1; lazySkipping = step > kLazySkippingStep
	MOVQ AX, L_IP
	XORL DX, DX
	CMPQ CX, $8              // kLazySkippingStep
	SETHI DX
	MOVL DX, P_SKIP
	JMP  main

found:
	CMPQ depth+72(FP), $0
	JEQ  catchup

lazy:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch1
	MOVL  rep1+64(FP), DX
	REPLEN(r1none, r1c1, r1d1, r1c2, r1d2, r1cd, r1done)
	TESTQ R11, R11           // mlRep
	JEQ   lsearch1
	LEAQ  (R11)(R11*2), AX   // gain2
	MOVQ  L_MLEN, CX
	LEAQ  (CX)(CX*2), CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX                 // gain1
	CMPQ  AX, CX
	JLE   lsearch1
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch1:
	MOVQ L_IP, DI
	CALL ·rowSearchExt45(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $4, CX
	CMPQ DX, CX
	JLE  ldepth2
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

ldepth2:
	CMPQ depth+72(FP), $2
	JNE  catchup
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch2
	MOVL  rep1+64(FP), DX
	REPLEN(r2none, r2c1, r2d1, r2c2, r2d2, r2cd, r2done)
	TESTQ R11, R11
	JEQ   lsearch2
	MOVQ  R11, AX
	SHLQ  $2, AX
	MOVQ  L_MLEN, CX
	SHLQ  $2, CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX
	CMPQ  AX, CX
	JLE   lsearch2
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch2:
	MOVQ L_IP, DI
	CALL ·rowSearchExt45(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $7, CX
	CMPQ DX, CX
	JLE  catchup
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

catchup:
	MOVQ L_OFFBASE, DX
	CMPQ DX, $3
	JLS  store              // a repcode: no catch up
	SUBQ $3, DX             // offset
	MOVQ L_START, R8
	MOVQ L_MLEN, AX
	// matchIndex = idx(start) - offset, in the extDict (from dictStart) or
	// the prefix (from prefixStart)
	MOVL    P_BASEIDX, CX
	ADDL    R8, CX
	SUBL    DX, CX
	MOVQ    L_BBIAS, R10
	MOVQ    L_PSTARTP, R9
	CMPL    CX, P_DICTLIMIT
	CMOVQCS L_DBIAS, R10
	CMOVQCS L_DSTARTP, R9
	ADDQ    CX, R10         // match

back:
	CMPQ    R8, anchorOut+88(FP)
	JLE     backdone
	CMPQ    R10, R9
	JLS     backdone
	MOVBLZX -1(SI)(R8*1), BX
	MOVBLZX -1(R10), CX
	CMPL    BX, CX
	JNE     backdone
	DECQ    R8
	DECQ    R10
	INCQ    AX
	JMP     back

backdone:
	MOVQ R8, L_START
	MOVQ AX, L_MLEN
	MOVL rep1+64(FP), CX
	MOVL CX, rep2+68(FP)    // offset2 = offset1
	MOVL DX, rep1+64(FP)    // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVQ L_START, R9
	SUBQ anchorOut+88(FP), R9
	MOVQ L_OFFBASE, R12
	MOVQ L_MLEN, AX
	MOVQ $0, L_RET
	JMP  storeseq

afterstore:
	MOVQ L_START, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	CMPL P_SKIP, $0
	JEQ  reploop
	// leave lazy skipping: ZSTD_row_fillHashCache(ms, base, rowLog, mls, nextToUpdate, ilimit)
	MOVL $0, P_SKIP
	MOVQ P_NEXT, AX
	MOVL (AX), R8            // idx
	MOVL R8, AX
	SUBL P_BASEIDX, AX       // its position
	MOVQ ilimit+48(FP), BX
	SUBQ AX, BX
	JLT  reploop             // idx beyond ilimit: nothing to fill
	INCQ BX
	CMPQ BX, $8
	JLE  fillcnt
	MOVQ $8, BX

fillcnt:
	MOVQ P_CACHE, DX

fillloop:
	MOVL R8, AX
	SUBL P_BASEIDX, AX
	MOVQ (SI)(AX*1), R10
	MOVQ $0x9e3779b100000000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $5, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	PREFETCHT0 64(CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	MOVL R8, AX
	ANDL $7, AX
	MOVL R10, (DX)(AX*4)
	INCL R8
	DECQ BX
	JNE  fillloop

reploop:
	// while ip <= ilimit: ml = repMatchLength(ip, idx(ip), offset2), until 0
	MOVQ  L_IP, R8
	CMPQ  R8, ilimit+48(FP)
	JGT   main
	MOVL  rep2+68(FP), DX
	REPLEN(r3none, r3c1, r3d1, r3c2, r3d2, r3cd, r3done)
	TESTQ R11, R11
	JEQ   main
	MOVQ  R11, AX            // matchLength
	MOVL  rep2+68(FP), CX    // swap repcodes
	MOVL  rep1+64(FP), DX
	MOVL  DX, rep2+68(FP)
	MOVL  CX, rep1+64(FP)
	MOVQ  AX, L_MLEN
	XORL  R9, R9             // no literals
	MOVL  $1, R12            // repcode1ToOffBase
	MOVQ  $1, L_RET
	JMP   storeseq

afterrep:
	MOVQ L_IP, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	JMP  reploop

	// storeseq: R9 litLen (from anchor), R12 offBase, AX matchLength;
	// returns to afterstore (L_RET = 0) or afterrep (L_RET = 1).
storeseq:
	TESTQ R9, R9
	JEQ   seq
	MOVQ  lits+16(FP), R10
	ADDQ  nLits+104(FP), R10
	MOVQ  anchorOut+88(FP), R11
	ADDQ  R9, nLits+104(FP)
	// up to 16 literals: one 16-byte copy (C: ZSTD_storeSeq's ZSTD_copy16).
	// The literal buffer has 16 bytes of slack (the Run functions check),
	// and the source must hold the 16 bytes (else fastCopyLits).
	CMPQ  R9, $16
	JA    litcall
	LEAQ  16(R11), CX
	CMPQ  CX, iend+40(FP)
	JA    litcall
	MOVOU (SI)(R11*1), X0
	MOVOU X0, (R10)
	JMP   seq

litcall:
	ADDQ  SI, R11
	CALL  ·fastCopyLits(SB)

seq:
	MOVQ seqs+8(FP), R10
	MOVQ nSeq+96(FP), R11
	MOVL R12, (R10)(R11*8)
	MOVW R9, 4(R10)(R11*8)
	LEAQ -3(AX), CX
	MOVW CX, 6(R10)(R11*8)
	CMPQ R9, $0xFFFF
	JLS  nolongll
	MOVL $1, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongll:
	CMPQ CX, $0xFFFF
	JLS  nolongml
	MOVL $2, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongml:
	INCQ R11
	MOVQ R11, nSeq+96(FP)
	CMPQ L_RET, $0
	JEQ  afterstore
	JMP  afterrep

finish:
	MOVQ L_IP, AX
	MOVQ AX, ipOut+80(FP)
	MOVL rep1+64(FP), AX
	MOVL AX, rep1Out+112(FP)
	MOVL rep2+68(FP), AX
	MOVL AX, rep2Out+116(FP)
	RET

bad:
	MOVQ $-1, nSeq+96(FP)
	RET

// rowSearchExt46: rowFindBestMatchExtDict (mls 4, rowLog 6) at DI = ip,
// R15 = p: rowSearch46 with the candidates below p.dictLimit read in
// the extDict (see EXTDICT in the header).
// Returns AX = ml (below 4: none; -1: a table entry at or after ip, or in
// the extDict's last 3 bytes, impossible), BX = offBase, SI = b. Clobbers
// everything but R15.
// Frame: as rowSearch46, then 376 d - dictBaseIdx, 384 the address of
// dictEnd, 392 of prefixStart, 400 dictLimit, 408-447 spills, 448 a count.
TEXT ·rowSearchExt46(SB), NOSPLIT, $456-0
	MOVQ R15, 368(SP)
	MOVQ R15, R9
	MOVQ Q_B, SI
	MOVQ SI, DX
	ADDQ DI, SI             // ip
	ADDQ Q_ILIMIT, DX       // iLimit
	MOVL $999999999, 8(SP)  // offBaseNotFound
	MOVQ Q_B, R8
	MOVL Q_BASEIDX, AX
	SUBQ AX, R8             // base: an index addresses it directly
	MOVQ Q_DICTBASE, AX
	MOVL Q_DICTBASEIDX, CX
	SUBQ CX, AX
	MOVQ AX, 376(SP)        // d - dictBaseIdx: an extDict index addresses it
	MOVL Q_DICTLIMIT, CX
	MOVL CX, 400(SP)
	ADDQ CX, AX
	MOVQ AX, 384(SP)        // the address of dictEnd
	LEAQ (R8)(CX*1), AX
	MOVQ AX, 392(SP)        // the address of prefixStart
	MOVQ SI, R13
	MOVQ Q_HASHTABLE, BX
	MOVQ Q_TAGTABLE, BP
	MOVQ DX, 0(SP)
	SUBQ R8, R13            // curr
	MOVL Q_MAXDIST, DX
	MOVL R13, R10
	MOVL R13, CX
	MOVL Q_LOWEST, AX
	SUBL DX, CX
	MOVQ BX, 0x10(SP)
	MOVQ BP, 0x18(SP)
	SUBL AX, R10
	MOVQ R8, 0x30(SP)
	CMPL DX, R10
	MOVL Q_ISDICT, DX
	MOVL R13, 0x28(SP)
	CMOVLCC AX, CX          // withinMaxDistance
	TESTL DX, DX
	MOVL CX, R11
	CMOVLNE AX, R11         // lowLimit = isDictionary ? lowestValid : withinMaxDistance
	MOVQ Q_SALT, AX
	MOVQ AX, 0x20(SP)
	MOVL Q_ATTEMPTS, DI
	MOVQ Q_HSHIFT, AX
	MOVL AX, 0x2c(SP)
	MOVL Q_SKIP, CX
	TESTL CX, CX
	JNE  skipping
	MOVQ Q_NEXT, AX
	MOVL (AX), R10          // idx = nextToUpdate
	MOVL R13, AX
	MOVQ Q_CACHE, R14
	SUBL R10, AX
	CMPL AX, $0x180         // kSkipThreshold
	JHI  far

upd:
	// ZSTD_row_update_internalImpl for [R10, R13)
	CMPL R10, R13
	JCC  hash
	MOVQ 0x30(SP), DX
	MOVQ R13, 0x38(SP)
	MOVL 0x2c(SP), CX
	MOVL R10, AX
	MOVQ R8, 0x30(SP)
	MOVQ $0x9e3779b100000000, R15
	MOVL DI, 0x40(SP)
	LEAQ 8(DX)(AX*1), R12
	MOVQ SI, 0x48(SP)
	MOVL 0x28(SP), SI
	MOVQ 0x20(SP), R9       // salt (p is reloaded after the loop)
	MOVL $63, DI
	PCALIGN $16

updloop:
	MOVQ  (R12), DX
	IMULQ R15, DX
	XORQ  R9, DX
	SHRQ  CX, DX            // newHash
	MOVL  DX, AX
	SHRL  $8, AX
	SHLL  $6, AX
	PREFETCHT0 (BP)(AX*1)
	PREFETCHT0 0x20(BP)(AX*1)
	PREFETCHT0 (BX)(AX*4)
	PREFETCHT0 0x40(BX)(AX*4)
	MOVL  R10, R8
	ANDL  $7, R8
	MOVL  (R14)(R8*4), R13  // hash
	MOVL  DX, (R14)(R8*4)
	MOVL  R13, DX
	SHRL  $8, DX
	SHLL  $6, DX       // relRow
	MOVBLZX (BP)(DX*1), AX
	SUBL  $1, AX
	ANDL  $63, AX
	CMOVLEQ DI, AX          // head 0 wraps to rowMask
	MOVB  AX, (BP)(DX*1)
	ADDQ  AX, DX
	MOVB  R13, (BP)(DX*1)
	MOVL  R10, (BX)(DX*4)
	ADDQ  $1, R12
	ADDL  $1, R10
	CMPL  SI, R10
	JNE   updloop
	MOVQ  368(SP), R9
	MOVQ  0x30(SP), R8
	MOVQ  0x38(SP), R13
	MOVL  0x40(SP), DI
	MOVQ  0x48(SP), SI

hash:
	// hash = ZSTD_row_nextCachedHash(curr); nextToUpdate = curr
	MOVL  R13, DX
	MOVQ  0x20(SP), BX
	MOVBLZX 0x2c(SP), CX
	MOVQ  $0x9e3779b100000000, AX
	IMULQ 8(R8)(DX*1), AX
	MOVQ  Q_NEXT, R12
	MOVL  R13, (R12)
	XORQ  BX, AX
	MOVQ  0x10(SP), BX
	SHRQ  CX, AX
	MOVL  AX, DX
	SHRL  $8, DX
	SHLL  $6, DX
	LEAQ  (DX*4), CX
	PREFETCHT0 (BX)(CX*1)
	PREFETCHT0 0x40(BX)(CX*1)
	MOVQ  0x18(SP), BX
	PREFETCHT0 (BX)(DX*1)
	PREFETCHT0 0x20(BX)(DX*1)
	MOVQ  R13, DX
	ANDL  $7, DX
	LEAQ  (R14)(DX*4), DX
	MOVL  (DX), R12
	MOVL  AX, (DX)

havehash:
	MOVL  R12, BX
	MOVQ  0x10(SP), AX
	MOVQ  R12, X0
	MOVQ  Q_ENTROPY, CX
	ADDL  R12, (CX)         // collect salt entropy
	SHRL  $8, BX
	PUNPCKLBW X0, X0
	SHLL  $6, BX       // relRow
	PUNPCKLWL X0, X0
	LEAQ  (AX)(BX*4), BP    // row
	MOVQ  0x18(SP), AX
	PSHUFL $0, X0, X0
	ADDQ  BX, AX            // tagRow

	// matches: tags equal to tag, rotated right by headGrouped (C: ZSTD_row_getSSEMask)
	MOVOU (AX), X2
	MOVOU 0x10(AX), X1
	MOVQ  AX, BX
	MOVOU 0x20(AX), X3
	MOVOU 0x30(AX), X4
	PCMPEQB X0, X2
	PCMPEQB X0, X1
	MOVBLZX (AX), CX
	PCMPEQB X0, X3
	PCMPEQB X4, X0
	MOVL  CX, R13
	ANDL  $0x3f, R13        // headGrouped
	PMOVMSKB X0, R10
	PMOVMSKB X3, AX
	SHLQ  $0x20, AX
	SHLQ  $0x30, R10
	ORQ   AX, R10
	PMOVMSKB X2, AX
	ORQ   AX, R10
	PMOVMSKB X1, AX
	SHLQ  $0x10, AX
	ORQ   AX, R10
	CMPB  ·useRowBMI(SB), $0
	JEQ   slow
	CMPL  DI, $63
	JCS   slow              // nbAttempts < rowEntries - 1: C's loop
	ANDQ  $-2, R10          // the head entry is never a candidate
	MOVQ  R10, DX
	RORQ  CX, DX
	TESTQ R10, R10
	JEQ   insert
	MOVL  0x28(SP), R15     // curr
	XORL  R10, R10
	PCALIGN $16

gfast:
	XORL  AX, AX
	TZCNTQ DX, AX  // DX != 0 here and below: TZCNT runs as BSF without BMI1, same result
	ADDL  R13, AX
	ANDL  $63, AX    // matchPos
	MOVL  (BP)(AX*4), R14   // matchIndex
	CMPL  R14, R11
	JCS   insert            // below lowLimit: stop
	// Bounds: lowLimit <= R14 < curr, and lowLimit >= baseIdx (rowAsmSetup
	// checks lowestValid >= baseIdx, and lazyRowRun lowestValid <= curr, so
	// curr - lowestValid does not wrap and curr - maxDistance is used only
	// when it is above lowestValid). So R8 + R14 lies in b[0:ip], and the
	// compare and count below read only b[R14-baseIdx:] up to the
	// iLimit - ip bytes that b[ip:] holds. Only buffered candidates are
	// read, and every one passed this check, so the compare loop needs none.
	CMPL  R14, R15
	JCC   bad
	MOVQ  R8, AX
	CMPL  R14, 400(SP)
	CMOVQCS 376(SP), AX     // the candidate's segment
	PREFETCHT0 (AX)(R14*1)
	MOVL  R14, 0x60(SP)(R10*4)
	ADDQ  $1, R10
	BLSRQ DX, DX
	JNE   gfast
	JMP   insert

slow:
	MOVQ  R10, DX
	RORQ  CX, DX
	TESTQ R10, R10
	JEQ   insert

gslow:
	XORL  R10, R10
	JMP   gnext
	PCALIGN $16

gtake:
	CMPL  R14, 0x28(SP)     // idx < curr (see gfast)
	JCC   bad
	SUBL  $1, DI
	MOVQ  R8, AX
	CMPL  R14, 400(SP)
	CMOVQCS 376(SP), AX     // the candidate's segment
	PREFETCHT0 (AX)(R14*1)
	MOVL  R14, 0x60(SP)(R10*4)
	ADDQ  $1, R10

gskip:
	LEAQ  -1(DX), AX
	ANDQ  AX, DX
	JEQ   insert
	TESTL DI, DI
	JEQ   insert

gnext:
	XORL  AX, AX
	TZCNTQ DX, AX  // DX != 0 (TZCNT = BSF without BMI1)
	ADDL  R13, AX
	ANDL  $63, AX
	MOVL  AX, R14
	MOVL  (BP)(R14*4), R14
	JEQ   gskip             // matchPos 0 is the head entry
	CMPL  R14, R11
	JCC   gtake

insert:
	// insert curr (nextToUpdate) into the row; nextToUpdate++
	LEAL  63(CX), AX  // (head - 1) & rowMask, CX the raw head byte
	MOVL  $63, DX
	ANDL  $63, AX
	CMOVLEQ DX, AX
	MOVB  AX, (BX)
	MOVL  AX, AX
	MOVB  R12, (BX)(AX*1)
	MOVQ  Q_NEXT, DI
	MOVL  (DI), DX
	LEAL  1(DX), CX
	MOVL  CX, (DI)
	MOVL  DX, (BP)(AX*4)
	TESTQ R10, R10
	JEQ   none
	MOVQ  0(SP), AX
	MOVL  0x28(SP), BP
	MOVL  $3, CX            // ml
	XORL  DX, DX
	LEAQ  0x60(SP), BX
	LEAQ  -7(AX), R12  // iLimit - 7, -3, -1: ZSTD_count's 8, 4, 2-byte step limits
	ADDL  $3, BP
	LEAQ  -3(AX), R15
	LEAQ  -1(AX), R14
	JMP   cmp
	PCALIGN $16

next:
	ADDQ  $1, DX
	CMPQ  DX, R10
	JEQ   done

cmp:
	MOVL  (BX)(DX*4), AX
	CMPL  AX, 400(SP)
	JCS   cmpdict           // an extDict candidate
	MOVL  -3(SI)(CX*1), R11
	MOVQ  AX, DI
	ADDQ  R8, AX            // match
	CMPL  -3(AX)(CX*1), R11
	JNE   next
	// ZSTD_count(ip, match, iLimit)
	CMPQ  SI, R12
	JCC   cnt4ip
	MOVQ  (AX), R9
	MOVQ  (SI), R11
	CMPQ  R9, R11
	JEQ   cnt8
	XORQ  R11, R9
	XORL  AX, AX
	TZCNTQ R9, AX  // R9 != 0 (TZCNT = BSF without BMI1)
	SHRL  $3, AX

counted:
	CMPQ  CX, AX
	JCC   next
	MOVL  BP, CX
	SUBL  DI, CX
	MOVL  CX, 8(SP)         // offBase = curr - matchIndex + REP_NUM
	LEAQ  (SI)(AX*1), CX
	CMPQ  0(SP), CX
	MOVQ  AX, CX
	JNE   next              // ip + ml == iLimit: the best possible

done:
	MOVQ  CX, AX
	MOVL  8(SP), BX
	MOVQ  368(SP), R15
	MOVQ  P_B, SI
	RET
	PCALIGN $16

cnt4ip:
	MOVQ  SI, R11

cnt4:
	CMPQ  R11, R15
	JCC   cnt2
	MOVL  (R11), R9
	CMPL  (AX), R9
	JNE   cnt2
	ADDQ  $4, R11
	ADDQ  $4, AX
	PCALIGN $16

cnt2:
	CMPQ  R11, R14
	JCC   cnt1
	MOVWLZX (R11), R9
	CMPW  (AX), R9
	JNE   cnt1
	ADDQ  $2, R11
	ADDQ  $2, AX
	PCALIGN $16

cnt1:
	MOVQ  0(SP), R9
	CMPQ  R11, R9
	JCC   cntend
	MOVBLZX (R11), R9
	CMPB  (AX), R9
	SETEQ AL
	MOVBLZX AL, AX
	ADDQ  AX, R11

cntend:
	MOVQ  R11, AX
	SUBQ  SI, AX
	JMP   counted
	PCALIGN $8

cnt8:
	LEAQ  8(SI), R11
	ADDQ  $8, AX
	CMPB  ·useAVX2(SB), $0
	JEQ   cnt8chk

cnt32:
	// 32 bytes per step with AVX2 (as fastCount), while R11 + 32 <= iLimit
	LEAQ  32(R11), R9
	CMPQ  R9, 0(SP)
	JHI   cnt32end
	VMOVDQU   (R11), Y0
	VPCMPEQB  (AX), Y0, Y0
	VPMOVMSKB Y0, R9
	INCL  R9
	JNE   cnt32diff
	ADDQ  $32, R11
	ADDQ  $32, AX
	JMP   cnt32

cnt32diff:
	VZEROUPPER
	BSFL  R9, R9
	LEAQ  (R11)(R9*1), AX
	SUBQ  SI, AX
	JMP   counted

cnt32end:
	VZEROUPPER

cnt8chk:
	CMPQ  R11, R12
	JCC   cnt4

cnt8loop:
	MOVQ  (AX), R9
	MOVQ  (R11), R13
	CMPQ  R9, R13
	JEQ   cnt8next
	XORQ  R13, R9
	XORL  AX, AX
	TZCNTQ R9, AX  // R9 != 0 (TZCNT = BSF without BMI1)
	SHRL  $3, AX
	ADDQ  R11, AX
	SUBQ  SI, AX
	JMP   counted
	PCALIGN $16

skipping:
	// lazy skipping: hash ip directly, without the cache or the row update
	MOVQ  $0x9e3779b100000000, R12
	IMULQ (SI), R12
	MOVQ  0x20(SP), AX
	MOVQ  Q_NEXT, CX
	MOVL  R13, (CX)         // nextToUpdate = curr
	MOVBLZX 0x2c(SP), CX
	XORQ  AX, R12
	SHRQ  CX, R12
	JMP   havehash
	PCALIGN $16

cnt8next:
	ADDQ  $8, R11
	ADDQ  $8, AX
	CMPQ  R11, R12
	JCS   cnt8loop
	JMP   cnt4

far:
	// target - idx > kSkipThreshold: update [idx, idx + 96), then refill the
	// cache from target - 32 (C: ZSTD_row_fillHashCache, up to ip + 1)
	CMPL  R10, $0xffffff9f  // idx + kMaxMatchStartPositionsToUpdate (96) would wrap: skip
	JHI   farfill
	MOVL  R10, AX
	MOVQ  R13, 0x38(SP)
	MOVL  0x2c(SP), CX
	MOVQ  $0x9e3779b100000000, R12
	LEAQ  8(R8)(AX*1), BX
	LEAQ  0x68(R8)(AX*1), R15
	MOVQ  0x20(SP), AX
	MOVL  R11, 0x40(SP)
	SUBL  BX, R10  // idx - pointer (mod 2^32), kept in R13: idx = R13 + pointer
	MOVL  DI, 0x48(SP)
	MOVQ  0x10(SP), R8
	MOVL  R10, BP
	MOVQ  SI, 0x50(SP)
	MOVQ  0x18(SP), R10
	MOVQ  AX, DX
	MOVL  BP, R13
	JMP   farin
	PCALIGN $16

farloop:
	MOVQ  Q_SALT, DX

farin:
	MOVQ  (BX), AX
	LEAL  (R13)(BX*1), R11  // idx, rebuilt from the moving pointer
	MOVL  $63, SI
	IMULQ R12, AX
	XORQ  AX, DX
	SHRQ  CX, DX
	MOVL  DX, AX
	SHRL  $8, AX
	SHLL  $6, AX
	PREFETCHT0 (R10)(AX*1)
	PREFETCHT0 0x20(R10)(AX*1)
	LEAQ  (AX*4), DI
	MOVL  R11, AX
	ANDL  $7, AX
	PREFETCHT0 (R8)(DI*1)
	PREFETCHT0 0x40(R8)(DI*1)
	LEAQ  (R14)(AX*4), AX
	MOVL  (AX), BP
	MOVL  DX, (AX)
	MOVL  BP, DX
	SHRL  $8, DX
	SHLL  $6, DX
	LEAQ  (R10)(DX*1), DI
	MOVBLZX (DI), AX
	SUBL  $1, AX
	ANDL  $63, AX
	CMOVLEQ SI, AX
	ADDQ  $1, BX
	MOVB  AX, (DI)
	MOVL  AX, AX
	ADDQ  AX, DX
	MOVB  BP, (DI)(AX*1)
	MOVL  R11, (R8)(DX*4)
	CMPQ  BX, R15
	JNE   farloop
	MOVQ  0x30(SP), R8
	MOVQ  0x38(SP), R13
	MOVL  0x40(SP), R11
	MOVL  0x48(SP), DI
	MOVQ  0x50(SP), SI
	MOVQ  0x10(SP), BX
	MOVQ  0x18(SP), BP

farfill:
	LEAL  -0x20(R13), AX
	LEAQ  1(SI), DX
	LEAQ  (R8)(AX*1), CX
	MOVQ  AX, R10           // idx = target - 32
	CMPQ  DX, CX
	JCS   upd
	MOVQ  DX, AX
	MOVL  $8, DX
	SUBQ  CX, AX
	ADDL  $1, AX
	CMPL  AX, DX
	CMOVLHI DX, AX
	LEAL  (AX)(R10*1), DX
	CMPL  R10, DX
	JCC   upd
	MOVQ  R13, 0x58(SP)
	MOVL  R10, R12
	MOVQ  0x20(SP), R15
	MOVL  DX, 0x40(SP)
	MOVQ  R8, 0x50(SP)
	MOVQ  CX, R8
	MOVL  0x2c(SP), CX
	PCALIGN $16

fill:
	MOVQ  $0x9e3779b100000000, DX
	IMULQ (R8), DX
	ADDQ  $1, R8
	XORQ  R15, DX
	SHRQ  CX, DX
	MOVL  DX, AX
	SHRL  $8, AX
	SHLL  $6, AX
	LEAQ  (AX*4), R13
	PREFETCHT0 (BP)(AX*1)
	PREFETCHT0 0x20(BP)(AX*1)
	MOVL  R12, AX
	ANDL  $7, AX
	ADDL  $1, R12
	PREFETCHT0 (BX)(R13*1)
	PREFETCHT0 0x40(BX)(R13*1)
	MOVL  DX, (R14)(AX*4)
	CMPL  R12, 0x40(SP)
	JCS   fill
	MOVQ  0x50(SP), R8
	MOVQ  0x58(SP), R13
	JMP   upd

cmpdict:
	// C: match = dictBase + matchIndex; read32(match) == read32(ip), then
	// ZSTD_count_2segments(ip+4, match+4, iLimit, dictEnd, prefixStart) + 4.
	// The candidate is at most dictLimit - 4 (C: by table construction;
	// else bad, where the Go code reads past d's slice); lowLimit <= it
	// and lowLimit >= dictBaseIdx (lazyRowExtRun), so it lies in
	// d[lowLimit-dictBaseIdx:dictEnd-4], and the count reads d only up to
	// dictEnd, then b from prefixStart, no further than iLimit from ip.
	MOVL  AX, DI
	MOVL  AX, R11
	SUBL  400(SP), R11
	CMPL  R11, $-3
	JCC   bad
	ADDQ  376(SP), AX       // match
	MOVL  (AX), R11
	CMPL  R11, (SI)
	JNE   next
	MOVQ  BX, 408(SP)
	MOVQ  CX, 416(SP)
	MOVQ  R10, 424(SP)
	MOVQ  DX, 432(SP)
	MOVQ  DI, 440(SP)
	LEAQ  4(SI), R9
	LEAQ  4(AX), R10
	MOVQ  384(SP), R13
	SUBQ  R10, R13
	MOVQ  0(SP), CX
	SUBQ  R9, CX
	CMPQ  CX, R13
	CMOVQLT CX, R13         // min(dictEnd - match, iLimit - ip) bytes
	MOVQ  R10, 448(SP)
	CALL  ·fastCount(SB)
	MOVQ  448(SP), R10
	ADDQ  R11, R10
	CMPQ  R10, 384(SP)
	JNE   dictcnt           // the match ends before dictEnd
	MOVQ  R11, 448(SP)
	LEAQ  4(SI)(R11*1), R9
	MOVQ  392(SP), R10      // it goes on at prefixStart
	MOVQ  0(SP), R13
	SUBQ  R9, R13
	CALL  ·fastCount(SB)
	ADDQ  448(SP), R11

dictcnt:
	LEAQ  4(R11), AX        // currentMl
	MOVQ  408(SP), BX
	MOVQ  416(SP), CX
	MOVQ  424(SP), R10
	MOVQ  432(SP), DX
	MOVQ  440(SP), DI
	JMP   counted

none:
	MOVL  $3, CX
	JMP   done

bad:
	MOVQ  368(SP), R15
	MOVQ  P_B, SI
	MOVQ  $-1, AX
	RET

// func lazyRowExt46(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_extDict_generic (row) for mls 4, rowLog 6:
// compressBlockLazyExtDictGeneric's match loop, with the repcode checks
// (REPLEN), the catch up and the lazy skipping step of the extDict parser.
// R15 = p, SI = b; prefixLowest is unused (the frame holds the segments).
// The repcodes live in the rep1/rep2 argument slots, the anchor and counts in
// their result slots. nSeq = -1 reports a table entry at or after the
// position searched (impossible).
TEXT ·lazyRowExt46(SB), NOSPLIT, $128-128
	MOVQ p+0(FP), R15
	MOVQ P_B, SI
	MOVQ P_DICTBASE, AX
	MOVL P_DICTBASEIDX, CX
	SUBQ CX, AX
	MOVQ AX, L_DBIAS
	MOVL P_LOWEST, CX
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_DSTARTP
	MOVL P_DICTLIMIT, CX
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_DENDP
	MOVQ SI, AX
	MOVL P_BASEIDX, DX
	SUBQ DX, AX
	MOVQ AX, L_BBIAS
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_PSTARTP
	MOVQ iend+40(FP), AX
	ADDQ SI, AX
	MOVQ AX, L_IENDP
	MOVQ ip+24(FP), AX
	MOVQ AX, L_IP
	MOVQ anchor+32(FP), AX
	MOVQ AX, anchorOut+88(FP)
	MOVQ $0, nSeq+96(FP)
	MOVQ $0, nLits+104(FP)
	MOVL $0, llType+120(FP)
	MOVL $0, llPos+124(FP)

main:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  finish
	MOVQ $0, L_MLEN
	MOVQ $1, L_OFFBASE      // repcode1ToOffBase
	LEAQ 1(R8), AX
	MOVQ AX, L_START

	// repcode at ip+1
	INCQ  R8
	MOVL  rep1+64(FP), DX
	REPLEN(r0none, r0c1, r0d1, r0c2, r0d2, r0cd, r0done)
	TESTQ R11, R11
	JEQ   search0
	MOVQ  R11, L_MLEN
	CMPQ  depth+72(FP), $0
	JEQ   store

search0:
	MOVQ L_IP, DI
	CALL ·rowSearchExt46(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, L_MLEN
	JLE  nobetter0
	MOVQ AX, L_MLEN
	MOVQ L_IP, CX
	MOVQ CX, L_START
	MOVQ BX, L_OFFBASE

nobetter0:
	CMPQ L_MLEN, $4
	JGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	MOVQ L_IP, AX
	MOVQ AX, CX
	SUBQ anchorOut+88(FP), CX
	SARQ $8, CX              // kSearchStrength
	LEAQ 1(AX)(CX*1), AX     // ip += step + 1; lazySkipping = step > kLazySkippingStep
	MOVQ AX, L_IP
	XORL DX, DX
	CMPQ CX, $8              // kLazySkippingStep
	SETHI DX
	MOVL DX, P_SKIP
	JMP  main

found:
	CMPQ depth+72(FP), $0
	JEQ  catchup

lazy:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch1
	MOVL  rep1+64(FP), DX
	REPLEN(r1none, r1c1, r1d1, r1c2, r1d2, r1cd, r1done)
	TESTQ R11, R11           // mlRep
	JEQ   lsearch1
	LEAQ  (R11)(R11*2), AX   // gain2
	MOVQ  L_MLEN, CX
	LEAQ  (CX)(CX*2), CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX                 // gain1
	CMPQ  AX, CX
	JLE   lsearch1
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch1:
	MOVQ L_IP, DI
	CALL ·rowSearchExt46(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $4, CX
	CMPQ DX, CX
	JLE  ldepth2
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

ldepth2:
	CMPQ depth+72(FP), $2
	JNE  catchup
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch2
	MOVL  rep1+64(FP), DX
	REPLEN(r2none, r2c1, r2d1, r2c2, r2d2, r2cd, r2done)
	TESTQ R11, R11
	JEQ   lsearch2
	MOVQ  R11, AX
	SHLQ  $2, AX
	MOVQ  L_MLEN, CX
	SHLQ  $2, CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX
	CMPQ  AX, CX
	JLE   lsearch2
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch2:
	MOVQ L_IP, DI
	CALL ·rowSearchExt46(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $7, CX
	CMPQ DX, CX
	JLE  catchup
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

catchup:
	MOVQ L_OFFBASE, DX
	CMPQ DX, $3
	JLS  store              // a repcode: no catch up
	SUBQ $3, DX             // offset
	MOVQ L_START, R8
	MOVQ L_MLEN, AX
	// matchIndex = idx(start) - offset, in the extDict (from dictStart) or
	// the prefix (from prefixStart)
	MOVL    P_BASEIDX, CX
	ADDL    R8, CX
	SUBL    DX, CX
	MOVQ    L_BBIAS, R10
	MOVQ    L_PSTARTP, R9
	CMPL    CX, P_DICTLIMIT
	CMOVQCS L_DBIAS, R10
	CMOVQCS L_DSTARTP, R9
	ADDQ    CX, R10         // match

back:
	CMPQ    R8, anchorOut+88(FP)
	JLE     backdone
	CMPQ    R10, R9
	JLS     backdone
	MOVBLZX -1(SI)(R8*1), BX
	MOVBLZX -1(R10), CX
	CMPL    BX, CX
	JNE     backdone
	DECQ    R8
	DECQ    R10
	INCQ    AX
	JMP     back

backdone:
	MOVQ R8, L_START
	MOVQ AX, L_MLEN
	MOVL rep1+64(FP), CX
	MOVL CX, rep2+68(FP)    // offset2 = offset1
	MOVL DX, rep1+64(FP)    // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVQ L_START, R9
	SUBQ anchorOut+88(FP), R9
	MOVQ L_OFFBASE, R12
	MOVQ L_MLEN, AX
	MOVQ $0, L_RET
	JMP  storeseq

afterstore:
	MOVQ L_START, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	CMPL P_SKIP, $0
	JEQ  reploop
	// leave lazy skipping: ZSTD_row_fillHashCache(ms, base, rowLog, mls, nextToUpdate, ilimit)
	MOVL $0, P_SKIP
	MOVQ P_NEXT, AX
	MOVL (AX), R8            // idx
	MOVL R8, AX
	SUBL P_BASEIDX, AX       // its position
	MOVQ ilimit+48(FP), BX
	SUBQ AX, BX
	JLT  reploop             // idx beyond ilimit: nothing to fill
	INCQ BX
	CMPQ BX, $8
	JLE  fillcnt
	MOVQ $8, BX

fillcnt:
	MOVQ P_CACHE, DX

fillloop:
	MOVL R8, AX
	SUBL P_BASEIDX, AX
	MOVQ (SI)(AX*1), R10
	MOVQ $0x9e3779b100000000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $6, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	PREFETCHT0 64(CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	PREFETCHT0 32(R11)
	MOVL R8, AX
	ANDL $7, AX
	MOVL R10, (DX)(AX*4)
	INCL R8
	DECQ BX
	JNE  fillloop

reploop:
	// while ip <= ilimit: ml = repMatchLength(ip, idx(ip), offset2), until 0
	MOVQ  L_IP, R8
	CMPQ  R8, ilimit+48(FP)
	JGT   main
	MOVL  rep2+68(FP), DX
	REPLEN(r3none, r3c1, r3d1, r3c2, r3d2, r3cd, r3done)
	TESTQ R11, R11
	JEQ   main
	MOVQ  R11, AX            // matchLength
	MOVL  rep2+68(FP), CX    // swap repcodes
	MOVL  rep1+64(FP), DX
	MOVL  DX, rep2+68(FP)
	MOVL  CX, rep1+64(FP)
	MOVQ  AX, L_MLEN
	XORL  R9, R9             // no literals
	MOVL  $1, R12            // repcode1ToOffBase
	MOVQ  $1, L_RET
	JMP   storeseq

afterrep:
	MOVQ L_IP, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	JMP  reploop

	// storeseq: R9 litLen (from anchor), R12 offBase, AX matchLength;
	// returns to afterstore (L_RET = 0) or afterrep (L_RET = 1).
storeseq:
	TESTQ R9, R9
	JEQ   seq
	MOVQ  lits+16(FP), R10
	ADDQ  nLits+104(FP), R10
	MOVQ  anchorOut+88(FP), R11
	ADDQ  R9, nLits+104(FP)
	// up to 16 literals: one 16-byte copy (C: ZSTD_storeSeq's ZSTD_copy16).
	// The literal buffer has 16 bytes of slack (the Run functions check),
	// and the source must hold the 16 bytes (else fastCopyLits).
	CMPQ  R9, $16
	JA    litcall
	LEAQ  16(R11), CX
	CMPQ  CX, iend+40(FP)
	JA    litcall
	MOVOU (SI)(R11*1), X0
	MOVOU X0, (R10)
	JMP   seq

litcall:
	ADDQ  SI, R11
	CALL  ·fastCopyLits(SB)

seq:
	MOVQ seqs+8(FP), R10
	MOVQ nSeq+96(FP), R11
	MOVL R12, (R10)(R11*8)
	MOVW R9, 4(R10)(R11*8)
	LEAQ -3(AX), CX
	MOVW CX, 6(R10)(R11*8)
	CMPQ R9, $0xFFFF
	JLS  nolongll
	MOVL $1, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongll:
	CMPQ CX, $0xFFFF
	JLS  nolongml
	MOVL $2, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongml:
	INCQ R11
	MOVQ R11, nSeq+96(FP)
	CMPQ L_RET, $0
	JEQ  afterstore
	JMP  afterrep

finish:
	MOVQ L_IP, AX
	MOVQ AX, ipOut+80(FP)
	MOVL rep1+64(FP), AX
	MOVL AX, rep1Out+112(FP)
	MOVL rep2+68(FP), AX
	MOVL AX, rep2Out+116(FP)
	RET

bad:
	MOVQ $-1, nSeq+96(FP)
	RET

// rowSearchExt54: rowFindBestMatchExtDict (mls 5, rowLog 4) at DI = ip,
// R15 = p: rowSearch54 with the candidates below p.dictLimit read in
// the extDict (see EXTDICT in the header).
// Returns AX = ml (below 4: none; -1: a table entry at or after ip, or in
// the extDict's last 3 bytes, impossible), BX = offBase, SI = b. Clobbers
// everything but R15.
// Frame: as rowSearch54, then 376 d - dictBaseIdx, 384 the address of
// dictEnd, 392 of prefixStart, 400 dictLimit, 408-447 spills, 448 a count.
TEXT ·rowSearchExt54(SB), NOSPLIT, $456-0
	MOVQ R15, 368(SP)
	MOVQ R15, R9
	MOVQ Q_B, SI
	MOVQ SI, DX
	ADDQ DI, SI             // ip
	ADDQ Q_ILIMIT, DX       // iLimit
	MOVL $999999999, 8(SP)  // offBaseNotFound
	MOVQ Q_B, R8
	MOVL Q_BASEIDX, AX
	SUBQ AX, R8             // base: an index addresses it directly
	MOVQ Q_DICTBASE, AX
	MOVL Q_DICTBASEIDX, CX
	SUBQ CX, AX
	MOVQ AX, 376(SP)        // d - dictBaseIdx: an extDict index addresses it
	MOVL Q_DICTLIMIT, CX
	MOVL CX, 400(SP)
	ADDQ CX, AX
	MOVQ AX, 384(SP)        // the address of dictEnd
	LEAQ (R8)(CX*1), AX
	MOVQ AX, 392(SP)        // the address of prefixStart
	MOVQ SI, R13
	MOVQ Q_HASHTABLE, BX
	MOVQ Q_TAGTABLE, BP
	MOVQ DX, 0(SP)
	SUBQ R8, R13            // curr
	MOVL Q_MAXDIST, DX
	MOVL R13, R10
	MOVL R13, CX
	MOVL Q_LOWEST, AX
	SUBL DX, CX
	MOVQ BX, 0x10(SP)
	MOVQ BP, 0x18(SP)
	SUBL AX, R10
	MOVQ R8, 0x30(SP)
	CMPL DX, R10
	MOVL Q_ISDICT, DX
	MOVL R13, 0x28(SP)
	CMOVLCC AX, CX          // withinMaxDistance
	TESTL DX, DX
	MOVL CX, R11
	CMOVLNE AX, R11         // lowLimit = isDictionary ? lowestValid : withinMaxDistance
	MOVQ Q_SALT, AX
	MOVQ AX, 0x20(SP)
	MOVL Q_ATTEMPTS, DI
	MOVQ Q_HSHIFT, AX
	MOVL AX, 0x2c(SP)
	MOVL Q_SKIP, CX
	TESTL CX, CX
	JNE  skipping
	MOVQ Q_NEXT, AX
	MOVL (AX), R10          // idx = nextToUpdate
	MOVL R13, AX
	MOVQ Q_CACHE, R14
	SUBL R10, AX
	CMPL AX, $0x180         // kSkipThreshold
	JHI  far

upd:
	// ZSTD_row_update_internalImpl for [R10, R13)
	CMPL R10, R13
	JCC  hash
	MOVQ 0x30(SP), DX
	MOVQ R13, 0x38(SP)
	MOVL 0x2c(SP), CX
	MOVL R10, AX
	MOVQ R8, 0x30(SP)
	MOVQ $0xcf1bbcdcbb000000, R15
	MOVL DI, 0x40(SP)
	LEAQ 8(DX)(AX*1), R12
	MOVQ SI, 0x48(SP)
	MOVL 0x28(SP), SI
	MOVQ 0x20(SP), R9       // salt (p is reloaded after the loop)
	MOVL $15, DI
	PCALIGN $16

updloop:
	MOVQ  (R12), DX
	IMULQ R15, DX
	XORQ  R9, DX
	SHRQ  CX, DX            // newHash
	MOVL  DX, AX
	SHRL  $8, AX
	SHLL  $4, AX
	PREFETCHT0 (BP)(AX*1)
	PREFETCHT0 (BX)(AX*4)
	MOVL  R10, R8
	ANDL  $7, R8
	MOVL  (R14)(R8*4), R13  // hash
	MOVL  DX, (R14)(R8*4)
	MOVL  R13, DX
	SHRL  $8, DX
	SHLL  $4, DX       // relRow
	MOVBLZX (BP)(DX*1), AX
	SUBL  $1, AX
	ANDL  $15, AX
	CMOVLEQ DI, AX          // head 0 wraps to rowMask
	MOVB  AX, (BP)(DX*1)
	ADDQ  AX, DX
	MOVB  R13, (BP)(DX*1)
	MOVL  R10, (BX)(DX*4)
	ADDQ  $1, R12
	ADDL  $1, R10
	CMPL  SI, R10
	JNE   updloop
	MOVQ  368(SP), R9
	MOVQ  0x30(SP), R8
	MOVQ  0x38(SP), R13
	MOVL  0x40(SP), DI
	MOVQ  0x48(SP), SI

hash:
	// hash = ZSTD_row_nextCachedHash(curr); nextToUpdate = curr
	MOVL  R13, DX
	MOVQ  0x20(SP), BX
	MOVBLZX 0x2c(SP), CX
	MOVQ  $0xcf1bbcdcbb000000, AX
	IMULQ 8(R8)(DX*1), AX
	MOVQ  Q_NEXT, R12
	MOVL  R13, (R12)
	XORQ  BX, AX
	MOVQ  0x10(SP), BX
	SHRQ  CX, AX
	MOVL  AX, DX
	SHRL  $8, DX
	SHLL  $4, DX
	LEAQ  (DX*4), CX
	PREFETCHT0 (BX)(CX*1)
	MOVQ  0x18(SP), BX
	PREFETCHT0 (BX)(DX*1)
	MOVQ  R13, DX
	ANDL  $7, DX
	LEAQ  (R14)(DX*4), DX
	MOVL  (DX), R12
	MOVL  AX, (DX)

havehash:
	MOVL  R12, BX
	MOVQ  0x10(SP), AX
	MOVQ  R12, X0
	MOVQ  Q_ENTROPY, CX
	ADDL  R12, (CX)         // collect salt entropy
	SHRL  $8, BX
	PUNPCKLBW X0, X0
	SHLL  $4, BX       // relRow
	PUNPCKLWL X0, X0
	LEAQ  (AX)(BX*4), BP    // row
	MOVQ  0x18(SP), AX
	PSHUFL $0, X0, X0
	ADDQ  BX, AX            // tagRow

	// matches: tags equal to tag, rotated right by headGrouped (C: ZSTD_row_getSSEMask)
	MOVOU (AX), X1
	MOVBLZX (AX), CX
	MOVQ  AX, BX
	PCMPEQB X1, X0
	MOVL  CX, R13
	ANDL  $0xf, R13         // headGrouped
	PMOVMSKB X0, R10
	CMPB  ·useRowBMI(SB), $0
	JEQ   slow
	CMPL  DI, $15
	JCS   slow              // nbAttempts < rowEntries - 1: C's loop
	ANDQ  $-2, R10          // the head entry is never a candidate
	MOVQ  R10, DX
	RORW  CX, DX
	MOVWLZX DX, DX
	TESTQ R10, R10
	JEQ   insert
	MOVL  0x28(SP), R15     // curr
	XORL  R10, R10
	PCALIGN $16

gfast:
	XORL  AX, AX
	TZCNTQ DX, AX  // DX != 0 here and below: TZCNT runs as BSF without BMI1, same result
	ADDL  R13, AX
	ANDL  $15, AX    // matchPos
	MOVL  (BP)(AX*4), R14   // matchIndex
	CMPL  R14, R11
	JCS   insert            // below lowLimit: stop
	// Bounds: lowLimit <= R14 < curr, and lowLimit >= baseIdx (rowAsmSetup
	// checks lowestValid >= baseIdx, and lazyRowRun lowestValid <= curr, so
	// curr - lowestValid does not wrap and curr - maxDistance is used only
	// when it is above lowestValid). So R8 + R14 lies in b[0:ip], and the
	// compare and count below read only b[R14-baseIdx:] up to the
	// iLimit - ip bytes that b[ip:] holds. Only buffered candidates are
	// read, and every one passed this check, so the compare loop needs none.
	CMPL  R14, R15
	JCC   bad
	MOVQ  R8, AX
	CMPL  R14, 400(SP)
	CMOVQCS 376(SP), AX     // the candidate's segment
	PREFETCHT0 (AX)(R14*1)
	MOVL  R14, 0x60(SP)(R10*4)
	ADDQ  $1, R10
	BLSRQ DX, DX
	JNE   gfast
	JMP   insert

slow:
	MOVQ  R10, DX
	RORW  CX, DX
	MOVWLZX DX, DX
	TESTQ R10, R10
	JEQ   insert

gslow:
	XORL  R10, R10
	JMP   gnext
	PCALIGN $16

gtake:
	CMPL  R14, 0x28(SP)     // idx < curr (see gfast)
	JCC   bad
	SUBL  $1, DI
	MOVQ  R8, AX
	CMPL  R14, 400(SP)
	CMOVQCS 376(SP), AX     // the candidate's segment
	PREFETCHT0 (AX)(R14*1)
	MOVL  R14, 0x60(SP)(R10*4)
	ADDQ  $1, R10

gskip:
	LEAQ  -1(DX), AX
	ANDQ  AX, DX
	JEQ   insert
	TESTL DI, DI
	JEQ   insert

gnext:
	XORL  AX, AX
	TZCNTQ DX, AX  // DX != 0 (TZCNT = BSF without BMI1)
	ADDL  R13, AX
	ANDL  $15, AX
	MOVL  AX, R14
	MOVL  (BP)(R14*4), R14
	JEQ   gskip             // matchPos 0 is the head entry
	CMPL  R14, R11
	JCC   gtake

insert:
	// insert curr (nextToUpdate) into the row; nextToUpdate++
	LEAL  15(CX), AX  // (head - 1) & rowMask, CX the raw head byte
	MOVL  $15, DX
	ANDL  $15, AX
	CMOVLEQ DX, AX
	MOVB  AX, (BX)
	MOVL  AX, AX
	MOVB  R12, (BX)(AX*1)
	MOVQ  Q_NEXT, DI
	MOVL  (DI), DX
	LEAL  1(DX), CX
	MOVL  CX, (DI)
	MOVL  DX, (BP)(AX*4)
	TESTQ R10, R10
	JEQ   none
	MOVQ  0(SP), AX
	MOVL  0x28(SP), BP
	MOVL  $3, CX            // ml
	XORL  DX, DX
	LEAQ  0x60(SP), BX
	LEAQ  -7(AX), R12  // iLimit - 7, -3, -1: ZSTD_count's 8, 4, 2-byte step limits
	ADDL  $3, BP
	LEAQ  -3(AX), R15
	LEAQ  -1(AX), R14
	JMP   cmp
	PCALIGN $16

next:
	ADDQ  $1, DX
	CMPQ  DX, R10
	JEQ   done

cmp:
	MOVL  (BX)(DX*4), AX
	CMPL  AX, 400(SP)
	JCS   cmpdict           // an extDict candidate
	MOVL  -3(SI)(CX*1), R11
	MOVQ  AX, DI
	ADDQ  R8, AX            // match
	CMPL  -3(AX)(CX*1), R11
	JNE   next
	// ZSTD_count(ip, match, iLimit)
	CMPQ  SI, R12
	JCC   cnt4ip
	MOVQ  (AX), R9
	MOVQ  (SI), R11
	CMPQ  R9, R11
	JEQ   cnt8
	XORQ  R11, R9
	XORL  AX, AX
	TZCNTQ R9, AX  // R9 != 0 (TZCNT = BSF without BMI1)
	SHRL  $3, AX

counted:
	CMPQ  CX, AX
	JCC   next
	MOVL  BP, CX
	SUBL  DI, CX
	MOVL  CX, 8(SP)         // offBase = curr - matchIndex + REP_NUM
	LEAQ  (SI)(AX*1), CX
	CMPQ  0(SP), CX
	MOVQ  AX, CX
	JNE   next              // ip + ml == iLimit: the best possible

done:
	MOVQ  CX, AX
	MOVL  8(SP), BX
	MOVQ  368(SP), R15
	MOVQ  P_B, SI
	RET
	PCALIGN $16

cnt4ip:
	MOVQ  SI, R11

cnt4:
	CMPQ  R11, R15
	JCC   cnt2
	MOVL  (R11), R9
	CMPL  (AX), R9
	JNE   cnt2
	ADDQ  $4, R11
	ADDQ  $4, AX
	PCALIGN $16

cnt2:
	CMPQ  R11, R14
	JCC   cnt1
	MOVWLZX (R11), R9
	CMPW  (AX), R9
	JNE   cnt1
	ADDQ  $2, R11
	ADDQ  $2, AX
	PCALIGN $16

cnt1:
	MOVQ  0(SP), R9
	CMPQ  R11, R9
	JCC   cntend
	MOVBLZX (R11), R9
	CMPB  (AX), R9
	SETEQ AL
	MOVBLZX AL, AX
	ADDQ  AX, R11

cntend:
	MOVQ  R11, AX
	SUBQ  SI, AX
	JMP   counted
	PCALIGN $8

cnt8:
	LEAQ  8(SI), R11
	ADDQ  $8, AX
	CMPB  ·useAVX2(SB), $0
	JEQ   cnt8chk

cnt32:
	// 32 bytes per step with AVX2 (as fastCount), while R11 + 32 <= iLimit
	LEAQ  32(R11), R9
	CMPQ  R9, 0(SP)
	JHI   cnt32end
	VMOVDQU   (R11), Y0
	VPCMPEQB  (AX), Y0, Y0
	VPMOVMSKB Y0, R9
	INCL  R9
	JNE   cnt32diff
	ADDQ  $32, R11
	ADDQ  $32, AX
	JMP   cnt32

cnt32diff:
	VZEROUPPER
	BSFL  R9, R9
	LEAQ  (R11)(R9*1), AX
	SUBQ  SI, AX
	JMP   counted

cnt32end:
	VZEROUPPER

cnt8chk:
	CMPQ  R11, R12
	JCC   cnt4

cnt8loop:
	MOVQ  (AX), R9
	MOVQ  (R11), R13
	CMPQ  R9, R13
	JEQ   cnt8next
	XORQ  R13, R9
	XORL  AX, AX
	TZCNTQ R9, AX  // R9 != 0 (TZCNT = BSF without BMI1)
	SHRL  $3, AX
	ADDQ  R11, AX
	SUBQ  SI, AX
	JMP   counted
	PCALIGN $16

skipping:
	// lazy skipping: hash ip directly, without the cache or the row update
	MOVQ  $0xcf1bbcdcbb000000, R12
	IMULQ (SI), R12
	MOVQ  0x20(SP), AX
	MOVQ  Q_NEXT, CX
	MOVL  R13, (CX)         // nextToUpdate = curr
	MOVBLZX 0x2c(SP), CX
	XORQ  AX, R12
	SHRQ  CX, R12
	JMP   havehash
	PCALIGN $16

cnt8next:
	ADDQ  $8, R11
	ADDQ  $8, AX
	CMPQ  R11, R12
	JCS   cnt8loop
	JMP   cnt4

far:
	// target - idx > kSkipThreshold: update [idx, idx + 96), then refill the
	// cache from target - 32 (C: ZSTD_row_fillHashCache, up to ip + 1)
	CMPL  R10, $0xffffff9f  // idx + kMaxMatchStartPositionsToUpdate (96) would wrap: skip
	JHI   farfill
	MOVL  R10, AX
	MOVQ  R13, 0x38(SP)
	MOVL  0x2c(SP), CX
	MOVQ  $0xcf1bbcdcbb000000, R12
	LEAQ  8(R8)(AX*1), BX
	LEAQ  0x68(R8)(AX*1), R15
	MOVQ  0x20(SP), AX
	MOVL  R11, 0x40(SP)
	SUBL  BX, R10  // idx - pointer (mod 2^32), kept in R13: idx = R13 + pointer
	MOVL  DI, 0x48(SP)
	MOVQ  0x10(SP), R8
	MOVL  R10, BP
	MOVQ  SI, 0x50(SP)
	MOVQ  0x18(SP), R10
	MOVQ  AX, DX
	MOVL  BP, R13
	JMP   farin
	PCALIGN $16

farloop:
	MOVQ  Q_SALT, DX

farin:
	MOVQ  (BX), AX
	LEAL  (R13)(BX*1), R11  // idx, rebuilt from the moving pointer
	MOVL  $15, SI
	IMULQ R12, AX
	XORQ  AX, DX
	SHRQ  CX, DX
	MOVL  DX, AX
	SHRL  $8, AX
	SHLL  $4, AX
	PREFETCHT0 (R10)(AX*1)
	LEAQ  (AX*4), DI
	MOVL  R11, AX
	ANDL  $7, AX
	PREFETCHT0 (R8)(DI*1)
	LEAQ  (R14)(AX*4), AX
	MOVL  (AX), BP
	MOVL  DX, (AX)
	MOVL  BP, DX
	SHRL  $8, DX
	SHLL  $4, DX
	LEAQ  (R10)(DX*1), DI
	MOVBLZX (DI), AX
	SUBL  $1, AX
	ANDL  $15, AX
	CMOVLEQ SI, AX
	ADDQ  $1, BX
	MOVB  AX, (DI)
	MOVL  AX, AX
	ADDQ  AX, DX
	MOVB  BP, (DI)(AX*1)
	MOVL  R11, (R8)(DX*4)
	CMPQ  BX, R15
	JNE   farloop
	MOVQ  0x30(SP), R8
	MOVQ  0x38(SP), R13
	MOVL  0x40(SP), R11
	MOVL  0x48(SP), DI
	MOVQ  0x50(SP), SI
	MOVQ  0x10(SP), BX
	MOVQ  0x18(SP), BP

farfill:
	LEAL  -0x20(R13), AX
	LEAQ  1(SI), DX
	LEAQ  (R8)(AX*1), CX
	MOVQ  AX, R10           // idx = target - 32
	CMPQ  DX, CX
	JCS   upd
	MOVQ  DX, AX
	MOVL  $8, DX
	SUBQ  CX, AX
	ADDL  $1, AX
	CMPL  AX, DX
	CMOVLHI DX, AX
	LEAL  (AX)(R10*1), DX
	CMPL  R10, DX
	JCC   upd
	MOVQ  R13, 0x58(SP)
	MOVL  R10, R12
	MOVQ  0x20(SP), R15
	MOVL  DX, 0x40(SP)
	MOVQ  R8, 0x50(SP)
	MOVQ  CX, R8
	MOVL  0x2c(SP), CX
	PCALIGN $16

fill:
	MOVQ  $0xcf1bbcdcbb000000, DX
	IMULQ (R8), DX
	ADDQ  $1, R8
	XORQ  R15, DX
	SHRQ  CX, DX
	MOVL  DX, AX
	SHRL  $8, AX
	SHLL  $4, AX
	LEAQ  (AX*4), R13
	PREFETCHT0 (BP)(AX*1)
	MOVL  R12, AX
	ANDL  $7, AX
	ADDL  $1, R12
	PREFETCHT0 (BX)(R13*1)
	MOVL  DX, (R14)(AX*4)
	CMPL  R12, 0x40(SP)
	JCS   fill
	MOVQ  0x50(SP), R8
	MOVQ  0x58(SP), R13
	JMP   upd

cmpdict:
	// C: match = dictBase + matchIndex; read32(match) == read32(ip), then
	// ZSTD_count_2segments(ip+4, match+4, iLimit, dictEnd, prefixStart) + 4.
	// The candidate is at most dictLimit - 4 (C: by table construction;
	// else bad, where the Go code reads past d's slice); lowLimit <= it
	// and lowLimit >= dictBaseIdx (lazyRowExtRun), so it lies in
	// d[lowLimit-dictBaseIdx:dictEnd-4], and the count reads d only up to
	// dictEnd, then b from prefixStart, no further than iLimit from ip.
	MOVL  AX, DI
	MOVL  AX, R11
	SUBL  400(SP), R11
	CMPL  R11, $-3
	JCC   bad
	ADDQ  376(SP), AX       // match
	MOVL  (AX), R11
	CMPL  R11, (SI)
	JNE   next
	MOVQ  BX, 408(SP)
	MOVQ  CX, 416(SP)
	MOVQ  R10, 424(SP)
	MOVQ  DX, 432(SP)
	MOVQ  DI, 440(SP)
	LEAQ  4(SI), R9
	LEAQ  4(AX), R10
	MOVQ  384(SP), R13
	SUBQ  R10, R13
	MOVQ  0(SP), CX
	SUBQ  R9, CX
	CMPQ  CX, R13
	CMOVQLT CX, R13         // min(dictEnd - match, iLimit - ip) bytes
	MOVQ  R10, 448(SP)
	CALL  ·fastCount(SB)
	MOVQ  448(SP), R10
	ADDQ  R11, R10
	CMPQ  R10, 384(SP)
	JNE   dictcnt           // the match ends before dictEnd
	MOVQ  R11, 448(SP)
	LEAQ  4(SI)(R11*1), R9
	MOVQ  392(SP), R10      // it goes on at prefixStart
	MOVQ  0(SP), R13
	SUBQ  R9, R13
	CALL  ·fastCount(SB)
	ADDQ  448(SP), R11

dictcnt:
	LEAQ  4(R11), AX        // currentMl
	MOVQ  408(SP), BX
	MOVQ  416(SP), CX
	MOVQ  424(SP), R10
	MOVQ  432(SP), DX
	MOVQ  440(SP), DI
	JMP   counted

none:
	MOVL  $3, CX
	JMP   done

bad:
	MOVQ  368(SP), R15
	MOVQ  P_B, SI
	MOVQ  $-1, AX
	RET

// func lazyRowExt54(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_extDict_generic (row) for mls 5, rowLog 4:
// compressBlockLazyExtDictGeneric's match loop, with the repcode checks
// (REPLEN), the catch up and the lazy skipping step of the extDict parser.
// R15 = p, SI = b; prefixLowest is unused (the frame holds the segments).
// The repcodes live in the rep1/rep2 argument slots, the anchor and counts in
// their result slots. nSeq = -1 reports a table entry at or after the
// position searched (impossible).
TEXT ·lazyRowExt54(SB), NOSPLIT, $128-128
	MOVQ p+0(FP), R15
	MOVQ P_B, SI
	MOVQ P_DICTBASE, AX
	MOVL P_DICTBASEIDX, CX
	SUBQ CX, AX
	MOVQ AX, L_DBIAS
	MOVL P_LOWEST, CX
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_DSTARTP
	MOVL P_DICTLIMIT, CX
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_DENDP
	MOVQ SI, AX
	MOVL P_BASEIDX, DX
	SUBQ DX, AX
	MOVQ AX, L_BBIAS
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_PSTARTP
	MOVQ iend+40(FP), AX
	ADDQ SI, AX
	MOVQ AX, L_IENDP
	MOVQ ip+24(FP), AX
	MOVQ AX, L_IP
	MOVQ anchor+32(FP), AX
	MOVQ AX, anchorOut+88(FP)
	MOVQ $0, nSeq+96(FP)
	MOVQ $0, nLits+104(FP)
	MOVL $0, llType+120(FP)
	MOVL $0, llPos+124(FP)

main:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  finish
	MOVQ $0, L_MLEN
	MOVQ $1, L_OFFBASE      // repcode1ToOffBase
	LEAQ 1(R8), AX
	MOVQ AX, L_START

	// repcode at ip+1
	INCQ  R8
	MOVL  rep1+64(FP), DX
	REPLEN(r0none, r0c1, r0d1, r0c2, r0d2, r0cd, r0done)
	TESTQ R11, R11
	JEQ   search0
	MOVQ  R11, L_MLEN
	CMPQ  depth+72(FP), $0
	JEQ   store

search0:
	MOVQ L_IP, DI
	CALL ·rowSearchExt54(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, L_MLEN
	JLE  nobetter0
	MOVQ AX, L_MLEN
	MOVQ L_IP, CX
	MOVQ CX, L_START
	MOVQ BX, L_OFFBASE

nobetter0:
	CMPQ L_MLEN, $4
	JGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	MOVQ L_IP, AX
	MOVQ AX, CX
	SUBQ anchorOut+88(FP), CX
	SARQ $8, CX              // kSearchStrength
	LEAQ 1(AX)(CX*1), AX     // ip += step + 1; lazySkipping = step > kLazySkippingStep
	MOVQ AX, L_IP
	XORL DX, DX
	CMPQ CX, $8              // kLazySkippingStep
	SETHI DX
	MOVL DX, P_SKIP
	JMP  main

found:
	CMPQ depth+72(FP), $0
	JEQ  catchup

lazy:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch1
	MOVL  rep1+64(FP), DX
	REPLEN(r1none, r1c1, r1d1, r1c2, r1d2, r1cd, r1done)
	TESTQ R11, R11           // mlRep
	JEQ   lsearch1
	LEAQ  (R11)(R11*2), AX   // gain2
	MOVQ  L_MLEN, CX
	LEAQ  (CX)(CX*2), CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX                 // gain1
	CMPQ  AX, CX
	JLE   lsearch1
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch1:
	MOVQ L_IP, DI
	CALL ·rowSearchExt54(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $4, CX
	CMPQ DX, CX
	JLE  ldepth2
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

ldepth2:
	CMPQ depth+72(FP), $2
	JNE  catchup
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch2
	MOVL  rep1+64(FP), DX
	REPLEN(r2none, r2c1, r2d1, r2c2, r2d2, r2cd, r2done)
	TESTQ R11, R11
	JEQ   lsearch2
	MOVQ  R11, AX
	SHLQ  $2, AX
	MOVQ  L_MLEN, CX
	SHLQ  $2, CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX
	CMPQ  AX, CX
	JLE   lsearch2
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch2:
	MOVQ L_IP, DI
	CALL ·rowSearchExt54(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $7, CX
	CMPQ DX, CX
	JLE  catchup
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

catchup:
	MOVQ L_OFFBASE, DX
	CMPQ DX, $3
	JLS  store              // a repcode: no catch up
	SUBQ $3, DX             // offset
	MOVQ L_START, R8
	MOVQ L_MLEN, AX
	// matchIndex = idx(start) - offset, in the extDict (from dictStart) or
	// the prefix (from prefixStart)
	MOVL    P_BASEIDX, CX
	ADDL    R8, CX
	SUBL    DX, CX
	MOVQ    L_BBIAS, R10
	MOVQ    L_PSTARTP, R9
	CMPL    CX, P_DICTLIMIT
	CMOVQCS L_DBIAS, R10
	CMOVQCS L_DSTARTP, R9
	ADDQ    CX, R10         // match

back:
	CMPQ    R8, anchorOut+88(FP)
	JLE     backdone
	CMPQ    R10, R9
	JLS     backdone
	MOVBLZX -1(SI)(R8*1), BX
	MOVBLZX -1(R10), CX
	CMPL    BX, CX
	JNE     backdone
	DECQ    R8
	DECQ    R10
	INCQ    AX
	JMP     back

backdone:
	MOVQ R8, L_START
	MOVQ AX, L_MLEN
	MOVL rep1+64(FP), CX
	MOVL CX, rep2+68(FP)    // offset2 = offset1
	MOVL DX, rep1+64(FP)    // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVQ L_START, R9
	SUBQ anchorOut+88(FP), R9
	MOVQ L_OFFBASE, R12
	MOVQ L_MLEN, AX
	MOVQ $0, L_RET
	JMP  storeseq

afterstore:
	MOVQ L_START, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	CMPL P_SKIP, $0
	JEQ  reploop
	// leave lazy skipping: ZSTD_row_fillHashCache(ms, base, rowLog, mls, nextToUpdate, ilimit)
	MOVL $0, P_SKIP
	MOVQ P_NEXT, AX
	MOVL (AX), R8            // idx
	MOVL R8, AX
	SUBL P_BASEIDX, AX       // its position
	MOVQ ilimit+48(FP), BX
	SUBQ AX, BX
	JLT  reploop             // idx beyond ilimit: nothing to fill
	INCQ BX
	CMPQ BX, $8
	JLE  fillcnt
	MOVQ $8, BX

fillcnt:
	MOVQ P_CACHE, DX

fillloop:
	MOVL R8, AX
	SUBL P_BASEIDX, AX
	MOVQ (SI)(AX*1), R10
	MOVQ $0xcf1bbcdcbb000000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $4, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	MOVL R8, AX
	ANDL $7, AX
	MOVL R10, (DX)(AX*4)
	INCL R8
	DECQ BX
	JNE  fillloop

reploop:
	// while ip <= ilimit: ml = repMatchLength(ip, idx(ip), offset2), until 0
	MOVQ  L_IP, R8
	CMPQ  R8, ilimit+48(FP)
	JGT   main
	MOVL  rep2+68(FP), DX
	REPLEN(r3none, r3c1, r3d1, r3c2, r3d2, r3cd, r3done)
	TESTQ R11, R11
	JEQ   main
	MOVQ  R11, AX            // matchLength
	MOVL  rep2+68(FP), CX    // swap repcodes
	MOVL  rep1+64(FP), DX
	MOVL  DX, rep2+68(FP)
	MOVL  CX, rep1+64(FP)
	MOVQ  AX, L_MLEN
	XORL  R9, R9             // no literals
	MOVL  $1, R12            // repcode1ToOffBase
	MOVQ  $1, L_RET
	JMP   storeseq

afterrep:
	MOVQ L_IP, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	JMP  reploop

	// storeseq: R9 litLen (from anchor), R12 offBase, AX matchLength;
	// returns to afterstore (L_RET = 0) or afterrep (L_RET = 1).
storeseq:
	TESTQ R9, R9
	JEQ   seq
	MOVQ  lits+16(FP), R10
	ADDQ  nLits+104(FP), R10
	MOVQ  anchorOut+88(FP), R11
	ADDQ  R9, nLits+104(FP)
	// up to 16 literals: one 16-byte copy (C: ZSTD_storeSeq's ZSTD_copy16).
	// The literal buffer has 16 bytes of slack (the Run functions check),
	// and the source must hold the 16 bytes (else fastCopyLits).
	CMPQ  R9, $16
	JA    litcall
	LEAQ  16(R11), CX
	CMPQ  CX, iend+40(FP)
	JA    litcall
	MOVOU (SI)(R11*1), X0
	MOVOU X0, (R10)
	JMP   seq

litcall:
	ADDQ  SI, R11
	CALL  ·fastCopyLits(SB)

seq:
	MOVQ seqs+8(FP), R10
	MOVQ nSeq+96(FP), R11
	MOVL R12, (R10)(R11*8)
	MOVW R9, 4(R10)(R11*8)
	LEAQ -3(AX), CX
	MOVW CX, 6(R10)(R11*8)
	CMPQ R9, $0xFFFF
	JLS  nolongll
	MOVL $1, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongll:
	CMPQ CX, $0xFFFF
	JLS  nolongml
	MOVL $2, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongml:
	INCQ R11
	MOVQ R11, nSeq+96(FP)
	CMPQ L_RET, $0
	JEQ  afterstore
	JMP  afterrep

finish:
	MOVQ L_IP, AX
	MOVQ AX, ipOut+80(FP)
	MOVL rep1+64(FP), AX
	MOVL AX, rep1Out+112(FP)
	MOVL rep2+68(FP), AX
	MOVL AX, rep2Out+116(FP)
	RET

bad:
	MOVQ $-1, nSeq+96(FP)
	RET

// rowSearchExt55: rowFindBestMatchExtDict (mls 5, rowLog 5) at DI = ip,
// R15 = p: rowSearch55 with the candidates below p.dictLimit read in
// the extDict (see EXTDICT in the header).
// Returns AX = ml (below 4: none; -1: a table entry at or after ip, or in
// the extDict's last 3 bytes, impossible), BX = offBase, SI = b. Clobbers
// everything but R15.
// Frame: as rowSearch55, then 376 d - dictBaseIdx, 384 the address of
// dictEnd, 392 of prefixStart, 400 dictLimit, 408-447 spills, 448 a count.
TEXT ·rowSearchExt55(SB), NOSPLIT, $456-0
	MOVQ R15, 368(SP)
	MOVQ R15, R9
	MOVQ Q_B, SI
	MOVQ SI, DX
	ADDQ DI, SI             // ip
	ADDQ Q_ILIMIT, DX       // iLimit
	MOVL $999999999, 8(SP)  // offBaseNotFound
	MOVQ Q_B, R8
	MOVL Q_BASEIDX, AX
	SUBQ AX, R8             // base: an index addresses it directly
	MOVQ Q_DICTBASE, AX
	MOVL Q_DICTBASEIDX, CX
	SUBQ CX, AX
	MOVQ AX, 376(SP)        // d - dictBaseIdx: an extDict index addresses it
	MOVL Q_DICTLIMIT, CX
	MOVL CX, 400(SP)
	ADDQ CX, AX
	MOVQ AX, 384(SP)        // the address of dictEnd
	LEAQ (R8)(CX*1), AX
	MOVQ AX, 392(SP)        // the address of prefixStart
	MOVQ SI, R13
	MOVQ Q_HASHTABLE, BX
	MOVQ Q_TAGTABLE, BP
	MOVQ DX, 0(SP)
	SUBQ R8, R13            // curr
	MOVL Q_MAXDIST, DX
	MOVL R13, R10
	MOVL R13, CX
	MOVL Q_LOWEST, AX
	SUBL DX, CX
	MOVQ BX, 0x10(SP)
	MOVQ BP, 0x18(SP)
	SUBL AX, R10
	MOVQ R8, 0x30(SP)
	CMPL DX, R10
	MOVL Q_ISDICT, DX
	MOVL R13, 0x28(SP)
	CMOVLCC AX, CX          // withinMaxDistance
	TESTL DX, DX
	MOVL CX, R11
	CMOVLNE AX, R11         // lowLimit = isDictionary ? lowestValid : withinMaxDistance
	MOVQ Q_SALT, AX
	MOVQ AX, 0x20(SP)
	MOVL Q_ATTEMPTS, DI
	MOVQ Q_HSHIFT, AX
	MOVL AX, 0x2c(SP)
	MOVL Q_SKIP, CX
	TESTL CX, CX
	JNE  skipping
	MOVQ Q_NEXT, AX
	MOVL (AX), R10          // idx = nextToUpdate
	MOVL R13, AX
	MOVQ Q_CACHE, R14
	SUBL R10, AX
	CMPL AX, $0x180         // kSkipThreshold
	JHI  far

upd:
	// ZSTD_row_update_internalImpl for [R10, R13)
	CMPL R10, R13
	JCC  hash
	MOVQ 0x30(SP), DX
	MOVQ R13, 0x38(SP)
	MOVL 0x2c(SP), CX
	MOVL R10, AX
	MOVQ R8, 0x30(SP)
	MOVQ $0xcf1bbcdcbb000000, R15
	MOVL DI, 0x40(SP)
	LEAQ 8(DX)(AX*1), R12
	MOVQ SI, 0x48(SP)
	MOVL 0x28(SP), SI
	MOVQ 0x20(SP), R9       // salt (p is reloaded after the loop)
	MOVL $31, DI
	PCALIGN $16

updloop:
	MOVQ  (R12), DX
	IMULQ R15, DX
	XORQ  R9, DX
	SHRQ  CX, DX            // newHash
	MOVL  DX, AX
	SHRL  $8, AX
	SHLL  $5, AX
	PREFETCHT0 (BP)(AX*1)
	PREFETCHT0 (BX)(AX*4)
	PREFETCHT0 0x40(BX)(AX*4)
	MOVL  R10, R8
	ANDL  $7, R8
	MOVL  (R14)(R8*4), R13  // hash
	MOVL  DX, (R14)(R8*4)
	MOVL  R13, DX
	SHRL  $8, DX
	SHLL  $5, DX       // relRow
	MOVBLZX (BP)(DX*1), AX
	SUBL  $1, AX
	ANDL  $31, AX
	CMOVLEQ DI, AX          // head 0 wraps to rowMask
	MOVB  AX, (BP)(DX*1)
	ADDQ  AX, DX
	MOVB  R13, (BP)(DX*1)
	MOVL  R10, (BX)(DX*4)
	ADDQ  $1, R12
	ADDL  $1, R10
	CMPL  SI, R10
	JNE   updloop
	MOVQ  368(SP), R9
	MOVQ  0x30(SP), R8
	MOVQ  0x38(SP), R13
	MOVL  0x40(SP), DI
	MOVQ  0x48(SP), SI

hash:
	// hash = ZSTD_row_nextCachedHash(curr); nextToUpdate = curr
	MOVL  R13, DX
	MOVQ  0x20(SP), BX
	MOVBLZX 0x2c(SP), CX
	MOVQ  $0xcf1bbcdcbb000000, AX
	IMULQ 8(R8)(DX*1), AX
	MOVQ  Q_NEXT, R12
	MOVL  R13, (R12)
	XORQ  BX, AX
	MOVQ  0x10(SP), BX
	SHRQ  CX, AX
	MOVL  AX, DX
	SHRL  $8, DX
	SHLL  $5, DX
	LEAQ  (DX*4), CX
	PREFETCHT0 (BX)(CX*1)
	PREFETCHT0 0x40(BX)(CX*1)
	MOVQ  0x18(SP), BX
	PREFETCHT0 (BX)(DX*1)
	MOVQ  R13, DX
	ANDL  $7, DX
	LEAQ  (R14)(DX*4), DX
	MOVL  (DX), R12
	MOVL  AX, (DX)

havehash:
	MOVL  R12, BX
	MOVQ  0x10(SP), AX
	MOVQ  R12, X0
	MOVQ  Q_ENTROPY, CX
	ADDL  R12, (CX)         // collect salt entropy
	SHRL  $8, BX
	PUNPCKLBW X0, X0
	SHLL  $5, BX       // relRow
	PUNPCKLWL X0, X0
	LEAQ  (AX)(BX*4), BP    // row
	MOVQ  0x18(SP), AX
	PSHUFL $0, X0, X0
	ADDQ  BX, AX            // tagRow

	// matches: tags equal to tag, rotated right by headGrouped (C: ZSTD_row_getSSEMask)
	MOVQ  AX, BX
	MOVOU (AX), X1
	MOVBLZX (AX), CX
	MOVOU 0x10(BX), X2
	PCMPEQB X0, X1
	MOVL  CX, R13
	PCMPEQB X2, X0
	ANDL  $0x1f, R13        // headGrouped
	PMOVMSKB X1, AX
	PMOVMSKB X0, R10
	SHLL  $0x10, R10
	ORL   AX, R10
	CMPB  ·useRowBMI(SB), $0
	JEQ   slow
	CMPL  DI, $31
	JCS   slow              // nbAttempts < rowEntries - 1: C's loop
	ANDQ  $-2, R10          // the head entry is never a candidate
	MOVQ  R10, DX
	RORL  CX, DX
	TESTQ R10, R10
	JEQ   insert
	MOVL  0x28(SP), R15     // curr
	XORL  R10, R10
	PCALIGN $16

gfast:
	XORL  AX, AX
	TZCNTQ DX, AX  // DX != 0 here and below: TZCNT runs as BSF without BMI1, same result
	ADDL  R13, AX
	ANDL  $31, AX    // matchPos
	MOVL  (BP)(AX*4), R14   // matchIndex
	CMPL  R14, R11
	JCS   insert            // below lowLimit: stop
	// Bounds: lowLimit <= R14 < curr, and lowLimit >= baseIdx (rowAsmSetup
	// checks lowestValid >= baseIdx, and lazyRowRun lowestValid <= curr, so
	// curr - lowestValid does not wrap and curr - maxDistance is used only
	// when it is above lowestValid). So R8 + R14 lies in b[0:ip], and the
	// compare and count below read only b[R14-baseIdx:] up to the
	// iLimit - ip bytes that b[ip:] holds. Only buffered candidates are
	// read, and every one passed this check, so the compare loop needs none.
	CMPL  R14, R15
	JCC   bad
	MOVQ  R8, AX
	CMPL  R14, 400(SP)
	CMOVQCS 376(SP), AX     // the candidate's segment
	PREFETCHT0 (AX)(R14*1)
	MOVL  R14, 0x60(SP)(R10*4)
	ADDQ  $1, R10
	BLSRQ DX, DX
	JNE   gfast
	JMP   insert

slow:
	MOVQ  R10, DX
	RORL  CX, DX
	TESTQ R10, R10
	JEQ   insert

gslow:
	XORL  R10, R10
	JMP   gnext
	PCALIGN $16

gtake:
	CMPL  R14, 0x28(SP)     // idx < curr (see gfast)
	JCC   bad
	SUBL  $1, DI
	MOVQ  R8, AX
	CMPL  R14, 400(SP)
	CMOVQCS 376(SP), AX     // the candidate's segment
	PREFETCHT0 (AX)(R14*1)
	MOVL  R14, 0x60(SP)(R10*4)
	ADDQ  $1, R10

gskip:
	LEAQ  -1(DX), AX
	ANDQ  AX, DX
	JEQ   insert
	TESTL DI, DI
	JEQ   insert

gnext:
	XORL  AX, AX
	TZCNTQ DX, AX  // DX != 0 (TZCNT = BSF without BMI1)
	ADDL  R13, AX
	ANDL  $31, AX
	MOVL  AX, R14
	MOVL  (BP)(R14*4), R14
	JEQ   gskip             // matchPos 0 is the head entry
	CMPL  R14, R11
	JCC   gtake

insert:
	// insert curr (nextToUpdate) into the row; nextToUpdate++
	LEAL  31(CX), AX  // (head - 1) & rowMask, CX the raw head byte
	MOVL  $31, DX
	ANDL  $31, AX
	CMOVLEQ DX, AX
	MOVB  AX, (BX)
	MOVL  AX, AX
	MOVB  R12, (BX)(AX*1)
	MOVQ  Q_NEXT, DI
	MOVL  (DI), DX
	LEAL  1(DX), CX
	MOVL  CX, (DI)
	MOVL  DX, (BP)(AX*4)
	TESTQ R10, R10
	JEQ   none
	MOVQ  0(SP), AX
	MOVL  0x28(SP), BP
	MOVL  $3, CX            // ml
	XORL  DX, DX
	LEAQ  0x60(SP), BX
	LEAQ  -7(AX), R12  // iLimit - 7, -3, -1: ZSTD_count's 8, 4, 2-byte step limits
	ADDL  $3, BP
	LEAQ  -3(AX), R15
	LEAQ  -1(AX), R14
	JMP   cmp
	PCALIGN $16

next:
	ADDQ  $1, DX
	CMPQ  DX, R10
	JEQ   done

cmp:
	MOVL  (BX)(DX*4), AX
	CMPL  AX, 400(SP)
	JCS   cmpdict           // an extDict candidate
	MOVL  -3(SI)(CX*1), R11
	MOVQ  AX, DI
	ADDQ  R8, AX            // match
	CMPL  -3(AX)(CX*1), R11
	JNE   next
	// ZSTD_count(ip, match, iLimit)
	CMPQ  SI, R12
	JCC   cnt4ip
	MOVQ  (AX), R9
	MOVQ  (SI), R11
	CMPQ  R9, R11
	JEQ   cnt8
	XORQ  R11, R9
	XORL  AX, AX
	TZCNTQ R9, AX  // R9 != 0 (TZCNT = BSF without BMI1)
	SHRL  $3, AX

counted:
	CMPQ  CX, AX
	JCC   next
	MOVL  BP, CX
	SUBL  DI, CX
	MOVL  CX, 8(SP)         // offBase = curr - matchIndex + REP_NUM
	LEAQ  (SI)(AX*1), CX
	CMPQ  0(SP), CX
	MOVQ  AX, CX
	JNE   next              // ip + ml == iLimit: the best possible

done:
	MOVQ  CX, AX
	MOVL  8(SP), BX
	MOVQ  368(SP), R15
	MOVQ  P_B, SI
	RET
	PCALIGN $16

cnt4ip:
	MOVQ  SI, R11

cnt4:
	CMPQ  R11, R15
	JCC   cnt2
	MOVL  (R11), R9
	CMPL  (AX), R9
	JNE   cnt2
	ADDQ  $4, R11
	ADDQ  $4, AX
	PCALIGN $16

cnt2:
	CMPQ  R11, R14
	JCC   cnt1
	MOVWLZX (R11), R9
	CMPW  (AX), R9
	JNE   cnt1
	ADDQ  $2, R11
	ADDQ  $2, AX
	PCALIGN $16

cnt1:
	MOVQ  0(SP), R9
	CMPQ  R11, R9
	JCC   cntend
	MOVBLZX (R11), R9
	CMPB  (AX), R9
	SETEQ AL
	MOVBLZX AL, AX
	ADDQ  AX, R11

cntend:
	MOVQ  R11, AX
	SUBQ  SI, AX
	JMP   counted
	PCALIGN $8

cnt8:
	LEAQ  8(SI), R11
	ADDQ  $8, AX
	CMPB  ·useAVX2(SB), $0
	JEQ   cnt8chk

cnt32:
	// 32 bytes per step with AVX2 (as fastCount), while R11 + 32 <= iLimit
	LEAQ  32(R11), R9
	CMPQ  R9, 0(SP)
	JHI   cnt32end
	VMOVDQU   (R11), Y0
	VPCMPEQB  (AX), Y0, Y0
	VPMOVMSKB Y0, R9
	INCL  R9
	JNE   cnt32diff
	ADDQ  $32, R11
	ADDQ  $32, AX
	JMP   cnt32

cnt32diff:
	VZEROUPPER
	BSFL  R9, R9
	LEAQ  (R11)(R9*1), AX
	SUBQ  SI, AX
	JMP   counted

cnt32end:
	VZEROUPPER

cnt8chk:
	CMPQ  R11, R12
	JCC   cnt4

cnt8loop:
	MOVQ  (AX), R9
	MOVQ  (R11), R13
	CMPQ  R9, R13
	JEQ   cnt8next
	XORQ  R13, R9
	XORL  AX, AX
	TZCNTQ R9, AX  // R9 != 0 (TZCNT = BSF without BMI1)
	SHRL  $3, AX
	ADDQ  R11, AX
	SUBQ  SI, AX
	JMP   counted
	PCALIGN $16

skipping:
	// lazy skipping: hash ip directly, without the cache or the row update
	MOVQ  $0xcf1bbcdcbb000000, R12
	IMULQ (SI), R12
	MOVQ  0x20(SP), AX
	MOVQ  Q_NEXT, CX
	MOVL  R13, (CX)         // nextToUpdate = curr
	MOVBLZX 0x2c(SP), CX
	XORQ  AX, R12
	SHRQ  CX, R12
	JMP   havehash
	PCALIGN $16

cnt8next:
	ADDQ  $8, R11
	ADDQ  $8, AX
	CMPQ  R11, R12
	JCS   cnt8loop
	JMP   cnt4

far:
	// target - idx > kSkipThreshold: update [idx, idx + 96), then refill the
	// cache from target - 32 (C: ZSTD_row_fillHashCache, up to ip + 1)
	CMPL  R10, $0xffffff9f  // idx + kMaxMatchStartPositionsToUpdate (96) would wrap: skip
	JHI   farfill
	MOVL  R10, AX
	MOVQ  R13, 0x38(SP)
	MOVL  0x2c(SP), CX
	MOVQ  $0xcf1bbcdcbb000000, R12
	LEAQ  8(R8)(AX*1), BX
	LEAQ  0x68(R8)(AX*1), R15
	MOVQ  0x20(SP), AX
	MOVL  R11, 0x40(SP)
	SUBL  BX, R10  // idx - pointer (mod 2^32), kept in R13: idx = R13 + pointer
	MOVL  DI, 0x48(SP)
	MOVQ  0x10(SP), R8
	MOVL  R10, BP
	MOVQ  SI, 0x50(SP)
	MOVQ  0x18(SP), R10
	MOVQ  AX, DX
	MOVL  BP, R13
	JMP   farin
	PCALIGN $16

farloop:
	MOVQ  Q_SALT, DX

farin:
	MOVQ  (BX), AX
	LEAL  (R13)(BX*1), R11  // idx, rebuilt from the moving pointer
	MOVL  $31, SI
	IMULQ R12, AX
	XORQ  AX, DX
	SHRQ  CX, DX
	MOVL  DX, AX
	SHRL  $8, AX
	SHLL  $5, AX
	PREFETCHT0 (R10)(AX*1)
	LEAQ  (AX*4), DI
	MOVL  R11, AX
	ANDL  $7, AX
	PREFETCHT0 (R8)(DI*1)
	PREFETCHT0 0x40(R8)(DI*1)
	LEAQ  (R14)(AX*4), AX
	MOVL  (AX), BP
	MOVL  DX, (AX)
	MOVL  BP, DX
	SHRL  $8, DX
	SHLL  $5, DX
	LEAQ  (R10)(DX*1), DI
	MOVBLZX (DI), AX
	SUBL  $1, AX
	ANDL  $31, AX
	CMOVLEQ SI, AX
	ADDQ  $1, BX
	MOVB  AX, (DI)
	MOVL  AX, AX
	ADDQ  AX, DX
	MOVB  BP, (DI)(AX*1)
	MOVL  R11, (R8)(DX*4)
	CMPQ  BX, R15
	JNE   farloop
	MOVQ  0x30(SP), R8
	MOVQ  0x38(SP), R13
	MOVL  0x40(SP), R11
	MOVL  0x48(SP), DI
	MOVQ  0x50(SP), SI
	MOVQ  0x10(SP), BX
	MOVQ  0x18(SP), BP

farfill:
	LEAL  -0x20(R13), AX
	LEAQ  1(SI), DX
	LEAQ  (R8)(AX*1), CX
	MOVQ  AX, R10           // idx = target - 32
	CMPQ  DX, CX
	JCS   upd
	MOVQ  DX, AX
	MOVL  $8, DX
	SUBQ  CX, AX
	ADDL  $1, AX
	CMPL  AX, DX
	CMOVLHI DX, AX
	LEAL  (AX)(R10*1), DX
	CMPL  R10, DX
	JCC   upd
	MOVQ  R13, 0x58(SP)
	MOVL  R10, R12
	MOVQ  0x20(SP), R15
	MOVL  DX, 0x40(SP)
	MOVQ  R8, 0x50(SP)
	MOVQ  CX, R8
	MOVL  0x2c(SP), CX
	PCALIGN $16

fill:
	MOVQ  $0xcf1bbcdcbb000000, DX
	IMULQ (R8), DX
	ADDQ  $1, R8
	XORQ  R15, DX
	SHRQ  CX, DX
	MOVL  DX, AX
	SHRL  $8, AX
	SHLL  $5, AX
	LEAQ  (AX*4), R13
	PREFETCHT0 (BP)(AX*1)
	MOVL  R12, AX
	ANDL  $7, AX
	ADDL  $1, R12
	PREFETCHT0 (BX)(R13*1)
	PREFETCHT0 0x40(BX)(R13*1)
	MOVL  DX, (R14)(AX*4)
	CMPL  R12, 0x40(SP)
	JCS   fill
	MOVQ  0x50(SP), R8
	MOVQ  0x58(SP), R13
	JMP   upd

cmpdict:
	// C: match = dictBase + matchIndex; read32(match) == read32(ip), then
	// ZSTD_count_2segments(ip+4, match+4, iLimit, dictEnd, prefixStart) + 4.
	// The candidate is at most dictLimit - 4 (C: by table construction;
	// else bad, where the Go code reads past d's slice); lowLimit <= it
	// and lowLimit >= dictBaseIdx (lazyRowExtRun), so it lies in
	// d[lowLimit-dictBaseIdx:dictEnd-4], and the count reads d only up to
	// dictEnd, then b from prefixStart, no further than iLimit from ip.
	MOVL  AX, DI
	MOVL  AX, R11
	SUBL  400(SP), R11
	CMPL  R11, $-3
	JCC   bad
	ADDQ  376(SP), AX       // match
	MOVL  (AX), R11
	CMPL  R11, (SI)
	JNE   next
	MOVQ  BX, 408(SP)
	MOVQ  CX, 416(SP)
	MOVQ  R10, 424(SP)
	MOVQ  DX, 432(SP)
	MOVQ  DI, 440(SP)
	LEAQ  4(SI), R9
	LEAQ  4(AX), R10
	MOVQ  384(SP), R13
	SUBQ  R10, R13
	MOVQ  0(SP), CX
	SUBQ  R9, CX
	CMPQ  CX, R13
	CMOVQLT CX, R13         // min(dictEnd - match, iLimit - ip) bytes
	MOVQ  R10, 448(SP)
	CALL  ·fastCount(SB)
	MOVQ  448(SP), R10
	ADDQ  R11, R10
	CMPQ  R10, 384(SP)
	JNE   dictcnt           // the match ends before dictEnd
	MOVQ  R11, 448(SP)
	LEAQ  4(SI)(R11*1), R9
	MOVQ  392(SP), R10      // it goes on at prefixStart
	MOVQ  0(SP), R13
	SUBQ  R9, R13
	CALL  ·fastCount(SB)
	ADDQ  448(SP), R11

dictcnt:
	LEAQ  4(R11), AX        // currentMl
	MOVQ  408(SP), BX
	MOVQ  416(SP), CX
	MOVQ  424(SP), R10
	MOVQ  432(SP), DX
	MOVQ  440(SP), DI
	JMP   counted

none:
	MOVL  $3, CX
	JMP   done

bad:
	MOVQ  368(SP), R15
	MOVQ  P_B, SI
	MOVQ  $-1, AX
	RET

// func lazyRowExt55(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_extDict_generic (row) for mls 5, rowLog 5:
// compressBlockLazyExtDictGeneric's match loop, with the repcode checks
// (REPLEN), the catch up and the lazy skipping step of the extDict parser.
// R15 = p, SI = b; prefixLowest is unused (the frame holds the segments).
// The repcodes live in the rep1/rep2 argument slots, the anchor and counts in
// their result slots. nSeq = -1 reports a table entry at or after the
// position searched (impossible).
TEXT ·lazyRowExt55(SB), NOSPLIT, $128-128
	MOVQ p+0(FP), R15
	MOVQ P_B, SI
	MOVQ P_DICTBASE, AX
	MOVL P_DICTBASEIDX, CX
	SUBQ CX, AX
	MOVQ AX, L_DBIAS
	MOVL P_LOWEST, CX
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_DSTARTP
	MOVL P_DICTLIMIT, CX
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_DENDP
	MOVQ SI, AX
	MOVL P_BASEIDX, DX
	SUBQ DX, AX
	MOVQ AX, L_BBIAS
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_PSTARTP
	MOVQ iend+40(FP), AX
	ADDQ SI, AX
	MOVQ AX, L_IENDP
	MOVQ ip+24(FP), AX
	MOVQ AX, L_IP
	MOVQ anchor+32(FP), AX
	MOVQ AX, anchorOut+88(FP)
	MOVQ $0, nSeq+96(FP)
	MOVQ $0, nLits+104(FP)
	MOVL $0, llType+120(FP)
	MOVL $0, llPos+124(FP)

main:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  finish
	MOVQ $0, L_MLEN
	MOVQ $1, L_OFFBASE      // repcode1ToOffBase
	LEAQ 1(R8), AX
	MOVQ AX, L_START

	// repcode at ip+1
	INCQ  R8
	MOVL  rep1+64(FP), DX
	REPLEN(r0none, r0c1, r0d1, r0c2, r0d2, r0cd, r0done)
	TESTQ R11, R11
	JEQ   search0
	MOVQ  R11, L_MLEN
	CMPQ  depth+72(FP), $0
	JEQ   store

search0:
	MOVQ L_IP, DI
	CALL ·rowSearchExt55(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, L_MLEN
	JLE  nobetter0
	MOVQ AX, L_MLEN
	MOVQ L_IP, CX
	MOVQ CX, L_START
	MOVQ BX, L_OFFBASE

nobetter0:
	CMPQ L_MLEN, $4
	JGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	MOVQ L_IP, AX
	MOVQ AX, CX
	SUBQ anchorOut+88(FP), CX
	SARQ $8, CX              // kSearchStrength
	LEAQ 1(AX)(CX*1), AX     // ip += step + 1; lazySkipping = step > kLazySkippingStep
	MOVQ AX, L_IP
	XORL DX, DX
	CMPQ CX, $8              // kLazySkippingStep
	SETHI DX
	MOVL DX, P_SKIP
	JMP  main

found:
	CMPQ depth+72(FP), $0
	JEQ  catchup

lazy:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch1
	MOVL  rep1+64(FP), DX
	REPLEN(r1none, r1c1, r1d1, r1c2, r1d2, r1cd, r1done)
	TESTQ R11, R11           // mlRep
	JEQ   lsearch1
	LEAQ  (R11)(R11*2), AX   // gain2
	MOVQ  L_MLEN, CX
	LEAQ  (CX)(CX*2), CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX                 // gain1
	CMPQ  AX, CX
	JLE   lsearch1
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch1:
	MOVQ L_IP, DI
	CALL ·rowSearchExt55(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $4, CX
	CMPQ DX, CX
	JLE  ldepth2
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

ldepth2:
	CMPQ depth+72(FP), $2
	JNE  catchup
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch2
	MOVL  rep1+64(FP), DX
	REPLEN(r2none, r2c1, r2d1, r2c2, r2d2, r2cd, r2done)
	TESTQ R11, R11
	JEQ   lsearch2
	MOVQ  R11, AX
	SHLQ  $2, AX
	MOVQ  L_MLEN, CX
	SHLQ  $2, CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX
	CMPQ  AX, CX
	JLE   lsearch2
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch2:
	MOVQ L_IP, DI
	CALL ·rowSearchExt55(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $7, CX
	CMPQ DX, CX
	JLE  catchup
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

catchup:
	MOVQ L_OFFBASE, DX
	CMPQ DX, $3
	JLS  store              // a repcode: no catch up
	SUBQ $3, DX             // offset
	MOVQ L_START, R8
	MOVQ L_MLEN, AX
	// matchIndex = idx(start) - offset, in the extDict (from dictStart) or
	// the prefix (from prefixStart)
	MOVL    P_BASEIDX, CX
	ADDL    R8, CX
	SUBL    DX, CX
	MOVQ    L_BBIAS, R10
	MOVQ    L_PSTARTP, R9
	CMPL    CX, P_DICTLIMIT
	CMOVQCS L_DBIAS, R10
	CMOVQCS L_DSTARTP, R9
	ADDQ    CX, R10         // match

back:
	CMPQ    R8, anchorOut+88(FP)
	JLE     backdone
	CMPQ    R10, R9
	JLS     backdone
	MOVBLZX -1(SI)(R8*1), BX
	MOVBLZX -1(R10), CX
	CMPL    BX, CX
	JNE     backdone
	DECQ    R8
	DECQ    R10
	INCQ    AX
	JMP     back

backdone:
	MOVQ R8, L_START
	MOVQ AX, L_MLEN
	MOVL rep1+64(FP), CX
	MOVL CX, rep2+68(FP)    // offset2 = offset1
	MOVL DX, rep1+64(FP)    // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVQ L_START, R9
	SUBQ anchorOut+88(FP), R9
	MOVQ L_OFFBASE, R12
	MOVQ L_MLEN, AX
	MOVQ $0, L_RET
	JMP  storeseq

afterstore:
	MOVQ L_START, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	CMPL P_SKIP, $0
	JEQ  reploop
	// leave lazy skipping: ZSTD_row_fillHashCache(ms, base, rowLog, mls, nextToUpdate, ilimit)
	MOVL $0, P_SKIP
	MOVQ P_NEXT, AX
	MOVL (AX), R8            // idx
	MOVL R8, AX
	SUBL P_BASEIDX, AX       // its position
	MOVQ ilimit+48(FP), BX
	SUBQ AX, BX
	JLT  reploop             // idx beyond ilimit: nothing to fill
	INCQ BX
	CMPQ BX, $8
	JLE  fillcnt
	MOVQ $8, BX

fillcnt:
	MOVQ P_CACHE, DX

fillloop:
	MOVL R8, AX
	SUBL P_BASEIDX, AX
	MOVQ (SI)(AX*1), R10
	MOVQ $0xcf1bbcdcbb000000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $5, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	PREFETCHT0 64(CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	MOVL R8, AX
	ANDL $7, AX
	MOVL R10, (DX)(AX*4)
	INCL R8
	DECQ BX
	JNE  fillloop

reploop:
	// while ip <= ilimit: ml = repMatchLength(ip, idx(ip), offset2), until 0
	MOVQ  L_IP, R8
	CMPQ  R8, ilimit+48(FP)
	JGT   main
	MOVL  rep2+68(FP), DX
	REPLEN(r3none, r3c1, r3d1, r3c2, r3d2, r3cd, r3done)
	TESTQ R11, R11
	JEQ   main
	MOVQ  R11, AX            // matchLength
	MOVL  rep2+68(FP), CX    // swap repcodes
	MOVL  rep1+64(FP), DX
	MOVL  DX, rep2+68(FP)
	MOVL  CX, rep1+64(FP)
	MOVQ  AX, L_MLEN
	XORL  R9, R9             // no literals
	MOVL  $1, R12            // repcode1ToOffBase
	MOVQ  $1, L_RET
	JMP   storeseq

afterrep:
	MOVQ L_IP, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	JMP  reploop

	// storeseq: R9 litLen (from anchor), R12 offBase, AX matchLength;
	// returns to afterstore (L_RET = 0) or afterrep (L_RET = 1).
storeseq:
	TESTQ R9, R9
	JEQ   seq
	MOVQ  lits+16(FP), R10
	ADDQ  nLits+104(FP), R10
	MOVQ  anchorOut+88(FP), R11
	ADDQ  R9, nLits+104(FP)
	// up to 16 literals: one 16-byte copy (C: ZSTD_storeSeq's ZSTD_copy16).
	// The literal buffer has 16 bytes of slack (the Run functions check),
	// and the source must hold the 16 bytes (else fastCopyLits).
	CMPQ  R9, $16
	JA    litcall
	LEAQ  16(R11), CX
	CMPQ  CX, iend+40(FP)
	JA    litcall
	MOVOU (SI)(R11*1), X0
	MOVOU X0, (R10)
	JMP   seq

litcall:
	ADDQ  SI, R11
	CALL  ·fastCopyLits(SB)

seq:
	MOVQ seqs+8(FP), R10
	MOVQ nSeq+96(FP), R11
	MOVL R12, (R10)(R11*8)
	MOVW R9, 4(R10)(R11*8)
	LEAQ -3(AX), CX
	MOVW CX, 6(R10)(R11*8)
	CMPQ R9, $0xFFFF
	JLS  nolongll
	MOVL $1, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongll:
	CMPQ CX, $0xFFFF
	JLS  nolongml
	MOVL $2, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongml:
	INCQ R11
	MOVQ R11, nSeq+96(FP)
	CMPQ L_RET, $0
	JEQ  afterstore
	JMP  afterrep

finish:
	MOVQ L_IP, AX
	MOVQ AX, ipOut+80(FP)
	MOVL rep1+64(FP), AX
	MOVL AX, rep1Out+112(FP)
	MOVL rep2+68(FP), AX
	MOVL AX, rep2Out+116(FP)
	RET

bad:
	MOVQ $-1, nSeq+96(FP)
	RET

// rowSearchExt56: rowFindBestMatchExtDict (mls 5, rowLog 6) at DI = ip,
// R15 = p: rowSearch56 with the candidates below p.dictLimit read in
// the extDict (see EXTDICT in the header).
// Returns AX = ml (below 4: none; -1: a table entry at or after ip, or in
// the extDict's last 3 bytes, impossible), BX = offBase, SI = b. Clobbers
// everything but R15.
// Frame: as rowSearch56, then 376 d - dictBaseIdx, 384 the address of
// dictEnd, 392 of prefixStart, 400 dictLimit, 408-447 spills, 448 a count.
TEXT ·rowSearchExt56(SB), NOSPLIT, $456-0
	MOVQ R15, 368(SP)
	MOVQ R15, R9
	MOVQ Q_B, SI
	MOVQ SI, DX
	ADDQ DI, SI             // ip
	ADDQ Q_ILIMIT, DX       // iLimit
	MOVL $999999999, 8(SP)  // offBaseNotFound
	MOVQ Q_B, R8
	MOVL Q_BASEIDX, AX
	SUBQ AX, R8             // base: an index addresses it directly
	MOVQ Q_DICTBASE, AX
	MOVL Q_DICTBASEIDX, CX
	SUBQ CX, AX
	MOVQ AX, 376(SP)        // d - dictBaseIdx: an extDict index addresses it
	MOVL Q_DICTLIMIT, CX
	MOVL CX, 400(SP)
	ADDQ CX, AX
	MOVQ AX, 384(SP)        // the address of dictEnd
	LEAQ (R8)(CX*1), AX
	MOVQ AX, 392(SP)        // the address of prefixStart
	MOVQ SI, R13
	MOVQ Q_HASHTABLE, BX
	MOVQ Q_TAGTABLE, BP
	MOVQ DX, 0(SP)
	SUBQ R8, R13            // curr
	MOVL Q_MAXDIST, DX
	MOVL R13, R10
	MOVL R13, CX
	MOVL Q_LOWEST, AX
	SUBL DX, CX
	MOVQ BX, 0x10(SP)
	MOVQ BP, 0x18(SP)
	SUBL AX, R10
	MOVQ R8, 0x30(SP)
	CMPL DX, R10
	MOVL Q_ISDICT, DX
	MOVL R13, 0x28(SP)
	CMOVLCC AX, CX          // withinMaxDistance
	TESTL DX, DX
	MOVL CX, R11
	CMOVLNE AX, R11         // lowLimit = isDictionary ? lowestValid : withinMaxDistance
	MOVQ Q_SALT, AX
	MOVQ AX, 0x20(SP)
	MOVL Q_ATTEMPTS, DI
	MOVQ Q_HSHIFT, AX
	MOVL AX, 0x2c(SP)
	MOVL Q_SKIP, CX
	TESTL CX, CX
	JNE  skipping
	MOVQ Q_NEXT, AX
	MOVL (AX), R10          // idx = nextToUpdate
	MOVL R13, AX
	MOVQ Q_CACHE, R14
	SUBL R10, AX
	CMPL AX, $0x180         // kSkipThreshold
	JHI  far

upd:
	// ZSTD_row_update_internalImpl for [R10, R13)
	CMPL R10, R13
	JCC  hash
	MOVQ 0x30(SP), DX
	MOVQ R13, 0x38(SP)
	MOVL 0x2c(SP), CX
	MOVL R10, AX
	MOVQ R8, 0x30(SP)
	MOVQ $0xcf1bbcdcbb000000, R15
	MOVL DI, 0x40(SP)
	LEAQ 8(DX)(AX*1), R12
	MOVQ SI, 0x48(SP)
	MOVL 0x28(SP), SI
	MOVQ 0x20(SP), R9       // salt (p is reloaded after the loop)
	MOVL $63, DI
	PCALIGN $16

updloop:
	MOVQ  (R12), DX
	IMULQ R15, DX
	XORQ  R9, DX
	SHRQ  CX, DX            // newHash
	MOVL  DX, AX
	SHRL  $8, AX
	SHLL  $6, AX
	PREFETCHT0 (BP)(AX*1)
	PREFETCHT0 0x20(BP)(AX*1)
	PREFETCHT0 (BX)(AX*4)
	PREFETCHT0 0x40(BX)(AX*4)
	MOVL  R10, R8
	ANDL  $7, R8
	MOVL  (R14)(R8*4), R13  // hash
	MOVL  DX, (R14)(R8*4)
	MOVL  R13, DX
	SHRL  $8, DX
	SHLL  $6, DX       // relRow
	MOVBLZX (BP)(DX*1), AX
	SUBL  $1, AX
	ANDL  $63, AX
	CMOVLEQ DI, AX          // head 0 wraps to rowMask
	MOVB  AX, (BP)(DX*1)
	ADDQ  AX, DX
	MOVB  R13, (BP)(DX*1)
	MOVL  R10, (BX)(DX*4)
	ADDQ  $1, R12
	ADDL  $1, R10
	CMPL  SI, R10
	JNE   updloop
	MOVQ  368(SP), R9
	MOVQ  0x30(SP), R8
	MOVQ  0x38(SP), R13
	MOVL  0x40(SP), DI
	MOVQ  0x48(SP), SI

hash:
	// hash = ZSTD_row_nextCachedHash(curr); nextToUpdate = curr
	MOVL  R13, DX
	MOVQ  0x20(SP), BX
	MOVBLZX 0x2c(SP), CX
	MOVQ  $0xcf1bbcdcbb000000, AX
	IMULQ 8(R8)(DX*1), AX
	MOVQ  Q_NEXT, R12
	MOVL  R13, (R12)
	XORQ  BX, AX
	MOVQ  0x10(SP), BX
	SHRQ  CX, AX
	MOVL  AX, DX
	SHRL  $8, DX
	SHLL  $6, DX
	LEAQ  (DX*4), CX
	PREFETCHT0 (BX)(CX*1)
	PREFETCHT0 0x40(BX)(CX*1)
	MOVQ  0x18(SP), BX
	PREFETCHT0 (BX)(DX*1)
	PREFETCHT0 0x20(BX)(DX*1)
	MOVQ  R13, DX
	ANDL  $7, DX
	LEAQ  (R14)(DX*4), DX
	MOVL  (DX), R12
	MOVL  AX, (DX)

havehash:
	MOVL  R12, BX
	MOVQ  0x10(SP), AX
	MOVQ  R12, X0
	MOVQ  Q_ENTROPY, CX
	ADDL  R12, (CX)         // collect salt entropy
	SHRL  $8, BX
	PUNPCKLBW X0, X0
	SHLL  $6, BX       // relRow
	PUNPCKLWL X0, X0
	LEAQ  (AX)(BX*4), BP    // row
	MOVQ  0x18(SP), AX
	PSHUFL $0, X0, X0
	ADDQ  BX, AX            // tagRow

	// matches: tags equal to tag, rotated right by headGrouped (C: ZSTD_row_getSSEMask)
	MOVOU (AX), X2
	MOVOU 0x10(AX), X1
	MOVQ  AX, BX
	MOVOU 0x20(AX), X3
	MOVOU 0x30(AX), X4
	PCMPEQB X0, X2
	PCMPEQB X0, X1
	MOVBLZX (AX), CX
	PCMPEQB X0, X3
	PCMPEQB X4, X0
	MOVL  CX, R13
	ANDL  $0x3f, R13        // headGrouped
	PMOVMSKB X0, R10
	PMOVMSKB X3, AX
	SHLQ  $0x20, AX
	SHLQ  $0x30, R10
	ORQ   AX, R10
	PMOVMSKB X2, AX
	ORQ   AX, R10
	PMOVMSKB X1, AX
	SHLQ  $0x10, AX
	ORQ   AX, R10
	CMPB  ·useRowBMI(SB), $0
	JEQ   slow
	CMPL  DI, $63
	JCS   slow              // nbAttempts < rowEntries - 1: C's loop
	ANDQ  $-2, R10          // the head entry is never a candidate
	MOVQ  R10, DX
	RORQ  CX, DX
	TESTQ R10, R10
	JEQ   insert
	MOVL  0x28(SP), R15     // curr
	XORL  R10, R10
	PCALIGN $16

gfast:
	XORL  AX, AX
	TZCNTQ DX, AX  // DX != 0 here and below: TZCNT runs as BSF without BMI1, same result
	ADDL  R13, AX
	ANDL  $63, AX    // matchPos
	MOVL  (BP)(AX*4), R14   // matchIndex
	CMPL  R14, R11
	JCS   insert            // below lowLimit: stop
	// Bounds: lowLimit <= R14 < curr, and lowLimit >= baseIdx (rowAsmSetup
	// checks lowestValid >= baseIdx, and lazyRowRun lowestValid <= curr, so
	// curr - lowestValid does not wrap and curr - maxDistance is used only
	// when it is above lowestValid). So R8 + R14 lies in b[0:ip], and the
	// compare and count below read only b[R14-baseIdx:] up to the
	// iLimit - ip bytes that b[ip:] holds. Only buffered candidates are
	// read, and every one passed this check, so the compare loop needs none.
	CMPL  R14, R15
	JCC   bad
	MOVQ  R8, AX
	CMPL  R14, 400(SP)
	CMOVQCS 376(SP), AX     // the candidate's segment
	PREFETCHT0 (AX)(R14*1)
	MOVL  R14, 0x60(SP)(R10*4)
	ADDQ  $1, R10
	BLSRQ DX, DX
	JNE   gfast
	JMP   insert

slow:
	MOVQ  R10, DX
	RORQ  CX, DX
	TESTQ R10, R10
	JEQ   insert

gslow:
	XORL  R10, R10
	JMP   gnext
	PCALIGN $16

gtake:
	CMPL  R14, 0x28(SP)     // idx < curr (see gfast)
	JCC   bad
	SUBL  $1, DI
	MOVQ  R8, AX
	CMPL  R14, 400(SP)
	CMOVQCS 376(SP), AX     // the candidate's segment
	PREFETCHT0 (AX)(R14*1)
	MOVL  R14, 0x60(SP)(R10*4)
	ADDQ  $1, R10

gskip:
	LEAQ  -1(DX), AX
	ANDQ  AX, DX
	JEQ   insert
	TESTL DI, DI
	JEQ   insert

gnext:
	XORL  AX, AX
	TZCNTQ DX, AX  // DX != 0 (TZCNT = BSF without BMI1)
	ADDL  R13, AX
	ANDL  $63, AX
	MOVL  AX, R14
	MOVL  (BP)(R14*4), R14
	JEQ   gskip             // matchPos 0 is the head entry
	CMPL  R14, R11
	JCC   gtake

insert:
	// insert curr (nextToUpdate) into the row; nextToUpdate++
	LEAL  63(CX), AX  // (head - 1) & rowMask, CX the raw head byte
	MOVL  $63, DX
	ANDL  $63, AX
	CMOVLEQ DX, AX
	MOVB  AX, (BX)
	MOVL  AX, AX
	MOVB  R12, (BX)(AX*1)
	MOVQ  Q_NEXT, DI
	MOVL  (DI), DX
	LEAL  1(DX), CX
	MOVL  CX, (DI)
	MOVL  DX, (BP)(AX*4)
	TESTQ R10, R10
	JEQ   none
	MOVQ  0(SP), AX
	MOVL  0x28(SP), BP
	MOVL  $3, CX            // ml
	XORL  DX, DX
	LEAQ  0x60(SP), BX
	LEAQ  -7(AX), R12  // iLimit - 7, -3, -1: ZSTD_count's 8, 4, 2-byte step limits
	ADDL  $3, BP
	LEAQ  -3(AX), R15
	LEAQ  -1(AX), R14
	JMP   cmp
	PCALIGN $16

next:
	ADDQ  $1, DX
	CMPQ  DX, R10
	JEQ   done

cmp:
	MOVL  (BX)(DX*4), AX
	CMPL  AX, 400(SP)
	JCS   cmpdict           // an extDict candidate
	MOVL  -3(SI)(CX*1), R11
	MOVQ  AX, DI
	ADDQ  R8, AX            // match
	CMPL  -3(AX)(CX*1), R11
	JNE   next
	// ZSTD_count(ip, match, iLimit)
	CMPQ  SI, R12
	JCC   cnt4ip
	MOVQ  (AX), R9
	MOVQ  (SI), R11
	CMPQ  R9, R11
	JEQ   cnt8
	XORQ  R11, R9
	XORL  AX, AX
	TZCNTQ R9, AX  // R9 != 0 (TZCNT = BSF without BMI1)
	SHRL  $3, AX

counted:
	CMPQ  CX, AX
	JCC   next
	MOVL  BP, CX
	SUBL  DI, CX
	MOVL  CX, 8(SP)         // offBase = curr - matchIndex + REP_NUM
	LEAQ  (SI)(AX*1), CX
	CMPQ  0(SP), CX
	MOVQ  AX, CX
	JNE   next              // ip + ml == iLimit: the best possible

done:
	MOVQ  CX, AX
	MOVL  8(SP), BX
	MOVQ  368(SP), R15
	MOVQ  P_B, SI
	RET
	PCALIGN $16

cnt4ip:
	MOVQ  SI, R11

cnt4:
	CMPQ  R11, R15
	JCC   cnt2
	MOVL  (R11), R9
	CMPL  (AX), R9
	JNE   cnt2
	ADDQ  $4, R11
	ADDQ  $4, AX
	PCALIGN $16

cnt2:
	CMPQ  R11, R14
	JCC   cnt1
	MOVWLZX (R11), R9
	CMPW  (AX), R9
	JNE   cnt1
	ADDQ  $2, R11
	ADDQ  $2, AX
	PCALIGN $16

cnt1:
	MOVQ  0(SP), R9
	CMPQ  R11, R9
	JCC   cntend
	MOVBLZX (R11), R9
	CMPB  (AX), R9
	SETEQ AL
	MOVBLZX AL, AX
	ADDQ  AX, R11

cntend:
	MOVQ  R11, AX
	SUBQ  SI, AX
	JMP   counted
	PCALIGN $8

cnt8:
	LEAQ  8(SI), R11
	ADDQ  $8, AX
	CMPB  ·useAVX2(SB), $0
	JEQ   cnt8chk

cnt32:
	// 32 bytes per step with AVX2 (as fastCount), while R11 + 32 <= iLimit
	LEAQ  32(R11), R9
	CMPQ  R9, 0(SP)
	JHI   cnt32end
	VMOVDQU   (R11), Y0
	VPCMPEQB  (AX), Y0, Y0
	VPMOVMSKB Y0, R9
	INCL  R9
	JNE   cnt32diff
	ADDQ  $32, R11
	ADDQ  $32, AX
	JMP   cnt32

cnt32diff:
	VZEROUPPER
	BSFL  R9, R9
	LEAQ  (R11)(R9*1), AX
	SUBQ  SI, AX
	JMP   counted

cnt32end:
	VZEROUPPER

cnt8chk:
	CMPQ  R11, R12
	JCC   cnt4

cnt8loop:
	MOVQ  (AX), R9
	MOVQ  (R11), R13
	CMPQ  R9, R13
	JEQ   cnt8next
	XORQ  R13, R9
	XORL  AX, AX
	TZCNTQ R9, AX  // R9 != 0 (TZCNT = BSF without BMI1)
	SHRL  $3, AX
	ADDQ  R11, AX
	SUBQ  SI, AX
	JMP   counted
	PCALIGN $16

skipping:
	// lazy skipping: hash ip directly, without the cache or the row update
	MOVQ  $0xcf1bbcdcbb000000, R12
	IMULQ (SI), R12
	MOVQ  0x20(SP), AX
	MOVQ  Q_NEXT, CX
	MOVL  R13, (CX)         // nextToUpdate = curr
	MOVBLZX 0x2c(SP), CX
	XORQ  AX, R12
	SHRQ  CX, R12
	JMP   havehash
	PCALIGN $16

cnt8next:
	ADDQ  $8, R11
	ADDQ  $8, AX
	CMPQ  R11, R12
	JCS   cnt8loop
	JMP   cnt4

far:
	// target - idx > kSkipThreshold: update [idx, idx + 96), then refill the
	// cache from target - 32 (C: ZSTD_row_fillHashCache, up to ip + 1)
	CMPL  R10, $0xffffff9f  // idx + kMaxMatchStartPositionsToUpdate (96) would wrap: skip
	JHI   farfill
	MOVL  R10, AX
	MOVQ  R13, 0x38(SP)
	MOVL  0x2c(SP), CX
	MOVQ  $0xcf1bbcdcbb000000, R12
	LEAQ  8(R8)(AX*1), BX
	LEAQ  0x68(R8)(AX*1), R15
	MOVQ  0x20(SP), AX
	MOVL  R11, 0x40(SP)
	SUBL  BX, R10  // idx - pointer (mod 2^32), kept in R13: idx = R13 + pointer
	MOVL  DI, 0x48(SP)
	MOVQ  0x10(SP), R8
	MOVL  R10, BP
	MOVQ  SI, 0x50(SP)
	MOVQ  0x18(SP), R10
	MOVQ  AX, DX
	MOVL  BP, R13
	JMP   farin
	PCALIGN $16

farloop:
	MOVQ  Q_SALT, DX

farin:
	MOVQ  (BX), AX
	LEAL  (R13)(BX*1), R11  // idx, rebuilt from the moving pointer
	MOVL  $63, SI
	IMULQ R12, AX
	XORQ  AX, DX
	SHRQ  CX, DX
	MOVL  DX, AX
	SHRL  $8, AX
	SHLL  $6, AX
	PREFETCHT0 (R10)(AX*1)
	PREFETCHT0 0x20(R10)(AX*1)
	LEAQ  (AX*4), DI
	MOVL  R11, AX
	ANDL  $7, AX
	PREFETCHT0 (R8)(DI*1)
	PREFETCHT0 0x40(R8)(DI*1)
	LEAQ  (R14)(AX*4), AX
	MOVL  (AX), BP
	MOVL  DX, (AX)
	MOVL  BP, DX
	SHRL  $8, DX
	SHLL  $6, DX
	LEAQ  (R10)(DX*1), DI
	MOVBLZX (DI), AX
	SUBL  $1, AX
	ANDL  $63, AX
	CMOVLEQ SI, AX
	ADDQ  $1, BX
	MOVB  AX, (DI)
	MOVL  AX, AX
	ADDQ  AX, DX
	MOVB  BP, (DI)(AX*1)
	MOVL  R11, (R8)(DX*4)
	CMPQ  BX, R15
	JNE   farloop
	MOVQ  0x30(SP), R8
	MOVQ  0x38(SP), R13
	MOVL  0x40(SP), R11
	MOVL  0x48(SP), DI
	MOVQ  0x50(SP), SI
	MOVQ  0x10(SP), BX
	MOVQ  0x18(SP), BP

farfill:
	LEAL  -0x20(R13), AX
	LEAQ  1(SI), DX
	LEAQ  (R8)(AX*1), CX
	MOVQ  AX, R10           // idx = target - 32
	CMPQ  DX, CX
	JCS   upd
	MOVQ  DX, AX
	MOVL  $8, DX
	SUBQ  CX, AX
	ADDL  $1, AX
	CMPL  AX, DX
	CMOVLHI DX, AX
	LEAL  (AX)(R10*1), DX
	CMPL  R10, DX
	JCC   upd
	MOVQ  R13, 0x58(SP)
	MOVL  R10, R12
	MOVQ  0x20(SP), R15
	MOVL  DX, 0x40(SP)
	MOVQ  R8, 0x50(SP)
	MOVQ  CX, R8
	MOVL  0x2c(SP), CX
	PCALIGN $16

fill:
	MOVQ  $0xcf1bbcdcbb000000, DX
	IMULQ (R8), DX
	ADDQ  $1, R8
	XORQ  R15, DX
	SHRQ  CX, DX
	MOVL  DX, AX
	SHRL  $8, AX
	SHLL  $6, AX
	LEAQ  (AX*4), R13
	PREFETCHT0 (BP)(AX*1)
	PREFETCHT0 0x20(BP)(AX*1)
	MOVL  R12, AX
	ANDL  $7, AX
	ADDL  $1, R12
	PREFETCHT0 (BX)(R13*1)
	PREFETCHT0 0x40(BX)(R13*1)
	MOVL  DX, (R14)(AX*4)
	CMPL  R12, 0x40(SP)
	JCS   fill
	MOVQ  0x50(SP), R8
	MOVQ  0x58(SP), R13
	JMP   upd

cmpdict:
	// C: match = dictBase + matchIndex; read32(match) == read32(ip), then
	// ZSTD_count_2segments(ip+4, match+4, iLimit, dictEnd, prefixStart) + 4.
	// The candidate is at most dictLimit - 4 (C: by table construction;
	// else bad, where the Go code reads past d's slice); lowLimit <= it
	// and lowLimit >= dictBaseIdx (lazyRowExtRun), so it lies in
	// d[lowLimit-dictBaseIdx:dictEnd-4], and the count reads d only up to
	// dictEnd, then b from prefixStart, no further than iLimit from ip.
	MOVL  AX, DI
	MOVL  AX, R11
	SUBL  400(SP), R11
	CMPL  R11, $-3
	JCC   bad
	ADDQ  376(SP), AX       // match
	MOVL  (AX), R11
	CMPL  R11, (SI)
	JNE   next
	MOVQ  BX, 408(SP)
	MOVQ  CX, 416(SP)
	MOVQ  R10, 424(SP)
	MOVQ  DX, 432(SP)
	MOVQ  DI, 440(SP)
	LEAQ  4(SI), R9
	LEAQ  4(AX), R10
	MOVQ  384(SP), R13
	SUBQ  R10, R13
	MOVQ  0(SP), CX
	SUBQ  R9, CX
	CMPQ  CX, R13
	CMOVQLT CX, R13         // min(dictEnd - match, iLimit - ip) bytes
	MOVQ  R10, 448(SP)
	CALL  ·fastCount(SB)
	MOVQ  448(SP), R10
	ADDQ  R11, R10
	CMPQ  R10, 384(SP)
	JNE   dictcnt           // the match ends before dictEnd
	MOVQ  R11, 448(SP)
	LEAQ  4(SI)(R11*1), R9
	MOVQ  392(SP), R10      // it goes on at prefixStart
	MOVQ  0(SP), R13
	SUBQ  R9, R13
	CALL  ·fastCount(SB)
	ADDQ  448(SP), R11

dictcnt:
	LEAQ  4(R11), AX        // currentMl
	MOVQ  408(SP), BX
	MOVQ  416(SP), CX
	MOVQ  424(SP), R10
	MOVQ  432(SP), DX
	MOVQ  440(SP), DI
	JMP   counted

none:
	MOVL  $3, CX
	JMP   done

bad:
	MOVQ  368(SP), R15
	MOVQ  P_B, SI
	MOVQ  $-1, AX
	RET

// func lazyRowExt56(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_extDict_generic (row) for mls 5, rowLog 6:
// compressBlockLazyExtDictGeneric's match loop, with the repcode checks
// (REPLEN), the catch up and the lazy skipping step of the extDict parser.
// R15 = p, SI = b; prefixLowest is unused (the frame holds the segments).
// The repcodes live in the rep1/rep2 argument slots, the anchor and counts in
// their result slots. nSeq = -1 reports a table entry at or after the
// position searched (impossible).
TEXT ·lazyRowExt56(SB), NOSPLIT, $128-128
	MOVQ p+0(FP), R15
	MOVQ P_B, SI
	MOVQ P_DICTBASE, AX
	MOVL P_DICTBASEIDX, CX
	SUBQ CX, AX
	MOVQ AX, L_DBIAS
	MOVL P_LOWEST, CX
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_DSTARTP
	MOVL P_DICTLIMIT, CX
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_DENDP
	MOVQ SI, AX
	MOVL P_BASEIDX, DX
	SUBQ DX, AX
	MOVQ AX, L_BBIAS
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_PSTARTP
	MOVQ iend+40(FP), AX
	ADDQ SI, AX
	MOVQ AX, L_IENDP
	MOVQ ip+24(FP), AX
	MOVQ AX, L_IP
	MOVQ anchor+32(FP), AX
	MOVQ AX, anchorOut+88(FP)
	MOVQ $0, nSeq+96(FP)
	MOVQ $0, nLits+104(FP)
	MOVL $0, llType+120(FP)
	MOVL $0, llPos+124(FP)

main:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  finish
	MOVQ $0, L_MLEN
	MOVQ $1, L_OFFBASE      // repcode1ToOffBase
	LEAQ 1(R8), AX
	MOVQ AX, L_START

	// repcode at ip+1
	INCQ  R8
	MOVL  rep1+64(FP), DX
	REPLEN(r0none, r0c1, r0d1, r0c2, r0d2, r0cd, r0done)
	TESTQ R11, R11
	JEQ   search0
	MOVQ  R11, L_MLEN
	CMPQ  depth+72(FP), $0
	JEQ   store

search0:
	MOVQ L_IP, DI
	CALL ·rowSearchExt56(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, L_MLEN
	JLE  nobetter0
	MOVQ AX, L_MLEN
	MOVQ L_IP, CX
	MOVQ CX, L_START
	MOVQ BX, L_OFFBASE

nobetter0:
	CMPQ L_MLEN, $4
	JGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	MOVQ L_IP, AX
	MOVQ AX, CX
	SUBQ anchorOut+88(FP), CX
	SARQ $8, CX              // kSearchStrength
	LEAQ 1(AX)(CX*1), AX     // ip += step + 1; lazySkipping = step > kLazySkippingStep
	MOVQ AX, L_IP
	XORL DX, DX
	CMPQ CX, $8              // kLazySkippingStep
	SETHI DX
	MOVL DX, P_SKIP
	JMP  main

found:
	CMPQ depth+72(FP), $0
	JEQ  catchup

lazy:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch1
	MOVL  rep1+64(FP), DX
	REPLEN(r1none, r1c1, r1d1, r1c2, r1d2, r1cd, r1done)
	TESTQ R11, R11           // mlRep
	JEQ   lsearch1
	LEAQ  (R11)(R11*2), AX   // gain2
	MOVQ  L_MLEN, CX
	LEAQ  (CX)(CX*2), CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX                 // gain1
	CMPQ  AX, CX
	JLE   lsearch1
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch1:
	MOVQ L_IP, DI
	CALL ·rowSearchExt56(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $4, CX
	CMPQ DX, CX
	JLE  ldepth2
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

ldepth2:
	CMPQ depth+72(FP), $2
	JNE  catchup
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch2
	MOVL  rep1+64(FP), DX
	REPLEN(r2none, r2c1, r2d1, r2c2, r2d2, r2cd, r2done)
	TESTQ R11, R11
	JEQ   lsearch2
	MOVQ  R11, AX
	SHLQ  $2, AX
	MOVQ  L_MLEN, CX
	SHLQ  $2, CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX
	CMPQ  AX, CX
	JLE   lsearch2
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch2:
	MOVQ L_IP, DI
	CALL ·rowSearchExt56(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $7, CX
	CMPQ DX, CX
	JLE  catchup
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

catchup:
	MOVQ L_OFFBASE, DX
	CMPQ DX, $3
	JLS  store              // a repcode: no catch up
	SUBQ $3, DX             // offset
	MOVQ L_START, R8
	MOVQ L_MLEN, AX
	// matchIndex = idx(start) - offset, in the extDict (from dictStart) or
	// the prefix (from prefixStart)
	MOVL    P_BASEIDX, CX
	ADDL    R8, CX
	SUBL    DX, CX
	MOVQ    L_BBIAS, R10
	MOVQ    L_PSTARTP, R9
	CMPL    CX, P_DICTLIMIT
	CMOVQCS L_DBIAS, R10
	CMOVQCS L_DSTARTP, R9
	ADDQ    CX, R10         // match

back:
	CMPQ    R8, anchorOut+88(FP)
	JLE     backdone
	CMPQ    R10, R9
	JLS     backdone
	MOVBLZX -1(SI)(R8*1), BX
	MOVBLZX -1(R10), CX
	CMPL    BX, CX
	JNE     backdone
	DECQ    R8
	DECQ    R10
	INCQ    AX
	JMP     back

backdone:
	MOVQ R8, L_START
	MOVQ AX, L_MLEN
	MOVL rep1+64(FP), CX
	MOVL CX, rep2+68(FP)    // offset2 = offset1
	MOVL DX, rep1+64(FP)    // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVQ L_START, R9
	SUBQ anchorOut+88(FP), R9
	MOVQ L_OFFBASE, R12
	MOVQ L_MLEN, AX
	MOVQ $0, L_RET
	JMP  storeseq

afterstore:
	MOVQ L_START, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	CMPL P_SKIP, $0
	JEQ  reploop
	// leave lazy skipping: ZSTD_row_fillHashCache(ms, base, rowLog, mls, nextToUpdate, ilimit)
	MOVL $0, P_SKIP
	MOVQ P_NEXT, AX
	MOVL (AX), R8            // idx
	MOVL R8, AX
	SUBL P_BASEIDX, AX       // its position
	MOVQ ilimit+48(FP), BX
	SUBQ AX, BX
	JLT  reploop             // idx beyond ilimit: nothing to fill
	INCQ BX
	CMPQ BX, $8
	JLE  fillcnt
	MOVQ $8, BX

fillcnt:
	MOVQ P_CACHE, DX

fillloop:
	MOVL R8, AX
	SUBL P_BASEIDX, AX
	MOVQ (SI)(AX*1), R10
	MOVQ $0xcf1bbcdcbb000000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $6, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	PREFETCHT0 64(CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	PREFETCHT0 32(R11)
	MOVL R8, AX
	ANDL $7, AX
	MOVL R10, (DX)(AX*4)
	INCL R8
	DECQ BX
	JNE  fillloop

reploop:
	// while ip <= ilimit: ml = repMatchLength(ip, idx(ip), offset2), until 0
	MOVQ  L_IP, R8
	CMPQ  R8, ilimit+48(FP)
	JGT   main
	MOVL  rep2+68(FP), DX
	REPLEN(r3none, r3c1, r3d1, r3c2, r3d2, r3cd, r3done)
	TESTQ R11, R11
	JEQ   main
	MOVQ  R11, AX            // matchLength
	MOVL  rep2+68(FP), CX    // swap repcodes
	MOVL  rep1+64(FP), DX
	MOVL  DX, rep2+68(FP)
	MOVL  CX, rep1+64(FP)
	MOVQ  AX, L_MLEN
	XORL  R9, R9             // no literals
	MOVL  $1, R12            // repcode1ToOffBase
	MOVQ  $1, L_RET
	JMP   storeseq

afterrep:
	MOVQ L_IP, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	JMP  reploop

	// storeseq: R9 litLen (from anchor), R12 offBase, AX matchLength;
	// returns to afterstore (L_RET = 0) or afterrep (L_RET = 1).
storeseq:
	TESTQ R9, R9
	JEQ   seq
	MOVQ  lits+16(FP), R10
	ADDQ  nLits+104(FP), R10
	MOVQ  anchorOut+88(FP), R11
	ADDQ  R9, nLits+104(FP)
	// up to 16 literals: one 16-byte copy (C: ZSTD_storeSeq's ZSTD_copy16).
	// The literal buffer has 16 bytes of slack (the Run functions check),
	// and the source must hold the 16 bytes (else fastCopyLits).
	CMPQ  R9, $16
	JA    litcall
	LEAQ  16(R11), CX
	CMPQ  CX, iend+40(FP)
	JA    litcall
	MOVOU (SI)(R11*1), X0
	MOVOU X0, (R10)
	JMP   seq

litcall:
	ADDQ  SI, R11
	CALL  ·fastCopyLits(SB)

seq:
	MOVQ seqs+8(FP), R10
	MOVQ nSeq+96(FP), R11
	MOVL R12, (R10)(R11*8)
	MOVW R9, 4(R10)(R11*8)
	LEAQ -3(AX), CX
	MOVW CX, 6(R10)(R11*8)
	CMPQ R9, $0xFFFF
	JLS  nolongll
	MOVL $1, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongll:
	CMPQ CX, $0xFFFF
	JLS  nolongml
	MOVL $2, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongml:
	INCQ R11
	MOVQ R11, nSeq+96(FP)
	CMPQ L_RET, $0
	JEQ  afterstore
	JMP  afterrep

finish:
	MOVQ L_IP, AX
	MOVQ AX, ipOut+80(FP)
	MOVL rep1+64(FP), AX
	MOVL AX, rep1Out+112(FP)
	MOVL rep2+68(FP), AX
	MOVL AX, rep2Out+116(FP)
	RET

bad:
	MOVQ $-1, nSeq+96(FP)
	RET

// rowSearchExt64: rowFindBestMatchExtDict (mls 6, rowLog 4) at DI = ip,
// R15 = p: rowSearch64 with the candidates below p.dictLimit read in
// the extDict (see EXTDICT in the header).
// Returns AX = ml (below 4: none; -1: a table entry at or after ip, or in
// the extDict's last 3 bytes, impossible), BX = offBase, SI = b. Clobbers
// everything but R15.
// Frame: as rowSearch64, then 376 d - dictBaseIdx, 384 the address of
// dictEnd, 392 of prefixStart, 400 dictLimit, 408-447 spills, 448 a count.
TEXT ·rowSearchExt64(SB), NOSPLIT, $456-0
	MOVQ R15, 368(SP)
	MOVQ R15, R9
	MOVQ Q_B, SI
	MOVQ SI, DX
	ADDQ DI, SI             // ip
	ADDQ Q_ILIMIT, DX       // iLimit
	MOVL $999999999, 8(SP)  // offBaseNotFound
	MOVQ Q_B, R8
	MOVL Q_BASEIDX, AX
	SUBQ AX, R8             // base: an index addresses it directly
	MOVQ Q_DICTBASE, AX
	MOVL Q_DICTBASEIDX, CX
	SUBQ CX, AX
	MOVQ AX, 376(SP)        // d - dictBaseIdx: an extDict index addresses it
	MOVL Q_DICTLIMIT, CX
	MOVL CX, 400(SP)
	ADDQ CX, AX
	MOVQ AX, 384(SP)        // the address of dictEnd
	LEAQ (R8)(CX*1), AX
	MOVQ AX, 392(SP)        // the address of prefixStart
	MOVQ SI, R13
	MOVQ Q_HASHTABLE, BX
	MOVQ Q_TAGTABLE, BP
	MOVQ DX, 0(SP)
	SUBQ R8, R13            // curr
	MOVL Q_MAXDIST, DX
	MOVL R13, R10
	MOVL R13, CX
	MOVL Q_LOWEST, AX
	SUBL DX, CX
	MOVQ BX, 0x10(SP)
	MOVQ BP, 0x18(SP)
	SUBL AX, R10
	MOVQ R8, 0x30(SP)
	CMPL DX, R10
	MOVL Q_ISDICT, DX
	MOVL R13, 0x28(SP)
	CMOVLCC AX, CX          // withinMaxDistance
	TESTL DX, DX
	MOVL CX, R11
	CMOVLNE AX, R11         // lowLimit = isDictionary ? lowestValid : withinMaxDistance
	MOVQ Q_SALT, AX
	MOVQ AX, 0x20(SP)
	MOVL Q_ATTEMPTS, DI
	MOVQ Q_HSHIFT, AX
	MOVL AX, 0x2c(SP)
	MOVL Q_SKIP, CX
	TESTL CX, CX
	JNE  skipping
	MOVQ Q_NEXT, AX
	MOVL (AX), R10          // idx = nextToUpdate
	MOVL R13, AX
	MOVQ Q_CACHE, R14
	SUBL R10, AX
	CMPL AX, $0x180         // kSkipThreshold
	JHI  far

upd:
	// ZSTD_row_update_internalImpl for [R10, R13)
	CMPL R10, R13
	JCC  hash
	MOVQ 0x30(SP), DX
	MOVQ R13, 0x38(SP)
	MOVL 0x2c(SP), CX
	MOVL R10, AX
	MOVQ R8, 0x30(SP)
	MOVQ $0xcf1bbcdcbf9b0000, R15
	MOVL DI, 0x40(SP)
	LEAQ 8(DX)(AX*1), R12
	MOVQ SI, 0x48(SP)
	MOVL 0x28(SP), SI
	MOVQ 0x20(SP), R9       // salt (p is reloaded after the loop)
	MOVL $15, DI
	PCALIGN $16

updloop:
	MOVQ  (R12), DX
	IMULQ R15, DX
	XORQ  R9, DX
	SHRQ  CX, DX            // newHash
	MOVL  DX, AX
	SHRL  $8, AX
	SHLL  $4, AX
	PREFETCHT0 (BP)(AX*1)
	PREFETCHT0 (BX)(AX*4)
	MOVL  R10, R8
	ANDL  $7, R8
	MOVL  (R14)(R8*4), R13  // hash
	MOVL  DX, (R14)(R8*4)
	MOVL  R13, DX
	SHRL  $8, DX
	SHLL  $4, DX       // relRow
	MOVBLZX (BP)(DX*1), AX
	SUBL  $1, AX
	ANDL  $15, AX
	CMOVLEQ DI, AX          // head 0 wraps to rowMask
	MOVB  AX, (BP)(DX*1)
	ADDQ  AX, DX
	MOVB  R13, (BP)(DX*1)
	MOVL  R10, (BX)(DX*4)
	ADDQ  $1, R12
	ADDL  $1, R10
	CMPL  SI, R10
	JNE   updloop
	MOVQ  368(SP), R9
	MOVQ  0x30(SP), R8
	MOVQ  0x38(SP), R13
	MOVL  0x40(SP), DI
	MOVQ  0x48(SP), SI

hash:
	// hash = ZSTD_row_nextCachedHash(curr); nextToUpdate = curr
	MOVL  R13, DX
	MOVQ  0x20(SP), BX
	MOVBLZX 0x2c(SP), CX
	MOVQ  $0xcf1bbcdcbf9b0000, AX
	IMULQ 8(R8)(DX*1), AX
	MOVQ  Q_NEXT, R12
	MOVL  R13, (R12)
	XORQ  BX, AX
	MOVQ  0x10(SP), BX
	SHRQ  CX, AX
	MOVL  AX, DX
	SHRL  $8, DX
	SHLL  $4, DX
	LEAQ  (DX*4), CX
	PREFETCHT0 (BX)(CX*1)
	MOVQ  0x18(SP), BX
	PREFETCHT0 (BX)(DX*1)
	MOVQ  R13, DX
	ANDL  $7, DX
	LEAQ  (R14)(DX*4), DX
	MOVL  (DX), R12
	MOVL  AX, (DX)

havehash:
	MOVL  R12, BX
	MOVQ  0x10(SP), AX
	MOVQ  R12, X0
	MOVQ  Q_ENTROPY, CX
	ADDL  R12, (CX)         // collect salt entropy
	SHRL  $8, BX
	PUNPCKLBW X0, X0
	SHLL  $4, BX       // relRow
	PUNPCKLWL X0, X0
	LEAQ  (AX)(BX*4), BP    // row
	MOVQ  0x18(SP), AX
	PSHUFL $0, X0, X0
	ADDQ  BX, AX            // tagRow

	// matches: tags equal to tag, rotated right by headGrouped (C: ZSTD_row_getSSEMask)
	MOVOU (AX), X1
	MOVBLZX (AX), CX
	MOVQ  AX, BX
	PCMPEQB X1, X0
	MOVL  CX, R13
	ANDL  $0xf, R13         // headGrouped
	PMOVMSKB X0, R10
	CMPB  ·useRowBMI(SB), $0
	JEQ   slow
	CMPL  DI, $15
	JCS   slow              // nbAttempts < rowEntries - 1: C's loop
	ANDQ  $-2, R10          // the head entry is never a candidate
	MOVQ  R10, DX
	RORW  CX, DX
	MOVWLZX DX, DX
	TESTQ R10, R10
	JEQ   insert
	MOVL  0x28(SP), R15     // curr
	XORL  R10, R10
	PCALIGN $16

gfast:
	XORL  AX, AX
	TZCNTQ DX, AX  // DX != 0 here and below: TZCNT runs as BSF without BMI1, same result
	ADDL  R13, AX
	ANDL  $15, AX    // matchPos
	MOVL  (BP)(AX*4), R14   // matchIndex
	CMPL  R14, R11
	JCS   insert            // below lowLimit: stop
	// Bounds: lowLimit <= R14 < curr, and lowLimit >= baseIdx (rowAsmSetup
	// checks lowestValid >= baseIdx, and lazyRowRun lowestValid <= curr, so
	// curr - lowestValid does not wrap and curr - maxDistance is used only
	// when it is above lowestValid). So R8 + R14 lies in b[0:ip], and the
	// compare and count below read only b[R14-baseIdx:] up to the
	// iLimit - ip bytes that b[ip:] holds. Only buffered candidates are
	// read, and every one passed this check, so the compare loop needs none.
	CMPL  R14, R15
	JCC   bad
	MOVQ  R8, AX
	CMPL  R14, 400(SP)
	CMOVQCS 376(SP), AX     // the candidate's segment
	PREFETCHT0 (AX)(R14*1)
	MOVL  R14, 0x60(SP)(R10*4)
	ADDQ  $1, R10
	BLSRQ DX, DX
	JNE   gfast
	JMP   insert

slow:
	MOVQ  R10, DX
	RORW  CX, DX
	MOVWLZX DX, DX
	TESTQ R10, R10
	JEQ   insert

gslow:
	XORL  R10, R10
	JMP   gnext
	PCALIGN $16

gtake:
	CMPL  R14, 0x28(SP)     // idx < curr (see gfast)
	JCC   bad
	SUBL  $1, DI
	MOVQ  R8, AX
	CMPL  R14, 400(SP)
	CMOVQCS 376(SP), AX     // the candidate's segment
	PREFETCHT0 (AX)(R14*1)
	MOVL  R14, 0x60(SP)(R10*4)
	ADDQ  $1, R10

gskip:
	LEAQ  -1(DX), AX
	ANDQ  AX, DX
	JEQ   insert
	TESTL DI, DI
	JEQ   insert

gnext:
	XORL  AX, AX
	TZCNTQ DX, AX  // DX != 0 (TZCNT = BSF without BMI1)
	ADDL  R13, AX
	ANDL  $15, AX
	MOVL  AX, R14
	MOVL  (BP)(R14*4), R14
	JEQ   gskip             // matchPos 0 is the head entry
	CMPL  R14, R11
	JCC   gtake

insert:
	// insert curr (nextToUpdate) into the row; nextToUpdate++
	LEAL  15(CX), AX  // (head - 1) & rowMask, CX the raw head byte
	MOVL  $15, DX
	ANDL  $15, AX
	CMOVLEQ DX, AX
	MOVB  AX, (BX)
	MOVL  AX, AX
	MOVB  R12, (BX)(AX*1)
	MOVQ  Q_NEXT, DI
	MOVL  (DI), DX
	LEAL  1(DX), CX
	MOVL  CX, (DI)
	MOVL  DX, (BP)(AX*4)
	TESTQ R10, R10
	JEQ   none
	MOVQ  0(SP), AX
	MOVL  0x28(SP), BP
	MOVL  $3, CX            // ml
	XORL  DX, DX
	LEAQ  0x60(SP), BX
	LEAQ  -7(AX), R12  // iLimit - 7, -3, -1: ZSTD_count's 8, 4, 2-byte step limits
	ADDL  $3, BP
	LEAQ  -3(AX), R15
	LEAQ  -1(AX), R14
	JMP   cmp
	PCALIGN $16

next:
	ADDQ  $1, DX
	CMPQ  DX, R10
	JEQ   done

cmp:
	MOVL  (BX)(DX*4), AX
	CMPL  AX, 400(SP)
	JCS   cmpdict           // an extDict candidate
	MOVL  -3(SI)(CX*1), R11
	MOVQ  AX, DI
	ADDQ  R8, AX            // match
	CMPL  -3(AX)(CX*1), R11
	JNE   next
	// ZSTD_count(ip, match, iLimit)
	CMPQ  SI, R12
	JCC   cnt4ip
	MOVQ  (AX), R9
	MOVQ  (SI), R11
	CMPQ  R9, R11
	JEQ   cnt8
	XORQ  R11, R9
	XORL  AX, AX
	TZCNTQ R9, AX  // R9 != 0 (TZCNT = BSF without BMI1)
	SHRL  $3, AX

counted:
	CMPQ  CX, AX
	JCC   next
	MOVL  BP, CX
	SUBL  DI, CX
	MOVL  CX, 8(SP)         // offBase = curr - matchIndex + REP_NUM
	LEAQ  (SI)(AX*1), CX
	CMPQ  0(SP), CX
	MOVQ  AX, CX
	JNE   next              // ip + ml == iLimit: the best possible

done:
	MOVQ  CX, AX
	MOVL  8(SP), BX
	MOVQ  368(SP), R15
	MOVQ  P_B, SI
	RET
	PCALIGN $16

cnt4ip:
	MOVQ  SI, R11

cnt4:
	CMPQ  R11, R15
	JCC   cnt2
	MOVL  (R11), R9
	CMPL  (AX), R9
	JNE   cnt2
	ADDQ  $4, R11
	ADDQ  $4, AX
	PCALIGN $16

cnt2:
	CMPQ  R11, R14
	JCC   cnt1
	MOVWLZX (R11), R9
	CMPW  (AX), R9
	JNE   cnt1
	ADDQ  $2, R11
	ADDQ  $2, AX
	PCALIGN $16

cnt1:
	MOVQ  0(SP), R9
	CMPQ  R11, R9
	JCC   cntend
	MOVBLZX (R11), R9
	CMPB  (AX), R9
	SETEQ AL
	MOVBLZX AL, AX
	ADDQ  AX, R11

cntend:
	MOVQ  R11, AX
	SUBQ  SI, AX
	JMP   counted
	PCALIGN $8

cnt8:
	LEAQ  8(SI), R11
	ADDQ  $8, AX
	CMPB  ·useAVX2(SB), $0
	JEQ   cnt8chk

cnt32:
	// 32 bytes per step with AVX2 (as fastCount), while R11 + 32 <= iLimit
	LEAQ  32(R11), R9
	CMPQ  R9, 0(SP)
	JHI   cnt32end
	VMOVDQU   (R11), Y0
	VPCMPEQB  (AX), Y0, Y0
	VPMOVMSKB Y0, R9
	INCL  R9
	JNE   cnt32diff
	ADDQ  $32, R11
	ADDQ  $32, AX
	JMP   cnt32

cnt32diff:
	VZEROUPPER
	BSFL  R9, R9
	LEAQ  (R11)(R9*1), AX
	SUBQ  SI, AX
	JMP   counted

cnt32end:
	VZEROUPPER

cnt8chk:
	CMPQ  R11, R12
	JCC   cnt4

cnt8loop:
	MOVQ  (AX), R9
	MOVQ  (R11), R13
	CMPQ  R9, R13
	JEQ   cnt8next
	XORQ  R13, R9
	XORL  AX, AX
	TZCNTQ R9, AX  // R9 != 0 (TZCNT = BSF without BMI1)
	SHRL  $3, AX
	ADDQ  R11, AX
	SUBQ  SI, AX
	JMP   counted
	PCALIGN $16

skipping:
	// lazy skipping: hash ip directly, without the cache or the row update
	MOVQ  $0xcf1bbcdcbf9b0000, R12
	IMULQ (SI), R12
	MOVQ  0x20(SP), AX
	MOVQ  Q_NEXT, CX
	MOVL  R13, (CX)         // nextToUpdate = curr
	MOVBLZX 0x2c(SP), CX
	XORQ  AX, R12
	SHRQ  CX, R12
	JMP   havehash
	PCALIGN $16

cnt8next:
	ADDQ  $8, R11
	ADDQ  $8, AX
	CMPQ  R11, R12
	JCS   cnt8loop
	JMP   cnt4

far:
	// target - idx > kSkipThreshold: update [idx, idx + 96), then refill the
	// cache from target - 32 (C: ZSTD_row_fillHashCache, up to ip + 1)
	CMPL  R10, $0xffffff9f  // idx + kMaxMatchStartPositionsToUpdate (96) would wrap: skip
	JHI   farfill
	MOVL  R10, AX
	MOVQ  R13, 0x38(SP)
	MOVL  0x2c(SP), CX
	MOVQ  $0xcf1bbcdcbf9b0000, R12
	LEAQ  8(R8)(AX*1), BX
	LEAQ  0x68(R8)(AX*1), R15
	MOVQ  0x20(SP), AX
	MOVL  R11, 0x40(SP)
	SUBL  BX, R10  // idx - pointer (mod 2^32), kept in R13: idx = R13 + pointer
	MOVL  DI, 0x48(SP)
	MOVQ  0x10(SP), R8
	MOVL  R10, BP
	MOVQ  SI, 0x50(SP)
	MOVQ  0x18(SP), R10
	MOVQ  AX, DX
	MOVL  BP, R13
	JMP   farin
	PCALIGN $16

farloop:
	MOVQ  Q_SALT, DX

farin:
	MOVQ  (BX), AX
	LEAL  (R13)(BX*1), R11  // idx, rebuilt from the moving pointer
	MOVL  $15, SI
	IMULQ R12, AX
	XORQ  AX, DX
	SHRQ  CX, DX
	MOVL  DX, AX
	SHRL  $8, AX
	SHLL  $4, AX
	PREFETCHT0 (R10)(AX*1)
	LEAQ  (AX*4), DI
	MOVL  R11, AX
	ANDL  $7, AX
	PREFETCHT0 (R8)(DI*1)
	LEAQ  (R14)(AX*4), AX
	MOVL  (AX), BP
	MOVL  DX, (AX)
	MOVL  BP, DX
	SHRL  $8, DX
	SHLL  $4, DX
	LEAQ  (R10)(DX*1), DI
	MOVBLZX (DI), AX
	SUBL  $1, AX
	ANDL  $15, AX
	CMOVLEQ SI, AX
	ADDQ  $1, BX
	MOVB  AX, (DI)
	MOVL  AX, AX
	ADDQ  AX, DX
	MOVB  BP, (DI)(AX*1)
	MOVL  R11, (R8)(DX*4)
	CMPQ  BX, R15
	JNE   farloop
	MOVQ  0x30(SP), R8
	MOVQ  0x38(SP), R13
	MOVL  0x40(SP), R11
	MOVL  0x48(SP), DI
	MOVQ  0x50(SP), SI
	MOVQ  0x10(SP), BX
	MOVQ  0x18(SP), BP

farfill:
	LEAL  -0x20(R13), AX
	LEAQ  1(SI), DX
	LEAQ  (R8)(AX*1), CX
	MOVQ  AX, R10           // idx = target - 32
	CMPQ  DX, CX
	JCS   upd
	MOVQ  DX, AX
	MOVL  $8, DX
	SUBQ  CX, AX
	ADDL  $1, AX
	CMPL  AX, DX
	CMOVLHI DX, AX
	LEAL  (AX)(R10*1), DX
	CMPL  R10, DX
	JCC   upd
	MOVQ  R13, 0x58(SP)
	MOVL  R10, R12
	MOVQ  0x20(SP), R15
	MOVL  DX, 0x40(SP)
	MOVQ  R8, 0x50(SP)
	MOVQ  CX, R8
	MOVL  0x2c(SP), CX
	PCALIGN $16

fill:
	MOVQ  $0xcf1bbcdcbf9b0000, DX
	IMULQ (R8), DX
	ADDQ  $1, R8
	XORQ  R15, DX
	SHRQ  CX, DX
	MOVL  DX, AX
	SHRL  $8, AX
	SHLL  $4, AX
	LEAQ  (AX*4), R13
	PREFETCHT0 (BP)(AX*1)
	MOVL  R12, AX
	ANDL  $7, AX
	ADDL  $1, R12
	PREFETCHT0 (BX)(R13*1)
	MOVL  DX, (R14)(AX*4)
	CMPL  R12, 0x40(SP)
	JCS   fill
	MOVQ  0x50(SP), R8
	MOVQ  0x58(SP), R13
	JMP   upd

cmpdict:
	// C: match = dictBase + matchIndex; read32(match) == read32(ip), then
	// ZSTD_count_2segments(ip+4, match+4, iLimit, dictEnd, prefixStart) + 4.
	// The candidate is at most dictLimit - 4 (C: by table construction;
	// else bad, where the Go code reads past d's slice); lowLimit <= it
	// and lowLimit >= dictBaseIdx (lazyRowExtRun), so it lies in
	// d[lowLimit-dictBaseIdx:dictEnd-4], and the count reads d only up to
	// dictEnd, then b from prefixStart, no further than iLimit from ip.
	MOVL  AX, DI
	MOVL  AX, R11
	SUBL  400(SP), R11
	CMPL  R11, $-3
	JCC   bad
	ADDQ  376(SP), AX       // match
	MOVL  (AX), R11
	CMPL  R11, (SI)
	JNE   next
	MOVQ  BX, 408(SP)
	MOVQ  CX, 416(SP)
	MOVQ  R10, 424(SP)
	MOVQ  DX, 432(SP)
	MOVQ  DI, 440(SP)
	LEAQ  4(SI), R9
	LEAQ  4(AX), R10
	MOVQ  384(SP), R13
	SUBQ  R10, R13
	MOVQ  0(SP), CX
	SUBQ  R9, CX
	CMPQ  CX, R13
	CMOVQLT CX, R13         // min(dictEnd - match, iLimit - ip) bytes
	MOVQ  R10, 448(SP)
	CALL  ·fastCount(SB)
	MOVQ  448(SP), R10
	ADDQ  R11, R10
	CMPQ  R10, 384(SP)
	JNE   dictcnt           // the match ends before dictEnd
	MOVQ  R11, 448(SP)
	LEAQ  4(SI)(R11*1), R9
	MOVQ  392(SP), R10      // it goes on at prefixStart
	MOVQ  0(SP), R13
	SUBQ  R9, R13
	CALL  ·fastCount(SB)
	ADDQ  448(SP), R11

dictcnt:
	LEAQ  4(R11), AX        // currentMl
	MOVQ  408(SP), BX
	MOVQ  416(SP), CX
	MOVQ  424(SP), R10
	MOVQ  432(SP), DX
	MOVQ  440(SP), DI
	JMP   counted

none:
	MOVL  $3, CX
	JMP   done

bad:
	MOVQ  368(SP), R15
	MOVQ  P_B, SI
	MOVQ  $-1, AX
	RET

// func lazyRowExt64(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_extDict_generic (row) for mls 6, rowLog 4:
// compressBlockLazyExtDictGeneric's match loop, with the repcode checks
// (REPLEN), the catch up and the lazy skipping step of the extDict parser.
// R15 = p, SI = b; prefixLowest is unused (the frame holds the segments).
// The repcodes live in the rep1/rep2 argument slots, the anchor and counts in
// their result slots. nSeq = -1 reports a table entry at or after the
// position searched (impossible).
TEXT ·lazyRowExt64(SB), NOSPLIT, $128-128
	MOVQ p+0(FP), R15
	MOVQ P_B, SI
	MOVQ P_DICTBASE, AX
	MOVL P_DICTBASEIDX, CX
	SUBQ CX, AX
	MOVQ AX, L_DBIAS
	MOVL P_LOWEST, CX
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_DSTARTP
	MOVL P_DICTLIMIT, CX
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_DENDP
	MOVQ SI, AX
	MOVL P_BASEIDX, DX
	SUBQ DX, AX
	MOVQ AX, L_BBIAS
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_PSTARTP
	MOVQ iend+40(FP), AX
	ADDQ SI, AX
	MOVQ AX, L_IENDP
	MOVQ ip+24(FP), AX
	MOVQ AX, L_IP
	MOVQ anchor+32(FP), AX
	MOVQ AX, anchorOut+88(FP)
	MOVQ $0, nSeq+96(FP)
	MOVQ $0, nLits+104(FP)
	MOVL $0, llType+120(FP)
	MOVL $0, llPos+124(FP)

main:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  finish
	MOVQ $0, L_MLEN
	MOVQ $1, L_OFFBASE      // repcode1ToOffBase
	LEAQ 1(R8), AX
	MOVQ AX, L_START

	// repcode at ip+1
	INCQ  R8
	MOVL  rep1+64(FP), DX
	REPLEN(r0none, r0c1, r0d1, r0c2, r0d2, r0cd, r0done)
	TESTQ R11, R11
	JEQ   search0
	MOVQ  R11, L_MLEN
	CMPQ  depth+72(FP), $0
	JEQ   store

search0:
	MOVQ L_IP, DI
	CALL ·rowSearchExt64(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, L_MLEN
	JLE  nobetter0
	MOVQ AX, L_MLEN
	MOVQ L_IP, CX
	MOVQ CX, L_START
	MOVQ BX, L_OFFBASE

nobetter0:
	CMPQ L_MLEN, $4
	JGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	MOVQ L_IP, AX
	MOVQ AX, CX
	SUBQ anchorOut+88(FP), CX
	SARQ $8, CX              // kSearchStrength
	LEAQ 1(AX)(CX*1), AX     // ip += step + 1; lazySkipping = step > kLazySkippingStep
	MOVQ AX, L_IP
	XORL DX, DX
	CMPQ CX, $8              // kLazySkippingStep
	SETHI DX
	MOVL DX, P_SKIP
	JMP  main

found:
	CMPQ depth+72(FP), $0
	JEQ  catchup

lazy:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch1
	MOVL  rep1+64(FP), DX
	REPLEN(r1none, r1c1, r1d1, r1c2, r1d2, r1cd, r1done)
	TESTQ R11, R11           // mlRep
	JEQ   lsearch1
	LEAQ  (R11)(R11*2), AX   // gain2
	MOVQ  L_MLEN, CX
	LEAQ  (CX)(CX*2), CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX                 // gain1
	CMPQ  AX, CX
	JLE   lsearch1
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch1:
	MOVQ L_IP, DI
	CALL ·rowSearchExt64(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $4, CX
	CMPQ DX, CX
	JLE  ldepth2
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

ldepth2:
	CMPQ depth+72(FP), $2
	JNE  catchup
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch2
	MOVL  rep1+64(FP), DX
	REPLEN(r2none, r2c1, r2d1, r2c2, r2d2, r2cd, r2done)
	TESTQ R11, R11
	JEQ   lsearch2
	MOVQ  R11, AX
	SHLQ  $2, AX
	MOVQ  L_MLEN, CX
	SHLQ  $2, CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX
	CMPQ  AX, CX
	JLE   lsearch2
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch2:
	MOVQ L_IP, DI
	CALL ·rowSearchExt64(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $7, CX
	CMPQ DX, CX
	JLE  catchup
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

catchup:
	MOVQ L_OFFBASE, DX
	CMPQ DX, $3
	JLS  store              // a repcode: no catch up
	SUBQ $3, DX             // offset
	MOVQ L_START, R8
	MOVQ L_MLEN, AX
	// matchIndex = idx(start) - offset, in the extDict (from dictStart) or
	// the prefix (from prefixStart)
	MOVL    P_BASEIDX, CX
	ADDL    R8, CX
	SUBL    DX, CX
	MOVQ    L_BBIAS, R10
	MOVQ    L_PSTARTP, R9
	CMPL    CX, P_DICTLIMIT
	CMOVQCS L_DBIAS, R10
	CMOVQCS L_DSTARTP, R9
	ADDQ    CX, R10         // match

back:
	CMPQ    R8, anchorOut+88(FP)
	JLE     backdone
	CMPQ    R10, R9
	JLS     backdone
	MOVBLZX -1(SI)(R8*1), BX
	MOVBLZX -1(R10), CX
	CMPL    BX, CX
	JNE     backdone
	DECQ    R8
	DECQ    R10
	INCQ    AX
	JMP     back

backdone:
	MOVQ R8, L_START
	MOVQ AX, L_MLEN
	MOVL rep1+64(FP), CX
	MOVL CX, rep2+68(FP)    // offset2 = offset1
	MOVL DX, rep1+64(FP)    // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVQ L_START, R9
	SUBQ anchorOut+88(FP), R9
	MOVQ L_OFFBASE, R12
	MOVQ L_MLEN, AX
	MOVQ $0, L_RET
	JMP  storeseq

afterstore:
	MOVQ L_START, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	CMPL P_SKIP, $0
	JEQ  reploop
	// leave lazy skipping: ZSTD_row_fillHashCache(ms, base, rowLog, mls, nextToUpdate, ilimit)
	MOVL $0, P_SKIP
	MOVQ P_NEXT, AX
	MOVL (AX), R8            // idx
	MOVL R8, AX
	SUBL P_BASEIDX, AX       // its position
	MOVQ ilimit+48(FP), BX
	SUBQ AX, BX
	JLT  reploop             // idx beyond ilimit: nothing to fill
	INCQ BX
	CMPQ BX, $8
	JLE  fillcnt
	MOVQ $8, BX

fillcnt:
	MOVQ P_CACHE, DX

fillloop:
	MOVL R8, AX
	SUBL P_BASEIDX, AX
	MOVQ (SI)(AX*1), R10
	MOVQ $0xcf1bbcdcbf9b0000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $4, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	MOVL R8, AX
	ANDL $7, AX
	MOVL R10, (DX)(AX*4)
	INCL R8
	DECQ BX
	JNE  fillloop

reploop:
	// while ip <= ilimit: ml = repMatchLength(ip, idx(ip), offset2), until 0
	MOVQ  L_IP, R8
	CMPQ  R8, ilimit+48(FP)
	JGT   main
	MOVL  rep2+68(FP), DX
	REPLEN(r3none, r3c1, r3d1, r3c2, r3d2, r3cd, r3done)
	TESTQ R11, R11
	JEQ   main
	MOVQ  R11, AX            // matchLength
	MOVL  rep2+68(FP), CX    // swap repcodes
	MOVL  rep1+64(FP), DX
	MOVL  DX, rep2+68(FP)
	MOVL  CX, rep1+64(FP)
	MOVQ  AX, L_MLEN
	XORL  R9, R9             // no literals
	MOVL  $1, R12            // repcode1ToOffBase
	MOVQ  $1, L_RET
	JMP   storeseq

afterrep:
	MOVQ L_IP, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	JMP  reploop

	// storeseq: R9 litLen (from anchor), R12 offBase, AX matchLength;
	// returns to afterstore (L_RET = 0) or afterrep (L_RET = 1).
storeseq:
	TESTQ R9, R9
	JEQ   seq
	MOVQ  lits+16(FP), R10
	ADDQ  nLits+104(FP), R10
	MOVQ  anchorOut+88(FP), R11
	ADDQ  R9, nLits+104(FP)
	// up to 16 literals: one 16-byte copy (C: ZSTD_storeSeq's ZSTD_copy16).
	// The literal buffer has 16 bytes of slack (the Run functions check),
	// and the source must hold the 16 bytes (else fastCopyLits).
	CMPQ  R9, $16
	JA    litcall
	LEAQ  16(R11), CX
	CMPQ  CX, iend+40(FP)
	JA    litcall
	MOVOU (SI)(R11*1), X0
	MOVOU X0, (R10)
	JMP   seq

litcall:
	ADDQ  SI, R11
	CALL  ·fastCopyLits(SB)

seq:
	MOVQ seqs+8(FP), R10
	MOVQ nSeq+96(FP), R11
	MOVL R12, (R10)(R11*8)
	MOVW R9, 4(R10)(R11*8)
	LEAQ -3(AX), CX
	MOVW CX, 6(R10)(R11*8)
	CMPQ R9, $0xFFFF
	JLS  nolongll
	MOVL $1, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongll:
	CMPQ CX, $0xFFFF
	JLS  nolongml
	MOVL $2, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongml:
	INCQ R11
	MOVQ R11, nSeq+96(FP)
	CMPQ L_RET, $0
	JEQ  afterstore
	JMP  afterrep

finish:
	MOVQ L_IP, AX
	MOVQ AX, ipOut+80(FP)
	MOVL rep1+64(FP), AX
	MOVL AX, rep1Out+112(FP)
	MOVL rep2+68(FP), AX
	MOVL AX, rep2Out+116(FP)
	RET

bad:
	MOVQ $-1, nSeq+96(FP)
	RET

// rowSearchExt65: rowFindBestMatchExtDict (mls 6, rowLog 5) at DI = ip,
// R15 = p: rowSearch65 with the candidates below p.dictLimit read in
// the extDict (see EXTDICT in the header).
// Returns AX = ml (below 4: none; -1: a table entry at or after ip, or in
// the extDict's last 3 bytes, impossible), BX = offBase, SI = b. Clobbers
// everything but R15.
// Frame: as rowSearch65, then 376 d - dictBaseIdx, 384 the address of
// dictEnd, 392 of prefixStart, 400 dictLimit, 408-447 spills, 448 a count.
TEXT ·rowSearchExt65(SB), NOSPLIT, $456-0
	MOVQ R15, 368(SP)
	MOVQ R15, R9
	MOVQ Q_B, SI
	MOVQ SI, DX
	ADDQ DI, SI             // ip
	ADDQ Q_ILIMIT, DX       // iLimit
	MOVL $999999999, 8(SP)  // offBaseNotFound
	MOVQ Q_B, R8
	MOVL Q_BASEIDX, AX
	SUBQ AX, R8             // base: an index addresses it directly
	MOVQ Q_DICTBASE, AX
	MOVL Q_DICTBASEIDX, CX
	SUBQ CX, AX
	MOVQ AX, 376(SP)        // d - dictBaseIdx: an extDict index addresses it
	MOVL Q_DICTLIMIT, CX
	MOVL CX, 400(SP)
	ADDQ CX, AX
	MOVQ AX, 384(SP)        // the address of dictEnd
	LEAQ (R8)(CX*1), AX
	MOVQ AX, 392(SP)        // the address of prefixStart
	MOVQ SI, R13
	MOVQ Q_HASHTABLE, BX
	MOVQ Q_TAGTABLE, BP
	MOVQ DX, 0(SP)
	SUBQ R8, R13            // curr
	MOVL Q_MAXDIST, DX
	MOVL R13, R10
	MOVL R13, CX
	MOVL Q_LOWEST, AX
	SUBL DX, CX
	MOVQ BX, 0x10(SP)
	MOVQ BP, 0x18(SP)
	SUBL AX, R10
	MOVQ R8, 0x30(SP)
	CMPL DX, R10
	MOVL Q_ISDICT, DX
	MOVL R13, 0x28(SP)
	CMOVLCC AX, CX          // withinMaxDistance
	TESTL DX, DX
	MOVL CX, R11
	CMOVLNE AX, R11         // lowLimit = isDictionary ? lowestValid : withinMaxDistance
	MOVQ Q_SALT, AX
	MOVQ AX, 0x20(SP)
	MOVL Q_ATTEMPTS, DI
	MOVQ Q_HSHIFT, AX
	MOVL AX, 0x2c(SP)
	MOVL Q_SKIP, CX
	TESTL CX, CX
	JNE  skipping
	MOVQ Q_NEXT, AX
	MOVL (AX), R10          // idx = nextToUpdate
	MOVL R13, AX
	MOVQ Q_CACHE, R14
	SUBL R10, AX
	CMPL AX, $0x180         // kSkipThreshold
	JHI  far

upd:
	// ZSTD_row_update_internalImpl for [R10, R13)
	CMPL R10, R13
	JCC  hash
	MOVQ 0x30(SP), DX
	MOVQ R13, 0x38(SP)
	MOVL 0x2c(SP), CX
	MOVL R10, AX
	MOVQ R8, 0x30(SP)
	MOVQ $0xcf1bbcdcbf9b0000, R15
	MOVL DI, 0x40(SP)
	LEAQ 8(DX)(AX*1), R12
	MOVQ SI, 0x48(SP)
	MOVL 0x28(SP), SI
	MOVQ 0x20(SP), R9       // salt (p is reloaded after the loop)
	MOVL $31, DI
	PCALIGN $16

updloop:
	MOVQ  (R12), DX
	IMULQ R15, DX
	XORQ  R9, DX
	SHRQ  CX, DX            // newHash
	MOVL  DX, AX
	SHRL  $8, AX
	SHLL  $5, AX
	PREFETCHT0 (BP)(AX*1)
	PREFETCHT0 (BX)(AX*4)
	PREFETCHT0 0x40(BX)(AX*4)
	MOVL  R10, R8
	ANDL  $7, R8
	MOVL  (R14)(R8*4), R13  // hash
	MOVL  DX, (R14)(R8*4)
	MOVL  R13, DX
	SHRL  $8, DX
	SHLL  $5, DX       // relRow
	MOVBLZX (BP)(DX*1), AX
	SUBL  $1, AX
	ANDL  $31, AX
	CMOVLEQ DI, AX          // head 0 wraps to rowMask
	MOVB  AX, (BP)(DX*1)
	ADDQ  AX, DX
	MOVB  R13, (BP)(DX*1)
	MOVL  R10, (BX)(DX*4)
	ADDQ  $1, R12
	ADDL  $1, R10
	CMPL  SI, R10
	JNE   updloop
	MOVQ  368(SP), R9
	MOVQ  0x30(SP), R8
	MOVQ  0x38(SP), R13
	MOVL  0x40(SP), DI
	MOVQ  0x48(SP), SI

hash:
	// hash = ZSTD_row_nextCachedHash(curr); nextToUpdate = curr
	MOVL  R13, DX
	MOVQ  0x20(SP), BX
	MOVBLZX 0x2c(SP), CX
	MOVQ  $0xcf1bbcdcbf9b0000, AX
	IMULQ 8(R8)(DX*1), AX
	MOVQ  Q_NEXT, R12
	MOVL  R13, (R12)
	XORQ  BX, AX
	MOVQ  0x10(SP), BX
	SHRQ  CX, AX
	MOVL  AX, DX
	SHRL  $8, DX
	SHLL  $5, DX
	LEAQ  (DX*4), CX
	PREFETCHT0 (BX)(CX*1)
	PREFETCHT0 0x40(BX)(CX*1)
	MOVQ  0x18(SP), BX
	PREFETCHT0 (BX)(DX*1)
	MOVQ  R13, DX
	ANDL  $7, DX
	LEAQ  (R14)(DX*4), DX
	MOVL  (DX), R12
	MOVL  AX, (DX)

havehash:
	MOVL  R12, BX
	MOVQ  0x10(SP), AX
	MOVQ  R12, X0
	MOVQ  Q_ENTROPY, CX
	ADDL  R12, (CX)         // collect salt entropy
	SHRL  $8, BX
	PUNPCKLBW X0, X0
	SHLL  $5, BX       // relRow
	PUNPCKLWL X0, X0
	LEAQ  (AX)(BX*4), BP    // row
	MOVQ  0x18(SP), AX
	PSHUFL $0, X0, X0
	ADDQ  BX, AX            // tagRow

	// matches: tags equal to tag, rotated right by headGrouped (C: ZSTD_row_getSSEMask)
	MOVQ  AX, BX
	MOVOU (AX), X1
	MOVBLZX (AX), CX
	MOVOU 0x10(BX), X2
	PCMPEQB X0, X1
	MOVL  CX, R13
	PCMPEQB X2, X0
	ANDL  $0x1f, R13        // headGrouped
	PMOVMSKB X1, AX
	PMOVMSKB X0, R10
	SHLL  $0x10, R10
	ORL   AX, R10
	CMPB  ·useRowBMI(SB), $0
	JEQ   slow
	CMPL  DI, $31
	JCS   slow              // nbAttempts < rowEntries - 1: C's loop
	ANDQ  $-2, R10          // the head entry is never a candidate
	MOVQ  R10, DX
	RORL  CX, DX
	TESTQ R10, R10
	JEQ   insert
	MOVL  0x28(SP), R15     // curr
	XORL  R10, R10
	PCALIGN $16

gfast:
	XORL  AX, AX
	TZCNTQ DX, AX  // DX != 0 here and below: TZCNT runs as BSF without BMI1, same result
	ADDL  R13, AX
	ANDL  $31, AX    // matchPos
	MOVL  (BP)(AX*4), R14   // matchIndex
	CMPL  R14, R11
	JCS   insert            // below lowLimit: stop
	// Bounds: lowLimit <= R14 < curr, and lowLimit >= baseIdx (rowAsmSetup
	// checks lowestValid >= baseIdx, and lazyRowRun lowestValid <= curr, so
	// curr - lowestValid does not wrap and curr - maxDistance is used only
	// when it is above lowestValid). So R8 + R14 lies in b[0:ip], and the
	// compare and count below read only b[R14-baseIdx:] up to the
	// iLimit - ip bytes that b[ip:] holds. Only buffered candidates are
	// read, and every one passed this check, so the compare loop needs none.
	CMPL  R14, R15
	JCC   bad
	MOVQ  R8, AX
	CMPL  R14, 400(SP)
	CMOVQCS 376(SP), AX     // the candidate's segment
	PREFETCHT0 (AX)(R14*1)
	MOVL  R14, 0x60(SP)(R10*4)
	ADDQ  $1, R10
	BLSRQ DX, DX
	JNE   gfast
	JMP   insert

slow:
	MOVQ  R10, DX
	RORL  CX, DX
	TESTQ R10, R10
	JEQ   insert

gslow:
	XORL  R10, R10
	JMP   gnext
	PCALIGN $16

gtake:
	CMPL  R14, 0x28(SP)     // idx < curr (see gfast)
	JCC   bad
	SUBL  $1, DI
	MOVQ  R8, AX
	CMPL  R14, 400(SP)
	CMOVQCS 376(SP), AX     // the candidate's segment
	PREFETCHT0 (AX)(R14*1)
	MOVL  R14, 0x60(SP)(R10*4)
	ADDQ  $1, R10

gskip:
	LEAQ  -1(DX), AX
	ANDQ  AX, DX
	JEQ   insert
	TESTL DI, DI
	JEQ   insert

gnext:
	XORL  AX, AX
	TZCNTQ DX, AX  // DX != 0 (TZCNT = BSF without BMI1)
	ADDL  R13, AX
	ANDL  $31, AX
	MOVL  AX, R14
	MOVL  (BP)(R14*4), R14
	JEQ   gskip             // matchPos 0 is the head entry
	CMPL  R14, R11
	JCC   gtake

insert:
	// insert curr (nextToUpdate) into the row; nextToUpdate++
	LEAL  31(CX), AX  // (head - 1) & rowMask, CX the raw head byte
	MOVL  $31, DX
	ANDL  $31, AX
	CMOVLEQ DX, AX
	MOVB  AX, (BX)
	MOVL  AX, AX
	MOVB  R12, (BX)(AX*1)
	MOVQ  Q_NEXT, DI
	MOVL  (DI), DX
	LEAL  1(DX), CX
	MOVL  CX, (DI)
	MOVL  DX, (BP)(AX*4)
	TESTQ R10, R10
	JEQ   none
	MOVQ  0(SP), AX
	MOVL  0x28(SP), BP
	MOVL  $3, CX            // ml
	XORL  DX, DX
	LEAQ  0x60(SP), BX
	LEAQ  -7(AX), R12  // iLimit - 7, -3, -1: ZSTD_count's 8, 4, 2-byte step limits
	ADDL  $3, BP
	LEAQ  -3(AX), R15
	LEAQ  -1(AX), R14
	JMP   cmp
	PCALIGN $16

next:
	ADDQ  $1, DX
	CMPQ  DX, R10
	JEQ   done

cmp:
	MOVL  (BX)(DX*4), AX
	CMPL  AX, 400(SP)
	JCS   cmpdict           // an extDict candidate
	MOVL  -3(SI)(CX*1), R11
	MOVQ  AX, DI
	ADDQ  R8, AX            // match
	CMPL  -3(AX)(CX*1), R11
	JNE   next
	// ZSTD_count(ip, match, iLimit)
	CMPQ  SI, R12
	JCC   cnt4ip
	MOVQ  (AX), R9
	MOVQ  (SI), R11
	CMPQ  R9, R11
	JEQ   cnt8
	XORQ  R11, R9
	XORL  AX, AX
	TZCNTQ R9, AX  // R9 != 0 (TZCNT = BSF without BMI1)
	SHRL  $3, AX

counted:
	CMPQ  CX, AX
	JCC   next
	MOVL  BP, CX
	SUBL  DI, CX
	MOVL  CX, 8(SP)         // offBase = curr - matchIndex + REP_NUM
	LEAQ  (SI)(AX*1), CX
	CMPQ  0(SP), CX
	MOVQ  AX, CX
	JNE   next              // ip + ml == iLimit: the best possible

done:
	MOVQ  CX, AX
	MOVL  8(SP), BX
	MOVQ  368(SP), R15
	MOVQ  P_B, SI
	RET
	PCALIGN $16

cnt4ip:
	MOVQ  SI, R11

cnt4:
	CMPQ  R11, R15
	JCC   cnt2
	MOVL  (R11), R9
	CMPL  (AX), R9
	JNE   cnt2
	ADDQ  $4, R11
	ADDQ  $4, AX
	PCALIGN $16

cnt2:
	CMPQ  R11, R14
	JCC   cnt1
	MOVWLZX (R11), R9
	CMPW  (AX), R9
	JNE   cnt1
	ADDQ  $2, R11
	ADDQ  $2, AX
	PCALIGN $16

cnt1:
	MOVQ  0(SP), R9
	CMPQ  R11, R9
	JCC   cntend
	MOVBLZX (R11), R9
	CMPB  (AX), R9
	SETEQ AL
	MOVBLZX AL, AX
	ADDQ  AX, R11

cntend:
	MOVQ  R11, AX
	SUBQ  SI, AX
	JMP   counted
	PCALIGN $8

cnt8:
	LEAQ  8(SI), R11
	ADDQ  $8, AX
	CMPB  ·useAVX2(SB), $0
	JEQ   cnt8chk

cnt32:
	// 32 bytes per step with AVX2 (as fastCount), while R11 + 32 <= iLimit
	LEAQ  32(R11), R9
	CMPQ  R9, 0(SP)
	JHI   cnt32end
	VMOVDQU   (R11), Y0
	VPCMPEQB  (AX), Y0, Y0
	VPMOVMSKB Y0, R9
	INCL  R9
	JNE   cnt32diff
	ADDQ  $32, R11
	ADDQ  $32, AX
	JMP   cnt32

cnt32diff:
	VZEROUPPER
	BSFL  R9, R9
	LEAQ  (R11)(R9*1), AX
	SUBQ  SI, AX
	JMP   counted

cnt32end:
	VZEROUPPER

cnt8chk:
	CMPQ  R11, R12
	JCC   cnt4

cnt8loop:
	MOVQ  (AX), R9
	MOVQ  (R11), R13
	CMPQ  R9, R13
	JEQ   cnt8next
	XORQ  R13, R9
	XORL  AX, AX
	TZCNTQ R9, AX  // R9 != 0 (TZCNT = BSF without BMI1)
	SHRL  $3, AX
	ADDQ  R11, AX
	SUBQ  SI, AX
	JMP   counted
	PCALIGN $16

skipping:
	// lazy skipping: hash ip directly, without the cache or the row update
	MOVQ  $0xcf1bbcdcbf9b0000, R12
	IMULQ (SI), R12
	MOVQ  0x20(SP), AX
	MOVQ  Q_NEXT, CX
	MOVL  R13, (CX)         // nextToUpdate = curr
	MOVBLZX 0x2c(SP), CX
	XORQ  AX, R12
	SHRQ  CX, R12
	JMP   havehash
	PCALIGN $16

cnt8next:
	ADDQ  $8, R11
	ADDQ  $8, AX
	CMPQ  R11, R12
	JCS   cnt8loop
	JMP   cnt4

far:
	// target - idx > kSkipThreshold: update [idx, idx + 96), then refill the
	// cache from target - 32 (C: ZSTD_row_fillHashCache, up to ip + 1)
	CMPL  R10, $0xffffff9f  // idx + kMaxMatchStartPositionsToUpdate (96) would wrap: skip
	JHI   farfill
	MOVL  R10, AX
	MOVQ  R13, 0x38(SP)
	MOVL  0x2c(SP), CX
	MOVQ  $0xcf1bbcdcbf9b0000, R12
	LEAQ  8(R8)(AX*1), BX
	LEAQ  0x68(R8)(AX*1), R15
	MOVQ  0x20(SP), AX
	MOVL  R11, 0x40(SP)
	SUBL  BX, R10  // idx - pointer (mod 2^32), kept in R13: idx = R13 + pointer
	MOVL  DI, 0x48(SP)
	MOVQ  0x10(SP), R8
	MOVL  R10, BP
	MOVQ  SI, 0x50(SP)
	MOVQ  0x18(SP), R10
	MOVQ  AX, DX
	MOVL  BP, R13
	JMP   farin
	PCALIGN $16

farloop:
	MOVQ  Q_SALT, DX

farin:
	MOVQ  (BX), AX
	LEAL  (R13)(BX*1), R11  // idx, rebuilt from the moving pointer
	MOVL  $31, SI
	IMULQ R12, AX
	XORQ  AX, DX
	SHRQ  CX, DX
	MOVL  DX, AX
	SHRL  $8, AX
	SHLL  $5, AX
	PREFETCHT0 (R10)(AX*1)
	LEAQ  (AX*4), DI
	MOVL  R11, AX
	ANDL  $7, AX
	PREFETCHT0 (R8)(DI*1)
	PREFETCHT0 0x40(R8)(DI*1)
	LEAQ  (R14)(AX*4), AX
	MOVL  (AX), BP
	MOVL  DX, (AX)
	MOVL  BP, DX
	SHRL  $8, DX
	SHLL  $5, DX
	LEAQ  (R10)(DX*1), DI
	MOVBLZX (DI), AX
	SUBL  $1, AX
	ANDL  $31, AX
	CMOVLEQ SI, AX
	ADDQ  $1, BX
	MOVB  AX, (DI)
	MOVL  AX, AX
	ADDQ  AX, DX
	MOVB  BP, (DI)(AX*1)
	MOVL  R11, (R8)(DX*4)
	CMPQ  BX, R15
	JNE   farloop
	MOVQ  0x30(SP), R8
	MOVQ  0x38(SP), R13
	MOVL  0x40(SP), R11
	MOVL  0x48(SP), DI
	MOVQ  0x50(SP), SI
	MOVQ  0x10(SP), BX
	MOVQ  0x18(SP), BP

farfill:
	LEAL  -0x20(R13), AX
	LEAQ  1(SI), DX
	LEAQ  (R8)(AX*1), CX
	MOVQ  AX, R10           // idx = target - 32
	CMPQ  DX, CX
	JCS   upd
	MOVQ  DX, AX
	MOVL  $8, DX
	SUBQ  CX, AX
	ADDL  $1, AX
	CMPL  AX, DX
	CMOVLHI DX, AX
	LEAL  (AX)(R10*1), DX
	CMPL  R10, DX
	JCC   upd
	MOVQ  R13, 0x58(SP)
	MOVL  R10, R12
	MOVQ  0x20(SP), R15
	MOVL  DX, 0x40(SP)
	MOVQ  R8, 0x50(SP)
	MOVQ  CX, R8
	MOVL  0x2c(SP), CX
	PCALIGN $16

fill:
	MOVQ  $0xcf1bbcdcbf9b0000, DX
	IMULQ (R8), DX
	ADDQ  $1, R8
	XORQ  R15, DX
	SHRQ  CX, DX
	MOVL  DX, AX
	SHRL  $8, AX
	SHLL  $5, AX
	LEAQ  (AX*4), R13
	PREFETCHT0 (BP)(AX*1)
	MOVL  R12, AX
	ANDL  $7, AX
	ADDL  $1, R12
	PREFETCHT0 (BX)(R13*1)
	PREFETCHT0 0x40(BX)(R13*1)
	MOVL  DX, (R14)(AX*4)
	CMPL  R12, 0x40(SP)
	JCS   fill
	MOVQ  0x50(SP), R8
	MOVQ  0x58(SP), R13
	JMP   upd

cmpdict:
	// C: match = dictBase + matchIndex; read32(match) == read32(ip), then
	// ZSTD_count_2segments(ip+4, match+4, iLimit, dictEnd, prefixStart) + 4.
	// The candidate is at most dictLimit - 4 (C: by table construction;
	// else bad, where the Go code reads past d's slice); lowLimit <= it
	// and lowLimit >= dictBaseIdx (lazyRowExtRun), so it lies in
	// d[lowLimit-dictBaseIdx:dictEnd-4], and the count reads d only up to
	// dictEnd, then b from prefixStart, no further than iLimit from ip.
	MOVL  AX, DI
	MOVL  AX, R11
	SUBL  400(SP), R11
	CMPL  R11, $-3
	JCC   bad
	ADDQ  376(SP), AX       // match
	MOVL  (AX), R11
	CMPL  R11, (SI)
	JNE   next
	MOVQ  BX, 408(SP)
	MOVQ  CX, 416(SP)
	MOVQ  R10, 424(SP)
	MOVQ  DX, 432(SP)
	MOVQ  DI, 440(SP)
	LEAQ  4(SI), R9
	LEAQ  4(AX), R10
	MOVQ  384(SP), R13
	SUBQ  R10, R13
	MOVQ  0(SP), CX
	SUBQ  R9, CX
	CMPQ  CX, R13
	CMOVQLT CX, R13         // min(dictEnd - match, iLimit - ip) bytes
	MOVQ  R10, 448(SP)
	CALL  ·fastCount(SB)
	MOVQ  448(SP), R10
	ADDQ  R11, R10
	CMPQ  R10, 384(SP)
	JNE   dictcnt           // the match ends before dictEnd
	MOVQ  R11, 448(SP)
	LEAQ  4(SI)(R11*1), R9
	MOVQ  392(SP), R10      // it goes on at prefixStart
	MOVQ  0(SP), R13
	SUBQ  R9, R13
	CALL  ·fastCount(SB)
	ADDQ  448(SP), R11

dictcnt:
	LEAQ  4(R11), AX        // currentMl
	MOVQ  408(SP), BX
	MOVQ  416(SP), CX
	MOVQ  424(SP), R10
	MOVQ  432(SP), DX
	MOVQ  440(SP), DI
	JMP   counted

none:
	MOVL  $3, CX
	JMP   done

bad:
	MOVQ  368(SP), R15
	MOVQ  P_B, SI
	MOVQ  $-1, AX
	RET

// func lazyRowExt65(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_extDict_generic (row) for mls 6, rowLog 5:
// compressBlockLazyExtDictGeneric's match loop, with the repcode checks
// (REPLEN), the catch up and the lazy skipping step of the extDict parser.
// R15 = p, SI = b; prefixLowest is unused (the frame holds the segments).
// The repcodes live in the rep1/rep2 argument slots, the anchor and counts in
// their result slots. nSeq = -1 reports a table entry at or after the
// position searched (impossible).
TEXT ·lazyRowExt65(SB), NOSPLIT, $128-128
	MOVQ p+0(FP), R15
	MOVQ P_B, SI
	MOVQ P_DICTBASE, AX
	MOVL P_DICTBASEIDX, CX
	SUBQ CX, AX
	MOVQ AX, L_DBIAS
	MOVL P_LOWEST, CX
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_DSTARTP
	MOVL P_DICTLIMIT, CX
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_DENDP
	MOVQ SI, AX
	MOVL P_BASEIDX, DX
	SUBQ DX, AX
	MOVQ AX, L_BBIAS
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_PSTARTP
	MOVQ iend+40(FP), AX
	ADDQ SI, AX
	MOVQ AX, L_IENDP
	MOVQ ip+24(FP), AX
	MOVQ AX, L_IP
	MOVQ anchor+32(FP), AX
	MOVQ AX, anchorOut+88(FP)
	MOVQ $0, nSeq+96(FP)
	MOVQ $0, nLits+104(FP)
	MOVL $0, llType+120(FP)
	MOVL $0, llPos+124(FP)

main:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  finish
	MOVQ $0, L_MLEN
	MOVQ $1, L_OFFBASE      // repcode1ToOffBase
	LEAQ 1(R8), AX
	MOVQ AX, L_START

	// repcode at ip+1
	INCQ  R8
	MOVL  rep1+64(FP), DX
	REPLEN(r0none, r0c1, r0d1, r0c2, r0d2, r0cd, r0done)
	TESTQ R11, R11
	JEQ   search0
	MOVQ  R11, L_MLEN
	CMPQ  depth+72(FP), $0
	JEQ   store

search0:
	MOVQ L_IP, DI
	CALL ·rowSearchExt65(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, L_MLEN
	JLE  nobetter0
	MOVQ AX, L_MLEN
	MOVQ L_IP, CX
	MOVQ CX, L_START
	MOVQ BX, L_OFFBASE

nobetter0:
	CMPQ L_MLEN, $4
	JGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	MOVQ L_IP, AX
	MOVQ AX, CX
	SUBQ anchorOut+88(FP), CX
	SARQ $8, CX              // kSearchStrength
	LEAQ 1(AX)(CX*1), AX     // ip += step + 1; lazySkipping = step > kLazySkippingStep
	MOVQ AX, L_IP
	XORL DX, DX
	CMPQ CX, $8              // kLazySkippingStep
	SETHI DX
	MOVL DX, P_SKIP
	JMP  main

found:
	CMPQ depth+72(FP), $0
	JEQ  catchup

lazy:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch1
	MOVL  rep1+64(FP), DX
	REPLEN(r1none, r1c1, r1d1, r1c2, r1d2, r1cd, r1done)
	TESTQ R11, R11           // mlRep
	JEQ   lsearch1
	LEAQ  (R11)(R11*2), AX   // gain2
	MOVQ  L_MLEN, CX
	LEAQ  (CX)(CX*2), CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX                 // gain1
	CMPQ  AX, CX
	JLE   lsearch1
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch1:
	MOVQ L_IP, DI
	CALL ·rowSearchExt65(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $4, CX
	CMPQ DX, CX
	JLE  ldepth2
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

ldepth2:
	CMPQ depth+72(FP), $2
	JNE  catchup
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch2
	MOVL  rep1+64(FP), DX
	REPLEN(r2none, r2c1, r2d1, r2c2, r2d2, r2cd, r2done)
	TESTQ R11, R11
	JEQ   lsearch2
	MOVQ  R11, AX
	SHLQ  $2, AX
	MOVQ  L_MLEN, CX
	SHLQ  $2, CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX
	CMPQ  AX, CX
	JLE   lsearch2
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch2:
	MOVQ L_IP, DI
	CALL ·rowSearchExt65(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $7, CX
	CMPQ DX, CX
	JLE  catchup
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

catchup:
	MOVQ L_OFFBASE, DX
	CMPQ DX, $3
	JLS  store              // a repcode: no catch up
	SUBQ $3, DX             // offset
	MOVQ L_START, R8
	MOVQ L_MLEN, AX
	// matchIndex = idx(start) - offset, in the extDict (from dictStart) or
	// the prefix (from prefixStart)
	MOVL    P_BASEIDX, CX
	ADDL    R8, CX
	SUBL    DX, CX
	MOVQ    L_BBIAS, R10
	MOVQ    L_PSTARTP, R9
	CMPL    CX, P_DICTLIMIT
	CMOVQCS L_DBIAS, R10
	CMOVQCS L_DSTARTP, R9
	ADDQ    CX, R10         // match

back:
	CMPQ    R8, anchorOut+88(FP)
	JLE     backdone
	CMPQ    R10, R9
	JLS     backdone
	MOVBLZX -1(SI)(R8*1), BX
	MOVBLZX -1(R10), CX
	CMPL    BX, CX
	JNE     backdone
	DECQ    R8
	DECQ    R10
	INCQ    AX
	JMP     back

backdone:
	MOVQ R8, L_START
	MOVQ AX, L_MLEN
	MOVL rep1+64(FP), CX
	MOVL CX, rep2+68(FP)    // offset2 = offset1
	MOVL DX, rep1+64(FP)    // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVQ L_START, R9
	SUBQ anchorOut+88(FP), R9
	MOVQ L_OFFBASE, R12
	MOVQ L_MLEN, AX
	MOVQ $0, L_RET
	JMP  storeseq

afterstore:
	MOVQ L_START, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	CMPL P_SKIP, $0
	JEQ  reploop
	// leave lazy skipping: ZSTD_row_fillHashCache(ms, base, rowLog, mls, nextToUpdate, ilimit)
	MOVL $0, P_SKIP
	MOVQ P_NEXT, AX
	MOVL (AX), R8            // idx
	MOVL R8, AX
	SUBL P_BASEIDX, AX       // its position
	MOVQ ilimit+48(FP), BX
	SUBQ AX, BX
	JLT  reploop             // idx beyond ilimit: nothing to fill
	INCQ BX
	CMPQ BX, $8
	JLE  fillcnt
	MOVQ $8, BX

fillcnt:
	MOVQ P_CACHE, DX

fillloop:
	MOVL R8, AX
	SUBL P_BASEIDX, AX
	MOVQ (SI)(AX*1), R10
	MOVQ $0xcf1bbcdcbf9b0000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $5, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	PREFETCHT0 64(CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	MOVL R8, AX
	ANDL $7, AX
	MOVL R10, (DX)(AX*4)
	INCL R8
	DECQ BX
	JNE  fillloop

reploop:
	// while ip <= ilimit: ml = repMatchLength(ip, idx(ip), offset2), until 0
	MOVQ  L_IP, R8
	CMPQ  R8, ilimit+48(FP)
	JGT   main
	MOVL  rep2+68(FP), DX
	REPLEN(r3none, r3c1, r3d1, r3c2, r3d2, r3cd, r3done)
	TESTQ R11, R11
	JEQ   main
	MOVQ  R11, AX            // matchLength
	MOVL  rep2+68(FP), CX    // swap repcodes
	MOVL  rep1+64(FP), DX
	MOVL  DX, rep2+68(FP)
	MOVL  CX, rep1+64(FP)
	MOVQ  AX, L_MLEN
	XORL  R9, R9             // no literals
	MOVL  $1, R12            // repcode1ToOffBase
	MOVQ  $1, L_RET
	JMP   storeseq

afterrep:
	MOVQ L_IP, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	JMP  reploop

	// storeseq: R9 litLen (from anchor), R12 offBase, AX matchLength;
	// returns to afterstore (L_RET = 0) or afterrep (L_RET = 1).
storeseq:
	TESTQ R9, R9
	JEQ   seq
	MOVQ  lits+16(FP), R10
	ADDQ  nLits+104(FP), R10
	MOVQ  anchorOut+88(FP), R11
	ADDQ  R9, nLits+104(FP)
	// up to 16 literals: one 16-byte copy (C: ZSTD_storeSeq's ZSTD_copy16).
	// The literal buffer has 16 bytes of slack (the Run functions check),
	// and the source must hold the 16 bytes (else fastCopyLits).
	CMPQ  R9, $16
	JA    litcall
	LEAQ  16(R11), CX
	CMPQ  CX, iend+40(FP)
	JA    litcall
	MOVOU (SI)(R11*1), X0
	MOVOU X0, (R10)
	JMP   seq

litcall:
	ADDQ  SI, R11
	CALL  ·fastCopyLits(SB)

seq:
	MOVQ seqs+8(FP), R10
	MOVQ nSeq+96(FP), R11
	MOVL R12, (R10)(R11*8)
	MOVW R9, 4(R10)(R11*8)
	LEAQ -3(AX), CX
	MOVW CX, 6(R10)(R11*8)
	CMPQ R9, $0xFFFF
	JLS  nolongll
	MOVL $1, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongll:
	CMPQ CX, $0xFFFF
	JLS  nolongml
	MOVL $2, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongml:
	INCQ R11
	MOVQ R11, nSeq+96(FP)
	CMPQ L_RET, $0
	JEQ  afterstore
	JMP  afterrep

finish:
	MOVQ L_IP, AX
	MOVQ AX, ipOut+80(FP)
	MOVL rep1+64(FP), AX
	MOVL AX, rep1Out+112(FP)
	MOVL rep2+68(FP), AX
	MOVL AX, rep2Out+116(FP)
	RET

bad:
	MOVQ $-1, nSeq+96(FP)
	RET

// rowSearchExt66: rowFindBestMatchExtDict (mls 6, rowLog 6) at DI = ip,
// R15 = p: rowSearch66 with the candidates below p.dictLimit read in
// the extDict (see EXTDICT in the header).
// Returns AX = ml (below 4: none; -1: a table entry at or after ip, or in
// the extDict's last 3 bytes, impossible), BX = offBase, SI = b. Clobbers
// everything but R15.
// Frame: as rowSearch66, then 376 d - dictBaseIdx, 384 the address of
// dictEnd, 392 of prefixStart, 400 dictLimit, 408-447 spills, 448 a count.
TEXT ·rowSearchExt66(SB), NOSPLIT, $456-0
	MOVQ R15, 368(SP)
	MOVQ R15, R9
	MOVQ Q_B, SI
	MOVQ SI, DX
	ADDQ DI, SI             // ip
	ADDQ Q_ILIMIT, DX       // iLimit
	MOVL $999999999, 8(SP)  // offBaseNotFound
	MOVQ Q_B, R8
	MOVL Q_BASEIDX, AX
	SUBQ AX, R8             // base: an index addresses it directly
	MOVQ Q_DICTBASE, AX
	MOVL Q_DICTBASEIDX, CX
	SUBQ CX, AX
	MOVQ AX, 376(SP)        // d - dictBaseIdx: an extDict index addresses it
	MOVL Q_DICTLIMIT, CX
	MOVL CX, 400(SP)
	ADDQ CX, AX
	MOVQ AX, 384(SP)        // the address of dictEnd
	LEAQ (R8)(CX*1), AX
	MOVQ AX, 392(SP)        // the address of prefixStart
	MOVQ SI, R13
	MOVQ Q_HASHTABLE, BX
	MOVQ Q_TAGTABLE, BP
	MOVQ DX, 0(SP)
	SUBQ R8, R13            // curr
	MOVL Q_MAXDIST, DX
	MOVL R13, R10
	MOVL R13, CX
	MOVL Q_LOWEST, AX
	SUBL DX, CX
	MOVQ BX, 0x10(SP)
	MOVQ BP, 0x18(SP)
	SUBL AX, R10
	MOVQ R8, 0x30(SP)
	CMPL DX, R10
	MOVL Q_ISDICT, DX
	MOVL R13, 0x28(SP)
	CMOVLCC AX, CX          // withinMaxDistance
	TESTL DX, DX
	MOVL CX, R11
	CMOVLNE AX, R11         // lowLimit = isDictionary ? lowestValid : withinMaxDistance
	MOVQ Q_SALT, AX
	MOVQ AX, 0x20(SP)
	MOVL Q_ATTEMPTS, DI
	MOVQ Q_HSHIFT, AX
	MOVL AX, 0x2c(SP)
	MOVL Q_SKIP, CX
	TESTL CX, CX
	JNE  skipping
	MOVQ Q_NEXT, AX
	MOVL (AX), R10          // idx = nextToUpdate
	MOVL R13, AX
	MOVQ Q_CACHE, R14
	SUBL R10, AX
	CMPL AX, $0x180         // kSkipThreshold
	JHI  far

upd:
	// ZSTD_row_update_internalImpl for [R10, R13)
	CMPL R10, R13
	JCC  hash
	MOVQ 0x30(SP), DX
	MOVQ R13, 0x38(SP)
	MOVL 0x2c(SP), CX
	MOVL R10, AX
	MOVQ R8, 0x30(SP)
	MOVQ $0xcf1bbcdcbf9b0000, R15
	MOVL DI, 0x40(SP)
	LEAQ 8(DX)(AX*1), R12
	MOVQ SI, 0x48(SP)
	MOVL 0x28(SP), SI
	MOVQ 0x20(SP), R9       // salt (p is reloaded after the loop)
	MOVL $63, DI
	PCALIGN $16

updloop:
	MOVQ  (R12), DX
	IMULQ R15, DX
	XORQ  R9, DX
	SHRQ  CX, DX            // newHash
	MOVL  DX, AX
	SHRL  $8, AX
	SHLL  $6, AX
	PREFETCHT0 (BP)(AX*1)
	PREFETCHT0 0x20(BP)(AX*1)
	PREFETCHT0 (BX)(AX*4)
	PREFETCHT0 0x40(BX)(AX*4)
	MOVL  R10, R8
	ANDL  $7, R8
	MOVL  (R14)(R8*4), R13  // hash
	MOVL  DX, (R14)(R8*4)
	MOVL  R13, DX
	SHRL  $8, DX
	SHLL  $6, DX       // relRow
	MOVBLZX (BP)(DX*1), AX
	SUBL  $1, AX
	ANDL  $63, AX
	CMOVLEQ DI, AX          // head 0 wraps to rowMask
	MOVB  AX, (BP)(DX*1)
	ADDQ  AX, DX
	MOVB  R13, (BP)(DX*1)
	MOVL  R10, (BX)(DX*4)
	ADDQ  $1, R12
	ADDL  $1, R10
	CMPL  SI, R10
	JNE   updloop
	MOVQ  368(SP), R9
	MOVQ  0x30(SP), R8
	MOVQ  0x38(SP), R13
	MOVL  0x40(SP), DI
	MOVQ  0x48(SP), SI

hash:
	// hash = ZSTD_row_nextCachedHash(curr); nextToUpdate = curr
	MOVL  R13, DX
	MOVQ  0x20(SP), BX
	MOVBLZX 0x2c(SP), CX
	MOVQ  $0xcf1bbcdcbf9b0000, AX
	IMULQ 8(R8)(DX*1), AX
	MOVQ  Q_NEXT, R12
	MOVL  R13, (R12)
	XORQ  BX, AX
	MOVQ  0x10(SP), BX
	SHRQ  CX, AX
	MOVL  AX, DX
	SHRL  $8, DX
	SHLL  $6, DX
	LEAQ  (DX*4), CX
	PREFETCHT0 (BX)(CX*1)
	PREFETCHT0 0x40(BX)(CX*1)
	MOVQ  0x18(SP), BX
	PREFETCHT0 (BX)(DX*1)
	PREFETCHT0 0x20(BX)(DX*1)
	MOVQ  R13, DX
	ANDL  $7, DX
	LEAQ  (R14)(DX*4), DX
	MOVL  (DX), R12
	MOVL  AX, (DX)

havehash:
	MOVL  R12, BX
	MOVQ  0x10(SP), AX
	MOVQ  R12, X0
	MOVQ  Q_ENTROPY, CX
	ADDL  R12, (CX)         // collect salt entropy
	SHRL  $8, BX
	PUNPCKLBW X0, X0
	SHLL  $6, BX       // relRow
	PUNPCKLWL X0, X0
	LEAQ  (AX)(BX*4), BP    // row
	MOVQ  0x18(SP), AX
	PSHUFL $0, X0, X0
	ADDQ  BX, AX            // tagRow

	// matches: tags equal to tag, rotated right by headGrouped (C: ZSTD_row_getSSEMask)
	MOVOU (AX), X2
	MOVOU 0x10(AX), X1
	MOVQ  AX, BX
	MOVOU 0x20(AX), X3
	MOVOU 0x30(AX), X4
	PCMPEQB X0, X2
	PCMPEQB X0, X1
	MOVBLZX (AX), CX
	PCMPEQB X0, X3
	PCMPEQB X4, X0
	MOVL  CX, R13
	ANDL  $0x3f, R13        // headGrouped
	PMOVMSKB X0, R10
	PMOVMSKB X3, AX
	SHLQ  $0x20, AX
	SHLQ  $0x30, R10
	ORQ   AX, R10
	PMOVMSKB X2, AX
	ORQ   AX, R10
	PMOVMSKB X1, AX
	SHLQ  $0x10, AX
	ORQ   AX, R10
	CMPB  ·useRowBMI(SB), $0
	JEQ   slow
	CMPL  DI, $63
	JCS   slow              // nbAttempts < rowEntries - 1: C's loop
	ANDQ  $-2, R10          // the head entry is never a candidate
	MOVQ  R10, DX
	RORQ  CX, DX
	TESTQ R10, R10
	JEQ   insert
	MOVL  0x28(SP), R15     // curr
	XORL  R10, R10
	PCALIGN $16

gfast:
	XORL  AX, AX
	TZCNTQ DX, AX  // DX != 0 here and below: TZCNT runs as BSF without BMI1, same result
	ADDL  R13, AX
	ANDL  $63, AX    // matchPos
	MOVL  (BP)(AX*4), R14   // matchIndex
	CMPL  R14, R11
	JCS   insert            // below lowLimit: stop
	// Bounds: lowLimit <= R14 < curr, and lowLimit >= baseIdx (rowAsmSetup
	// checks lowestValid >= baseIdx, and lazyRowRun lowestValid <= curr, so
	// curr - lowestValid does not wrap and curr - maxDistance is used only
	// when it is above lowestValid). So R8 + R14 lies in b[0:ip], and the
	// compare and count below read only b[R14-baseIdx:] up to the
	// iLimit - ip bytes that b[ip:] holds. Only buffered candidates are
	// read, and every one passed this check, so the compare loop needs none.
	CMPL  R14, R15
	JCC   bad
	MOVQ  R8, AX
	CMPL  R14, 400(SP)
	CMOVQCS 376(SP), AX     // the candidate's segment
	PREFETCHT0 (AX)(R14*1)
	MOVL  R14, 0x60(SP)(R10*4)
	ADDQ  $1, R10
	BLSRQ DX, DX
	JNE   gfast
	JMP   insert

slow:
	MOVQ  R10, DX
	RORQ  CX, DX
	TESTQ R10, R10
	JEQ   insert

gslow:
	XORL  R10, R10
	JMP   gnext
	PCALIGN $16

gtake:
	CMPL  R14, 0x28(SP)     // idx < curr (see gfast)
	JCC   bad
	SUBL  $1, DI
	MOVQ  R8, AX
	CMPL  R14, 400(SP)
	CMOVQCS 376(SP), AX     // the candidate's segment
	PREFETCHT0 (AX)(R14*1)
	MOVL  R14, 0x60(SP)(R10*4)
	ADDQ  $1, R10

gskip:
	LEAQ  -1(DX), AX
	ANDQ  AX, DX
	JEQ   insert
	TESTL DI, DI
	JEQ   insert

gnext:
	XORL  AX, AX
	TZCNTQ DX, AX  // DX != 0 (TZCNT = BSF without BMI1)
	ADDL  R13, AX
	ANDL  $63, AX
	MOVL  AX, R14
	MOVL  (BP)(R14*4), R14
	JEQ   gskip             // matchPos 0 is the head entry
	CMPL  R14, R11
	JCC   gtake

insert:
	// insert curr (nextToUpdate) into the row; nextToUpdate++
	LEAL  63(CX), AX  // (head - 1) & rowMask, CX the raw head byte
	MOVL  $63, DX
	ANDL  $63, AX
	CMOVLEQ DX, AX
	MOVB  AX, (BX)
	MOVL  AX, AX
	MOVB  R12, (BX)(AX*1)
	MOVQ  Q_NEXT, DI
	MOVL  (DI), DX
	LEAL  1(DX), CX
	MOVL  CX, (DI)
	MOVL  DX, (BP)(AX*4)
	TESTQ R10, R10
	JEQ   none
	MOVQ  0(SP), AX
	MOVL  0x28(SP), BP
	MOVL  $3, CX            // ml
	XORL  DX, DX
	LEAQ  0x60(SP), BX
	LEAQ  -7(AX), R12  // iLimit - 7, -3, -1: ZSTD_count's 8, 4, 2-byte step limits
	ADDL  $3, BP
	LEAQ  -3(AX), R15
	LEAQ  -1(AX), R14
	JMP   cmp
	PCALIGN $16

next:
	ADDQ  $1, DX
	CMPQ  DX, R10
	JEQ   done

cmp:
	MOVL  (BX)(DX*4), AX
	CMPL  AX, 400(SP)
	JCS   cmpdict           // an extDict candidate
	MOVL  -3(SI)(CX*1), R11
	MOVQ  AX, DI
	ADDQ  R8, AX            // match
	CMPL  -3(AX)(CX*1), R11
	JNE   next
	// ZSTD_count(ip, match, iLimit)
	CMPQ  SI, R12
	JCC   cnt4ip
	MOVQ  (AX), R9
	MOVQ  (SI), R11
	CMPQ  R9, R11
	JEQ   cnt8
	XORQ  R11, R9
	XORL  AX, AX
	TZCNTQ R9, AX  // R9 != 0 (TZCNT = BSF without BMI1)
	SHRL  $3, AX

counted:
	CMPQ  CX, AX
	JCC   next
	MOVL  BP, CX
	SUBL  DI, CX
	MOVL  CX, 8(SP)         // offBase = curr - matchIndex + REP_NUM
	LEAQ  (SI)(AX*1), CX
	CMPQ  0(SP), CX
	MOVQ  AX, CX
	JNE   next              // ip + ml == iLimit: the best possible

done:
	MOVQ  CX, AX
	MOVL  8(SP), BX
	MOVQ  368(SP), R15
	MOVQ  P_B, SI
	RET
	PCALIGN $16

cnt4ip:
	MOVQ  SI, R11

cnt4:
	CMPQ  R11, R15
	JCC   cnt2
	MOVL  (R11), R9
	CMPL  (AX), R9
	JNE   cnt2
	ADDQ  $4, R11
	ADDQ  $4, AX
	PCALIGN $16

cnt2:
	CMPQ  R11, R14
	JCC   cnt1
	MOVWLZX (R11), R9
	CMPW  (AX), R9
	JNE   cnt1
	ADDQ  $2, R11
	ADDQ  $2, AX
	PCALIGN $16

cnt1:
	MOVQ  0(SP), R9
	CMPQ  R11, R9
	JCC   cntend
	MOVBLZX (R11), R9
	CMPB  (AX), R9
	SETEQ AL
	MOVBLZX AL, AX
	ADDQ  AX, R11

cntend:
	MOVQ  R11, AX
	SUBQ  SI, AX
	JMP   counted
	PCALIGN $8

cnt8:
	LEAQ  8(SI), R11
	ADDQ  $8, AX
	CMPB  ·useAVX2(SB), $0
	JEQ   cnt8chk

cnt32:
	// 32 bytes per step with AVX2 (as fastCount), while R11 + 32 <= iLimit
	LEAQ  32(R11), R9
	CMPQ  R9, 0(SP)
	JHI   cnt32end
	VMOVDQU   (R11), Y0
	VPCMPEQB  (AX), Y0, Y0
	VPMOVMSKB Y0, R9
	INCL  R9
	JNE   cnt32diff
	ADDQ  $32, R11
	ADDQ  $32, AX
	JMP   cnt32

cnt32diff:
	VZEROUPPER
	BSFL  R9, R9
	LEAQ  (R11)(R9*1), AX
	SUBQ  SI, AX
	JMP   counted

cnt32end:
	VZEROUPPER

cnt8chk:
	CMPQ  R11, R12
	JCC   cnt4

cnt8loop:
	MOVQ  (AX), R9
	MOVQ  (R11), R13
	CMPQ  R9, R13
	JEQ   cnt8next
	XORQ  R13, R9
	XORL  AX, AX
	TZCNTQ R9, AX  // R9 != 0 (TZCNT = BSF without BMI1)
	SHRL  $3, AX
	ADDQ  R11, AX
	SUBQ  SI, AX
	JMP   counted
	PCALIGN $16

skipping:
	// lazy skipping: hash ip directly, without the cache or the row update
	MOVQ  $0xcf1bbcdcbf9b0000, R12
	IMULQ (SI), R12
	MOVQ  0x20(SP), AX
	MOVQ  Q_NEXT, CX
	MOVL  R13, (CX)         // nextToUpdate = curr
	MOVBLZX 0x2c(SP), CX
	XORQ  AX, R12
	SHRQ  CX, R12
	JMP   havehash
	PCALIGN $16

cnt8next:
	ADDQ  $8, R11
	ADDQ  $8, AX
	CMPQ  R11, R12
	JCS   cnt8loop
	JMP   cnt4

far:
	// target - idx > kSkipThreshold: update [idx, idx + 96), then refill the
	// cache from target - 32 (C: ZSTD_row_fillHashCache, up to ip + 1)
	CMPL  R10, $0xffffff9f  // idx + kMaxMatchStartPositionsToUpdate (96) would wrap: skip
	JHI   farfill
	MOVL  R10, AX
	MOVQ  R13, 0x38(SP)
	MOVL  0x2c(SP), CX
	MOVQ  $0xcf1bbcdcbf9b0000, R12
	LEAQ  8(R8)(AX*1), BX
	LEAQ  0x68(R8)(AX*1), R15
	MOVQ  0x20(SP), AX
	MOVL  R11, 0x40(SP)
	SUBL  BX, R10  // idx - pointer (mod 2^32), kept in R13: idx = R13 + pointer
	MOVL  DI, 0x48(SP)
	MOVQ  0x10(SP), R8
	MOVL  R10, BP
	MOVQ  SI, 0x50(SP)
	MOVQ  0x18(SP), R10
	MOVQ  AX, DX
	MOVL  BP, R13
	JMP   farin
	PCALIGN $16

farloop:
	MOVQ  Q_SALT, DX

farin:
	MOVQ  (BX), AX
	LEAL  (R13)(BX*1), R11  // idx, rebuilt from the moving pointer
	MOVL  $63, SI
	IMULQ R12, AX
	XORQ  AX, DX
	SHRQ  CX, DX
	MOVL  DX, AX
	SHRL  $8, AX
	SHLL  $6, AX
	PREFETCHT0 (R10)(AX*1)
	PREFETCHT0 0x20(R10)(AX*1)
	LEAQ  (AX*4), DI
	MOVL  R11, AX
	ANDL  $7, AX
	PREFETCHT0 (R8)(DI*1)
	PREFETCHT0 0x40(R8)(DI*1)
	LEAQ  (R14)(AX*4), AX
	MOVL  (AX), BP
	MOVL  DX, (AX)
	MOVL  BP, DX
	SHRL  $8, DX
	SHLL  $6, DX
	LEAQ  (R10)(DX*1), DI
	MOVBLZX (DI), AX
	SUBL  $1, AX
	ANDL  $63, AX
	CMOVLEQ SI, AX
	ADDQ  $1, BX
	MOVB  AX, (DI)
	MOVL  AX, AX
	ADDQ  AX, DX
	MOVB  BP, (DI)(AX*1)
	MOVL  R11, (R8)(DX*4)
	CMPQ  BX, R15
	JNE   farloop
	MOVQ  0x30(SP), R8
	MOVQ  0x38(SP), R13
	MOVL  0x40(SP), R11
	MOVL  0x48(SP), DI
	MOVQ  0x50(SP), SI
	MOVQ  0x10(SP), BX
	MOVQ  0x18(SP), BP

farfill:
	LEAL  -0x20(R13), AX
	LEAQ  1(SI), DX
	LEAQ  (R8)(AX*1), CX
	MOVQ  AX, R10           // idx = target - 32
	CMPQ  DX, CX
	JCS   upd
	MOVQ  DX, AX
	MOVL  $8, DX
	SUBQ  CX, AX
	ADDL  $1, AX
	CMPL  AX, DX
	CMOVLHI DX, AX
	LEAL  (AX)(R10*1), DX
	CMPL  R10, DX
	JCC   upd
	MOVQ  R13, 0x58(SP)
	MOVL  R10, R12
	MOVQ  0x20(SP), R15
	MOVL  DX, 0x40(SP)
	MOVQ  R8, 0x50(SP)
	MOVQ  CX, R8
	MOVL  0x2c(SP), CX
	PCALIGN $16

fill:
	MOVQ  $0xcf1bbcdcbf9b0000, DX
	IMULQ (R8), DX
	ADDQ  $1, R8
	XORQ  R15, DX
	SHRQ  CX, DX
	MOVL  DX, AX
	SHRL  $8, AX
	SHLL  $6, AX
	LEAQ  (AX*4), R13
	PREFETCHT0 (BP)(AX*1)
	PREFETCHT0 0x20(BP)(AX*1)
	MOVL  R12, AX
	ANDL  $7, AX
	ADDL  $1, R12
	PREFETCHT0 (BX)(R13*1)
	PREFETCHT0 0x40(BX)(R13*1)
	MOVL  DX, (R14)(AX*4)
	CMPL  R12, 0x40(SP)
	JCS   fill
	MOVQ  0x50(SP), R8
	MOVQ  0x58(SP), R13
	JMP   upd

cmpdict:
	// C: match = dictBase + matchIndex; read32(match) == read32(ip), then
	// ZSTD_count_2segments(ip+4, match+4, iLimit, dictEnd, prefixStart) + 4.
	// The candidate is at most dictLimit - 4 (C: by table construction;
	// else bad, where the Go code reads past d's slice); lowLimit <= it
	// and lowLimit >= dictBaseIdx (lazyRowExtRun), so it lies in
	// d[lowLimit-dictBaseIdx:dictEnd-4], and the count reads d only up to
	// dictEnd, then b from prefixStart, no further than iLimit from ip.
	MOVL  AX, DI
	MOVL  AX, R11
	SUBL  400(SP), R11
	CMPL  R11, $-3
	JCC   bad
	ADDQ  376(SP), AX       // match
	MOVL  (AX), R11
	CMPL  R11, (SI)
	JNE   next
	MOVQ  BX, 408(SP)
	MOVQ  CX, 416(SP)
	MOVQ  R10, 424(SP)
	MOVQ  DX, 432(SP)
	MOVQ  DI, 440(SP)
	LEAQ  4(SI), R9
	LEAQ  4(AX), R10
	MOVQ  384(SP), R13
	SUBQ  R10, R13
	MOVQ  0(SP), CX
	SUBQ  R9, CX
	CMPQ  CX, R13
	CMOVQLT CX, R13         // min(dictEnd - match, iLimit - ip) bytes
	MOVQ  R10, 448(SP)
	CALL  ·fastCount(SB)
	MOVQ  448(SP), R10
	ADDQ  R11, R10
	CMPQ  R10, 384(SP)
	JNE   dictcnt           // the match ends before dictEnd
	MOVQ  R11, 448(SP)
	LEAQ  4(SI)(R11*1), R9
	MOVQ  392(SP), R10      // it goes on at prefixStart
	MOVQ  0(SP), R13
	SUBQ  R9, R13
	CALL  ·fastCount(SB)
	ADDQ  448(SP), R11

dictcnt:
	LEAQ  4(R11), AX        // currentMl
	MOVQ  408(SP), BX
	MOVQ  416(SP), CX
	MOVQ  424(SP), R10
	MOVQ  432(SP), DX
	MOVQ  440(SP), DI
	JMP   counted

none:
	MOVL  $3, CX
	JMP   done

bad:
	MOVQ  368(SP), R15
	MOVQ  P_B, SI
	MOVQ  $-1, AX
	RET

// func lazyRowExt66(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_extDict_generic (row) for mls 6, rowLog 6:
// compressBlockLazyExtDictGeneric's match loop, with the repcode checks
// (REPLEN), the catch up and the lazy skipping step of the extDict parser.
// R15 = p, SI = b; prefixLowest is unused (the frame holds the segments).
// The repcodes live in the rep1/rep2 argument slots, the anchor and counts in
// their result slots. nSeq = -1 reports a table entry at or after the
// position searched (impossible).
TEXT ·lazyRowExt66(SB), NOSPLIT, $128-128
	MOVQ p+0(FP), R15
	MOVQ P_B, SI
	MOVQ P_DICTBASE, AX
	MOVL P_DICTBASEIDX, CX
	SUBQ CX, AX
	MOVQ AX, L_DBIAS
	MOVL P_LOWEST, CX
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_DSTARTP
	MOVL P_DICTLIMIT, CX
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_DENDP
	MOVQ SI, AX
	MOVL P_BASEIDX, DX
	SUBQ DX, AX
	MOVQ AX, L_BBIAS
	LEAQ (AX)(CX*1), DX
	MOVQ DX, L_PSTARTP
	MOVQ iend+40(FP), AX
	ADDQ SI, AX
	MOVQ AX, L_IENDP
	MOVQ ip+24(FP), AX
	MOVQ AX, L_IP
	MOVQ anchor+32(FP), AX
	MOVQ AX, anchorOut+88(FP)
	MOVQ $0, nSeq+96(FP)
	MOVQ $0, nLits+104(FP)
	MOVL $0, llType+120(FP)
	MOVL $0, llPos+124(FP)

main:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  finish
	MOVQ $0, L_MLEN
	MOVQ $1, L_OFFBASE      // repcode1ToOffBase
	LEAQ 1(R8), AX
	MOVQ AX, L_START

	// repcode at ip+1
	INCQ  R8
	MOVL  rep1+64(FP), DX
	REPLEN(r0none, r0c1, r0d1, r0c2, r0d2, r0cd, r0done)
	TESTQ R11, R11
	JEQ   search0
	MOVQ  R11, L_MLEN
	CMPQ  depth+72(FP), $0
	JEQ   store

search0:
	MOVQ L_IP, DI
	CALL ·rowSearchExt66(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, L_MLEN
	JLE  nobetter0
	MOVQ AX, L_MLEN
	MOVQ L_IP, CX
	MOVQ CX, L_START
	MOVQ BX, L_OFFBASE

nobetter0:
	CMPQ L_MLEN, $4
	JGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	MOVQ L_IP, AX
	MOVQ AX, CX
	SUBQ anchorOut+88(FP), CX
	SARQ $8, CX              // kSearchStrength
	LEAQ 1(AX)(CX*1), AX     // ip += step + 1; lazySkipping = step > kLazySkippingStep
	MOVQ AX, L_IP
	XORL DX, DX
	CMPQ CX, $8              // kLazySkippingStep
	SETHI DX
	MOVL DX, P_SKIP
	JMP  main

found:
	CMPQ depth+72(FP), $0
	JEQ  catchup

lazy:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch1
	MOVL  rep1+64(FP), DX
	REPLEN(r1none, r1c1, r1d1, r1c2, r1d2, r1cd, r1done)
	TESTQ R11, R11           // mlRep
	JEQ   lsearch1
	LEAQ  (R11)(R11*2), AX   // gain2
	MOVQ  L_MLEN, CX
	LEAQ  (CX)(CX*2), CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX                 // gain1
	CMPQ  AX, CX
	JLE   lsearch1
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch1:
	MOVQ L_IP, DI
	CALL ·rowSearchExt66(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $4, CX
	CMPQ DX, CX
	JLE  ldepth2
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

ldepth2:
	CMPQ depth+72(FP), $2
	JNE  catchup
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch2
	MOVL  rep1+64(FP), DX
	REPLEN(r2none, r2c1, r2d1, r2c2, r2d2, r2cd, r2done)
	TESTQ R11, R11
	JEQ   lsearch2
	MOVQ  R11, AX
	SHLQ  $2, AX
	MOVQ  L_MLEN, CX
	SHLQ  $2, CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX
	CMPQ  AX, CX
	JLE   lsearch2
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch2:
	MOVQ L_IP, DI
	CALL ·rowSearchExt66(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $7, CX
	CMPQ DX, CX
	JLE  catchup
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

catchup:
	MOVQ L_OFFBASE, DX
	CMPQ DX, $3
	JLS  store              // a repcode: no catch up
	SUBQ $3, DX             // offset
	MOVQ L_START, R8
	MOVQ L_MLEN, AX
	// matchIndex = idx(start) - offset, in the extDict (from dictStart) or
	// the prefix (from prefixStart)
	MOVL    P_BASEIDX, CX
	ADDL    R8, CX
	SUBL    DX, CX
	MOVQ    L_BBIAS, R10
	MOVQ    L_PSTARTP, R9
	CMPL    CX, P_DICTLIMIT
	CMOVQCS L_DBIAS, R10
	CMOVQCS L_DSTARTP, R9
	ADDQ    CX, R10         // match

back:
	CMPQ    R8, anchorOut+88(FP)
	JLE     backdone
	CMPQ    R10, R9
	JLS     backdone
	MOVBLZX -1(SI)(R8*1), BX
	MOVBLZX -1(R10), CX
	CMPL    BX, CX
	JNE     backdone
	DECQ    R8
	DECQ    R10
	INCQ    AX
	JMP     back

backdone:
	MOVQ R8, L_START
	MOVQ AX, L_MLEN
	MOVL rep1+64(FP), CX
	MOVL CX, rep2+68(FP)    // offset2 = offset1
	MOVL DX, rep1+64(FP)    // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVQ L_START, R9
	SUBQ anchorOut+88(FP), R9
	MOVQ L_OFFBASE, R12
	MOVQ L_MLEN, AX
	MOVQ $0, L_RET
	JMP  storeseq

afterstore:
	MOVQ L_START, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	CMPL P_SKIP, $0
	JEQ  reploop
	// leave lazy skipping: ZSTD_row_fillHashCache(ms, base, rowLog, mls, nextToUpdate, ilimit)
	MOVL $0, P_SKIP
	MOVQ P_NEXT, AX
	MOVL (AX), R8            // idx
	MOVL R8, AX
	SUBL P_BASEIDX, AX       // its position
	MOVQ ilimit+48(FP), BX
	SUBQ AX, BX
	JLT  reploop             // idx beyond ilimit: nothing to fill
	INCQ BX
	CMPQ BX, $8
	JLE  fillcnt
	MOVQ $8, BX

fillcnt:
	MOVQ P_CACHE, DX

fillloop:
	MOVL R8, AX
	SUBL P_BASEIDX, AX
	MOVQ (SI)(AX*1), R10
	MOVQ $0xcf1bbcdcbf9b0000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $6, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	PREFETCHT0 64(CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	PREFETCHT0 32(R11)
	MOVL R8, AX
	ANDL $7, AX
	MOVL R10, (DX)(AX*4)
	INCL R8
	DECQ BX
	JNE  fillloop

reploop:
	// while ip <= ilimit: ml = repMatchLength(ip, idx(ip), offset2), until 0
	MOVQ  L_IP, R8
	CMPQ  R8, ilimit+48(FP)
	JGT   main
	MOVL  rep2+68(FP), DX
	REPLEN(r3none, r3c1, r3d1, r3c2, r3d2, r3cd, r3done)
	TESTQ R11, R11
	JEQ   main
	MOVQ  R11, AX            // matchLength
	MOVL  rep2+68(FP), CX    // swap repcodes
	MOVL  rep1+64(FP), DX
	MOVL  DX, rep2+68(FP)
	MOVL  CX, rep1+64(FP)
	MOVQ  AX, L_MLEN
	XORL  R9, R9             // no literals
	MOVL  $1, R12            // repcode1ToOffBase
	MOVQ  $1, L_RET
	JMP   storeseq

afterrep:
	MOVQ L_IP, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	JMP  reploop

	// storeseq: R9 litLen (from anchor), R12 offBase, AX matchLength;
	// returns to afterstore (L_RET = 0) or afterrep (L_RET = 1).
storeseq:
	TESTQ R9, R9
	JEQ   seq
	MOVQ  lits+16(FP), R10
	ADDQ  nLits+104(FP), R10
	MOVQ  anchorOut+88(FP), R11
	ADDQ  R9, nLits+104(FP)
	// up to 16 literals: one 16-byte copy (C: ZSTD_storeSeq's ZSTD_copy16).
	// The literal buffer has 16 bytes of slack (the Run functions check),
	// and the source must hold the 16 bytes (else fastCopyLits).
	CMPQ  R9, $16
	JA    litcall
	LEAQ  16(R11), CX
	CMPQ  CX, iend+40(FP)
	JA    litcall
	MOVOU (SI)(R11*1), X0
	MOVOU X0, (R10)
	JMP   seq

litcall:
	ADDQ  SI, R11
	CALL  ·fastCopyLits(SB)

seq:
	MOVQ seqs+8(FP), R10
	MOVQ nSeq+96(FP), R11
	MOVL R12, (R10)(R11*8)
	MOVW R9, 4(R10)(R11*8)
	LEAQ -3(AX), CX
	MOVW CX, 6(R10)(R11*8)
	CMPQ R9, $0xFFFF
	JLS  nolongll
	MOVL $1, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongll:
	CMPQ CX, $0xFFFF
	JLS  nolongml
	MOVL $2, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongml:
	INCQ R11
	MOVQ R11, nSeq+96(FP)
	CMPQ L_RET, $0
	JEQ  afterstore
	JMP  afterrep

finish:
	MOVQ L_IP, AX
	MOVQ AX, ipOut+80(FP)
	MOVL rep1+64(FP), AX
	MOVL AX, rep1Out+112(FP)
	MOVL rep2+68(FP), AX
	MOVL AX, rep2Out+116(FP)
	RET

bad:
	MOVQ $-1, nSeq+96(FP)
	RET
